-- 623 позиций каталога (327 технологий + 296 соц. концепций)
INSERT INTO technologies
  (id, tree_id, code, name, branch_id, default_era_id, is_standard,
   image_path, description, historical_note) VALUES
  (1, 1, 't_tools', 'Орудия труда', 1, 1, 1, 'uploads/tech/stone/tools.svg', 'Первые обработанные орудия: рубила, отщепы, скребки. Основа всех ремёсел.', 'Древнейшие каменные орудия олдувайской традиции известны из Восточной Африки и датируются возрастом порядка 2,6 миллиона лет: у гальки скалывали несколько отщепов, получая режущую кромку.

Ашельское ручное рубило изготавливали уже по единому замыслу, и устойчивость этой формы на протяжении сотен тысяч лет говорит о том, что приёмы передавались из поколения в поколение — то есть о существовании обучения.

От орудий труда расходится всё остальное: ими разделывали добычу, обрабатывали дерево и кость, готовили шкуры, копали и строили. Сам век получил название по материалу этих орудий.'),
  (2, 1, 't_fire', 'Разведение огня', 2, 1, 1, 'uploads/tech/stone/fire.svg', 'Управляемый огонь: тепло, свет, защита от зверя и тепловая обработка пищи.', 'Древнейшие следы использования огня относят к периоду порядка миллиона лет назад. Долгое время огонь только сохраняли — угли поддерживали в очаге и переносили при перекочёвках; умение добывать его трением или высеканием искры появилось значительно позже и стало настоящим рубежом.

Термическая обработка резко повысила усвояемость пищи: варёные и печёные клубни и мясо дают заметно больше калорий, чем сырые. С приготовлением пищи связывают уменьшение челюстного аппарата и рост объёма мозга у наших предков.

Освещённый вечер удлинил время бодрствования, и очаг стал местом, вокруг которого складывались рассказ и обмен опытом.'),
  (3, 1, 't_gathering', 'Собирательство', 3, 1, 1, 'uploads/tech/stone/gathering.svg', 'Сбор растительной пищи: корней, плодов, ягод, орехов, мёда.', 'Вопреки образу «человека-охотника», основную часть пищи в большинстве известных этнографам обществ давало именно собирательство: растительная еда предсказуема и добывается почти каждый день, тогда как крупная охота часто заканчивается ничем.

Собирательство требует огромного объёма знаний — какие растения съедобны, в какой месяц созревают, как обезвредить горечь вымачиванием или обжигом. Этот массив сведений хранился в устной традиции.

Именно тысячелетия наблюдений за дикими злаками стали дорогой к земледелию.'),
  (4, 1, 't_hunt', 'Охота', 3, 1, 1, 'uploads/tech/stone/hunt.svg', 'Организованная добыча зверя: загон, засада, коллективные приёмы и разделка туш.', 'Охота на крупного зверя требовала не столько силы, сколько согласованности. Загонная охота, при которой часть группы гонит стадо к обрыву или в узкое ущелье, известна по стоянкам с огромными скоплениями костей.

Добыча давала не только мясо: шкуры шли на одежду и покрытия жилищ, сухожилия — на нити и тетиву, кости и рога — на орудия и иглы, жир — на светильники. Крупное животное использовалось практически целиком.

Дележ добычи по правилам — один из древнейших известных механизмов распределения, а удачливый охотник получал в группе особый статус.'),
  (5, 1, 't_speech', 'Речь', 4, 1, 1, 'uploads/tech/stone/speech.svg', 'Членораздельный язык: передача сложных сведений, замысла и опыта.', 'О времени появления речи спорят: анатомические признаки — строение гортани, подъязычная кость, размеры канала подъязычного нерва — говорят о готовности речевого аппарата задолго до появления искусства и погребений.

Косвенные доводы дают сами технологии. Изготовление составного орудия или организация загонной охоты требуют согласования замысла, который нельзя показать жестом целиком.

Речь сделала возможным накопление: знание перестало умирать вместе с человеком и стало передаваться, уточняться и исправляться поколениями.'),
  (6, 1, 't_knapping', 'Обработка камня и кости', 1, 1, 1, 'uploads/tech/stone/knapping.svg', 'Тонкая обработка материалов: отжимная ретушь, сверление, резьба по кости.', 'Если первые орудия получали грубым скалыванием, то в верхнем палеолите техника стала ювелирной. Отжимная ретушь — снятие тончайших чешуек нажатием костяного отжимника — позволяла доводить кромку до бритвенной остроты.

Освоение кости, рога и бивня открыло свойства, которых у камня нет: вязкость и способность гнуться. Из них делали иглы с ушком, гарпуны с зазубринами, копьеметалки, рыболовные крючки и застёжки.

Хорошее сырьё ценилось: обсидиан и качественный кремень переносили на сотни километров, и карты таких находок фактически рисуют древнейшие торговые пути.'),
  (7, 1, 't_cordage', 'Плетение и верёвки', 5, 1, 1, 'uploads/tech/stone/cordage.svg', 'Скручивание верёвок и плетение корзин, циновок и сетей из растительных волокон.', 'Верёвка — одна из самых недооценённых технологий древности. Без неё нет ни лука, ни сети, ни составного орудия, ни надёжного крепления жердей в жилище.

Волокно получали из крапивы, липового лыка, конопли и сухожилий. Скручивание в двух направлениях даёт нить, которая не раскручивается сама; этот приём известен с верхнего палеолита — найден фрагмент витой верёвки, изготовленной неандертальцами.

Плетение древнее ткачества и стало для него прообразом: принцип переплетения основы и утка сначала отработали на прутьях и полосах коры.'),
  (8, 1, 't_hides', 'Выделка шкур', 5, 1, 1, 'uploads/tech/stone/hides.svg', 'Очистка, мездрение и дубление шкур: одежда и покрытия для жилищ.', 'Сырая шкура быстро загнивает и на морозе дубеет, поэтому нужна цепочка операций: снять, отскоблить мездру скребком, растянуть на раме, размять и обработать составом, не дающим ей загнивать.

Древнейший способ — жировое дубление: шкуру пропитывали мозгом и жиром животного, а затем долго мяли и коптили над дымным костром.

Косвенное свидетельство появления одежды дают паразитологи: платяная вошь, живущая только в складках одежды, отделилась от головной десятки тысяч лет назад, и эта дата считается ориентиром.'),
  (9, 1, 't_pottery', 'Гончарное дело', 6, 1, 1, 'uploads/tech/stone/pottery.svg', 'Лепка и обжиг глиняной посуды: варка, хранение зерна и жидкостей.', 'Обжиг превращает пластичную глину в керамику — материал, который не размокает и держит воду. Древнейшая керамика найдена в Восточной Азии и старше земледелия: её делали ещё охотники-собиратели.

Горшок изменил кухню: в нём можно долго варить, а значит, использовать жёсткое мясо, крупу и коренья, которые иначе несъедобны. Это особенно важно для питания детей и стариков.

Керамика стала главным материалом археологии: черепки не гниют и не переплавляются, а форма и орнамент меняются достаточно быстро, чтобы датировать по ним слои.'),
  (10, 1, 't_herbs', 'Лечебные травы', 7, 1, 1, 'uploads/tech/stone/herbs.svg', 'Народная медицина: отвары, припарки, обработка ран и вправление вывихов.', 'В погребении неандертальца в пещере Шанидар пыльца лекарственных растений заставила предположить намеренный сбор трав, хотя спор об этой находке не закончен. Надёжнее свидетельства ухода: заросшие тяжёлые травмы у людей, которые не могли кормиться сами, — значит, их кормили другие.

Этнографические наблюдения показывают у охотников-собирателей развитые фармакопеи в сотни растений с различением дозы и способа приготовления.

Лечение с самого начала было связано с обрядом: болезнь объясняли вмешательством духа, и лекарь одновременно был посредником в мире невидимого.'),
  (11, 1, 't_count', 'Устный счёт', 8, 1, 1, 'uploads/tech/stone/count.svg', 'Счёт, меры и зарубки: учёт добычи, дней и долей при дележе.', 'Древнейшие следы счёта — кости с упорядоченными зарубками, самая известная из которых найдена в Ишанго в Африке. Спор о том, что именно там записано — лунный цикл, добыча или просто узор, — продолжается, но регулярность нарезок не случайна.

Счёт вырастает из практики дележа: чтобы разделить добычу поровну, нужно уметь сопоставлять количества, даже не имея слов для больших чисел.

Многие языки сохранили следы счёта по частям тела — отсюда пятеричные и двадцатеричные системы, дожившие во французском «quatre-vingts».'),
  (12, 1, 't_spear', 'Копьё и копьеметалка', 9, 1, 1, 'uploads/tech/stone/spear.svg', 'Метательное оружие: копьё с каменным наконечником и копьеметалка.', 'Деревянные копья из Шёнингена в Германии возрастом около 300 тысяч лет вытесаны с учётом того, что центр тяжести должен приходиться на переднюю треть — то есть их делали именно для броска, а не для тычка.

Копьеметалка — короткий рычаг с упором для торца дротика — удлиняет руку и заметно увеличивает дальность и убойную силу. Это первое известное устройство, усиливающее человека механически.

Составной наконечник, закреплённый смолой и жилой, потребовал соединения трёх разных материалов и считается признаком сложного планирующего мышления.'),
  (13, 1, 't_ground_axe', 'Шлифованный топор', 1, 1, 1, 'uploads/tech/stone/ground_axe.svg', 'Каменный топор с проушиной на рукояти: рубка леса и тяжёлые работы.', 'Шлифовка появляется в неолите и решает главную беду скола: сколотое лезвие крошится при рубке, шлифованное держит удар. Заготовку часами возили по мокрому песчанику, снимая неровности.

Второе новшество — сверление отверстия под рукоять. Насаженный топор превращает силу размаха в удар по узкой кромке, и производительность рубки вырастает в разы.

Именно топор сделал возможной массовую расчистку леса под поля: подсечно-огневое земледелие невозможно, пока лес нечем свести.'),
  (14, 1, 't_carpentry', 'Плотницкое дело', 10, 1, 1, 'uploads/tech/stone/carpentry.svg', 'Обработка дерева: рубка, тёска, расщепление и соединение деталей.', 'Дерево было главным конструкционным материалом древности, но сохраняется плохо, поэтому масштаб деревообработки долго недооценивали. Находки в торфяниках меняют картину: известны настилы из расщеплённых плах, уложенных на лаги.

Рубить каменным топором можно, но медленно, поэтому широко применяли расщепление клиньями вдоль волокон и подпаливание ствола у основания.

Соединения делали связыванием, шиповым замком и деревянными нагелями — приёмы, дожившие до плотницкого ремесла Нового времени почти без изменений.'),
  (15, 1, 't_fishing', 'Рыболовство', 3, 1, 1, 'uploads/tech/stone/fishing.svg', 'Добыча рыбы и морского зверя: остроги, крючки, сети, верши и запруды.', 'Кости рыбы хрупки и сохраняются хуже костей зверя, поэтому роль рыболовства долго недооценивали. Анализ изотопов в останках людей показывает, что у многих прибрежных групп рыба составляла основу питания.

Снасти развивались от остроги к крючку, затем к сети и верше — плетёной ловушке, работающей без участия человека. Запруды в приливной зоне позволяли собирать улов, когда вода уходила.

Река или берег дают пищу круглый год в одном месте, поэтому многие рыболовные группы переходили к оседлости задолго до земледелия.'),
  (16, 1, 't_bow', 'Стрельба из лука', 9, 1, 1, 'uploads/tech/stone/bow.svg', 'Лук и стрелы: дальний бесшумный выстрел, охота и первое дистанционное оружие.', 'Лук — механизм накопления энергии: медленное усилие натяжения запасается в плече и отдаётся стреле мгновенно. Древнейшие целые луки найдены в европейских торфяниках, а каменные микролиты-наконечники старше их на десятки тысяч лет.

В отличие от копья, лук позволяет стрелять из укрытия, лёжа и не выдавая себя движением, а стрелу можно выпустить прицельно на дистанции, недоступной броску.

Лук стал и первым оружием, уравнивающим бойцов: сила натяжения важна, но точность и выучка важнее, и это надолго определило военное дело.'),
  (17, 1, 't_sling', 'Праща и дротики', 9, 1, 1, 'uploads/tech/stone/sling.svg', 'Ременная праща и связка дротиков: дешёвое метательное оружие для всех.', 'Праща — ремень с ложем для снаряда — разгоняет камень до скорости, сравнимой со стрелой, и стоит почти ничего: её сплетёт любой, кто умеет вить верёвку. Находки снарядов и изображения относят её к неолиту, то есть к тому же времени, что и лук.

Праща и лук решают разные задачи и потому существуют рядом тысячелетиями: лук точнее и бьёт настильно, праща дальше и не требует ни дерева нужного качества, ни клея, ни тетивы, которую портит сырость.

Её главный недостаток — годы выучки: бросок требует чувства момента отпускания. Поэтому лучшие пращники древности, родосцы и балеарцы, ценились как наёмники, а оружием пастуха она осталась вплоть до античности — отсюда и сюжет о Давиде.'),
  (18, 1, 't_farming', 'Земледелие', 11, 1, 1, 'uploads/tech/stone/farming.svg', 'Целенаправленный посев и уборка урожая: начало оседлой жизни и запасов зерна.', 'Неолитическая революция произошла независимо в нескольких очагах: на Ближнем Востоке около десяти тысяч лет назад, в Китае, в Мезоамерике, в Андах и в Новой Гвинее.

Одомашнивание было не изобретением, а длительным отбором: люди из года в год брали на семена колосья, которые не осыпались до жатвы, — признак, вредный для дикого растения, но выгодный для земледельца.

Последствия двойственны: земледелие даёт с гектара во много раз больше калорий, но рацион становится однообразнее. Палеопатология фиксирует у ранних земледельцев ухудшение зубов и снижение среднего роста. Зато появился излишек, который можно хранить, — а с ним и специализация.'),
  (19, 1, 't_domestication', 'Приручение животных', 11, 1, 1, 'uploads/tech/stone/domestication.svg', 'Одомашнивание собаки, козы, овцы и свиньи: мясо, шкуры и помощь на охоте.', 'Первым спутником человека стала собака: генетические данные относят её отделение от волка ко времени задолго до земледелия. Вероятно, приручение шло само собой — менее пугливые волки держались у стоянок ради объедков.

Скот одомашнивали позже и уже вместе с земледелием. Отбор шёл на покладистость и скороспелость, и домашние формы заметно мельчали по сравнению с дикими предками.

Стадо стало формой богатства: его можно считать, наследовать, отдавать в приданое и угонять. С него начинается имущественное неравенство, которого собирательское хозяйство почти не знало.'),
  (20, 1, 't_shelter', 'Землянки и шалаши', 10, 1, 1, 'uploads/tech/stone/shelter.svg', 'Первые постоянные жилища: каркас из жердей и костей, покрытие из шкур и дёрна.', 'Древнейшие жилища были лёгкими: конический каркас из жердей, покрытый ветвями и шкурами. В степной зоне, где дерева мало, каркас строили из костей и бивней мамонта — такие постройки известны по стоянкам Восточной Европы.

Полуземлянка — следующий шаг: пол углубляли на полметра и более, что резко улучшало теплоизоляцию, поскольку грунт ниже промерзания держит стабильную температуру.

Размер построек и их расположение в поселении показывают, кто жил вместе: жилища ставили по кругу или рядами, оставляя середину под общее пространство.'),
  (21, 1, 't_rafts', 'Плоты и лодки', 12, 1, 1, 'uploads/tech/stone/rafts.svg', 'Первые плавсредства: плот, долблёнка и обтянутая шкурой лодка.', 'Заселение Австралии не менее 50 тысяч лет назад доказывает, что люди умели пересекать открытую воду задолго до неолита: даже при самом низком уровне океана туда нельзя дойти посуху.

Простейшее судно — связка брёвен или тростника; следующий шаг — долблёнка, которую выжигали и вытёсывали из ствола. Каркасная лодка, обтянутая шкурами, легче и выдерживает волну.

Лодка дала доступ к рыбным местам вдали от берега, к островам и к реке как к дороге: по воде груз перемещается несравнимо легче, чем волоком по суше.'),
  (22, 1, 't_travois', 'Волокуша', 13, 1, 1, 'uploads/tech/stone/travois.svg', 'Перевозка грузов на жердях, которые тащит человек или животное.', 'До колеса главным способом перевозки тяжестей была волокуша: две жерди, связанные поперечиной, одним концом лежат на земле, другим крепятся к плечам человека или к упряжи животного.

Волокуша не требует дороги и работает там, где колесо бесполезно: по траве, снегу и мягкому грунту. Этнографически она известна у степных и североамериканских народов и применялась вплоть до Нового времени.

Именно волокуша впервые связала перевозку с тягловым животным и подготовила переход к повозке.'),
  (23, 1, 't_mining', 'Горное дело', 3, 2, 1, NULL, 'Добыча руды и камня в шахтах и карьерах: сырьё для металла.', 'Первые шахты били ещё в каменном веке ради кремня: в Граймс-Грейвс в Англии сохранились колодцы глубиной более десяти метров с боковыми штреками, прорытыми оленьими рогами.

Металлургия сделала горное дело постоянным занятием: медную руду нужно искать, выламывать, дробить и сортировать. Огневая проходка — прогрев забоя костром и резкое охлаждение водой — раскалывала породу до появления железного инструмента.

Рудник — первое производство, требующее постоянной организованной группы людей, снабжения их пищей и кем-то установленного порядка работ.'),
  (24, 1, 't_copper_bronze', 'Плавка меди и бронзы', 1, 2, 1, NULL, 'Выплавка меди из руды и сплав её с оловом: прочный литой металл.', 'Самородную медь ковали холодной ещё в неолите, но настоящий переворот — выплавка металла из руды в печи с поддувом при температуре около 1100 градусов.

Бронза — сплав меди с оловом — твёрже чистой меди и хорошо льётся. Её слабое место не в металлургии, а в географии: медь и олово почти нигде не залегают рядом, поэтому бронзовый век — это ещё и век дальней торговли металлом.

Металл впервые дал вещь, которую можно переплавить и сделать заново, — материал перестал быть одноразовым.'),
  (25, 1, 't_wax_casting', 'Литьё по восковой модели', 1, 2, 1, NULL, 'Отливка сложных форм: модель из воска выплавляется из глиняной формы.', 'Мастер лепит изделие из воска, обмазывает глиной, обжигает — воск вытекает, а в полость заливают металл. Форму приходится разбивать, поэтому каждая отливка уникальна.

Способ позволил отливать то, что нельзя выковать: статуэтки, навершия, тонкостенные сосуды и детали со сложным профилем. Древнейшие изделия такого рода известны с рубежа медного и бронзового веков.

Литьё разделило ремесло: появился мастер, владеющий секретом состава сплава и режима плавки, — фигура, которая в мифологии почти всегда окружена особым почтением и опаской.'),
  (26, 1, 't_masonry', 'Каменная кладка', 10, 2, 1, NULL, 'Кладка стен из тёсаного камня без раствора или на глиняном растворе.', 'Кладка требует не только силы, но и расчёта: камни подбирают и подтёсывают так, чтобы вес передавался вниз, а швы не совпадали по вертикали. Мегалитические постройки показывают, что этим владели задолго до письменности.

Бронзовый век дал массовое строительство из камня: городские стены, платформы храмов, гробницы. Появились подъёмные приспособления — наклонные насыпи, катки, рычаги — и организация труда сотен людей.

Стена вокруг поселения — первый признак того, что есть что защищать и от кого.'),
  (27, 1, 't_weaving', 'Ткачество', 5, 2, 1, NULL, 'Ткань на станке из спрядённой нити: одежда, паруса, мешки.', 'Ткачество вырастает из плетения, но требует прялки и станка: нить нужно сначала спрясть, вытягивая и скручивая волокно, а затем натянуть основу и пропускать через неё уток.

Древнейшие станки — вертикальные, с грузиками-пряслицами, натягивающими нити основы; такие глиняные грузики находят на поселениях сотнями.

Ткань изменила и хозяйство, и общество: прядение и ткачество стали массовым домашним трудом, преимущественно женским, а текстиль — одним из главных товаров дальней торговли наравне с металлом.'),
  (28, 1, 't_herding', 'Скотоводство', 11, 2, 1, NULL, 'Разведение стад ради мяса, молока, шерсти и шкур.', 'Переход от забоя ради мяса к использованию живого животного — молока, шерсти, тягла — называют революцией вторичных продуктов и относят к бронзовому веку.

Молоко потребовало биологической перестройки самих людей: способность взрослого человека усваивать лактозу закрепилась в популяциях скотоводов как результат естественного отбора и до сих пор распределена по миру крайне неравномерно.

Скотоводство породило и особый уклад — подвижный, малозависимый от поля, с богатством в виде стада. Отношения степи и пашни определят историю на тысячи лет.'),
  (29, 1, 't_plough', 'Пашенное земледелие', 11, 2, 1, NULL, 'Соха и рало на тягле: обработка больших площадей вместо мотыги.', 'Мотыжное земледелие ограничено силой рук, поэтому поле у общины небольшое. Рало, которое тянет пара быков, взрыхляет за день столько, сколько мотыгой не осилить и за неделю.

Рало не переворачивает пласт, а лишь прорезает борозду, поэтому пахали крест-накрест и по лёгким почвам. Тяжёлый отвальный плуг появится только в Средневековье.

Пахота изменила и владение землёй: обработанный участок стоит вложенного труда, его закрепляют за семьёй и передают по наследству. Отсюда межа, спор о границе и земельное право.'),
  (30, 1, 't_irrigation', 'Ирригация', 11, 2, 1, NULL, 'Каналы, дамбы и водоподъём: урожай там, где дождя не хватает.', 'Первые государства выросли в долинах Тигра и Евфрата, Нила, Инда и Хуанхэ — то есть там, где земля плодородна, но без канала бесплодна.

Канал требует того, чего не требует поле: согласованного труда многих общин, постоянной расчистки от ила, правил очерёдности полива и разбора споров о воде. Историки давно спорят, ирригация ли породила государство или наоборот, но связь несомненна.

Побочный итог заметен и сегодня: на юге Междуречья многовековой полив без достаточного дренажа привёл к засолению почв и упадку земледелия.'),
  (31, 1, 't_wheel', 'Колесо', 13, 2, 1, NULL, 'Повозка на колёсном ходу: перевозка тяжестей по дорогам и полю.', 'Колесо изобрели не для транспорта: гончарный круг и катки под тяжестями старше повозки. Трудность не в диске, а в оси — нужно точно подогнать вращающуюся пару и выдержать нагрузку.

Древнейшие изображения и находки повозок относятся к IV тысячелетию до н. э. и почти одновременно появляются в Междуречье, на Балканах и в степи, что говорит о быстром распространении идеи.

Первые колёса были сплошными, из трёх сплочённых плах, и весили немало. Лёгкое колесо со спицами появится позже и сразу изменит военное дело.'),
  (32, 1, 't_potters_wheel', 'Гончарный круг', 14, 2, 1, NULL, 'Вращающийся круг: быстрая формовка одинаковой посуды.', 'На круге сосуд вытягивается из кома глины за минуты, тогда как лепка жгутами занимает часы. Это первая известная машина, поставившая ремесло на поток.

Результат виден археологически: посуда становится тонкостенной, симметричной и однотипной, а её производство сосредоточивается в мастерских при городах вместо каждого двора.

Круг — важный признак разделения труда: гончар перестаёт быть земледельцем, который лепит горшки между делом, и живёт обменом своих изделий на хлеб.'),
  (33, 1, 't_sail', 'Парусное судостроение', 12, 2, 1, NULL, 'Судно с парусом и обшивкой: перевозка грузов по морю и большой реке.', 'Парус превращает ветер в даровую тягу и снимает предел, положенный силой гребцов. Древнейшие изображения парусных судов известны из Египта и относятся к IV тысячелетию до н. э.

Прямой парус хорошо работает при попутном ветре, поэтому раннее мореходство подчинялось сезонным ветрам: расписание торговых плаваний определялось муссоном и этезиями, а не желанием купца.

Морская перевозка резко дешевле сухопутной: судно берёт груз, который не свезти никаким числом ослов, и это сразу связало берега Средиземноморья в единый рынок металла, зерна и леса.'),
  (34, 1, 't_ox_traction', 'Тягловая сила', 2, 2, 1, NULL, 'Упряжь и ярмо: сила быка на пахоте, перевозке и подъёме воды.', 'Бык даёт мощность, недоступную человеку, но её нужно передать: ярмо на холку, постромки, поворотное дышло. Конструкция упряжи веками оставалась узким местом, и неудачная упряжь душила животное при большом усилии.

Тягло применяли не только на пахоте: им молотили, вращали водоподъёмные колёса и жернова, тянули брёвна и камень на стройку.

С этого начинается замена мускульной силы человека силой, которую можно кормить травой, — первый шаг длинного пути к двигателю.'),
  (35, 1, 't_riding', 'Верховая езда', 15, 2, 1, NULL, 'Езда верхом: разведка, связь и подвижность на дальних расстояниях.', 'Лошадь одомашнили в степях Евразии, и споры идут в основном о том, насколько рано на ней начали именно ездить, а не разводить на мясо. Ранняя посадка была неустойчивой: без стремян и жёсткого седла всадник держится коленями.

Даже такая езда меняет масштаб: конный гонец покрывает за день расстояние, недоступное пешему, а конный пастух управляет несравнимо большим стадом.

Верховая езда дала степным народам стратегическое преимущество подвижности, которое они сохраняли до появления огнестрельного оружия.'),
  (36, 1, 't_chariot', 'Боевые колесницы', 15, 2, 1, NULL, 'Лёгкая колесница со спицами: подвижная площадка для лучника.', 'Колесница — вершина бронзового военного дела: лёгкий кузов, колёса со спицами, пара быстрых коней и экипаж из возницы и лучника. Её появление во II тысячелетии до н. э. перекроило военную карту Ближнего Востока.

Содержать колесницу дорого: нужны кони, мастер, ремонт и выучка. Поэтому колесничные войска — это всегда узкий слой знати, а сама колесница становится знаком высокого положения и попадает в погребения.

Битва при Кадеше между египтянами и хеттами известна прежде всего как сражение тысяч колесниц и как первый подробно описанный бой в истории.'),
  (37, 1, 't_ram', 'Тараны и осадные лестницы', 16, 2, 1, NULL, 'Простейшая осада: подкоп, лестница и таран под навесом.', 'Пока стена сложена из сырцового кирпича, её проще проломить или подкопать, чем перелезть. Ассирийские рельефы показывают крытые тараны на колёсах, которые подкатывали к стене под прикрытием лучников.

Лестница проста и потому всегда в ходу, но штурм по ней самый кровавый: обороняющийся сверху имеет все преимущества.

Осада впервые сделала войну делом долгим и требующим снабжения: войско под стенами нужно кормить неделями, а это уже задача государства, а не набега.'),
  (38, 1, 't_composite_bow', 'Композитный лук', 9, 2, 1, NULL, 'Клееный лук из дерева, рога и жил: сила при малой длине.', 'Композит собирают из трёх материалов по их свойствам: рог на внутренней стороне хорошо держит сжатие, сухожилие на внешней — растяжение, дерево связывает их воедино.

Такой лук при длине около метра бьёт сильнее простого деревянного вдвое большей длины — и только поэтому из него можно стрелять с коня и с колесницы, где длинному луку попросту негде развернуться.

Плата — время и климат: изготовление занимает месяцы из-за сушки клея, а сырость расслаивает лук. Поэтому композит господствовал в сухих степях и на Востоке, а влажная Северная Европа осталась при простом луке.'),
  (39, 1, 't_writing', 'Письменность', 4, 2, 1, NULL, 'Запись речи знаками: учёт, закон, договор и передача знания через века.', 'Письмо родилось из счёта: в Междуречье ему предшествовали глиняные фишки для учёта скота и зерна, которые запечатывали в шаровые конверты, а затем стали оттискивать их изображения на поверхности — так появилась табличка.

Ранняя клинопись почти целиком хозяйственная: расписки, наряды, описи. Литература и закон приходят позже, когда знаковая система становится способной передавать не только количество, но и звучание слова.

Письмо создало новую профессию — писца — и вместе с ней школу, экзамен и учебник, то есть первую систему передачи знания вне семьи.'),
  (40, 1, 't_calendar', 'Календарь и наблюдение неба', 8, 2, 1, NULL, 'Счёт дней, месяцев и лет по светилам: сроки сева, разлива и праздника.', 'Земледелие требует срока: посеешь рано — вымерзнет, поздно — не вызреет. Поэтому первые астрономические наблюдения прикладные — восход определённой звезды перед рассветом отмечал в Египте близость разлива Нила.

Трудность календаря в том, что год не делится на месяцы нацело. Отсюда вставные месяцы, споры о начале года и власть жречества, которое одно знало правило вставки.

Наблюдение неба быстро срослось с гаданием: вавилонские таблички фиксируют положение планет вместе с предсказаниями о царе и урожае, и из этой практики вырастет и астрология, и точная астрономия.'),
  (41, 1, 't_weights', 'Весовые деньги и меры', 17, 2, 1, NULL, 'Единые меры веса и объёма; серебро по весу как всеобщий эквивалент.', 'До монеты расчёт вёлся по весу металла: сикль и мина — это прежде всего единицы веса, и лишь потом суммы. Купец носил с собой гирьки, а честность гирь была предметом закона и проклятия в текстах.

Единая мера нужнее денег: без неё нет ни налога, ни договора о поставке, ни справедливого обмена зерна на масло. Поэтому эталон хранится при храме или дворце и становится делом власти.

Законы Хаммурапи назначают цены и наймы именно в весовом серебре, показывая, насколько далеко зашла хозяйственная жизнь до появления чеканки.'),
  (42, 1, 't_faience', 'Фаянс и стекло', 6, 2, 1, NULL, 'Стекловидные материалы: глазурь, бусина, цветное непрозрачное стекло.', 'Египетский фаянс — не глина, а спёкшийся кварцевый песок со щелочной добавкой, покрывающийся при обжиге синей стекловидной коркой. Это первый искусственный материал, созданный ради цвета.

Настоящее стекло появляется во II тысячелетии до н. э. и остаётся дорогой редкостью: его варят малыми порциями, лепят вокруг песчаного сердечника и красят окислами металлов.

Работа со щёлочью, окислами и температурой обжига — прямая предшественница химии: рецептура стекловарения записывалась на табличках задолго до появления слова «химия».'),
  (43, 1, 't_bonesetting', 'Костоправство', 7, 2, 1, NULL, 'Хирургия и травматология: вправление, шины, трепанация, прижигание.', 'Скелеты с зажившими переломами, сросшимися ровно, показывают, что кость умели вправлять и фиксировать шиной задолго до письменности.

Трепанация черепа — древнейшая известная операция: отверстия со следами заживления краёв означают, что пациент выживал. Делали её и при травме, и по причинам, которые мы можем только предполагать.

Египетский папирус Эдвина Смита — первый известный хирургический текст: он разбирает случаи по порядку, отделяет излечимые от безнадёжных и почти не обращается к магии, что делает его поразительно «медицинским» документом.'),
  (44, 1, 't_bridges', 'Мостостроение', 10, 2, 1, NULL, 'Постоянные переправы: балочный, свайный и понтонный мост.', 'Мост решает задачу, которая иначе решается только бродом и паромом: сделать реку не преградой, а частью дороги. Простейший балочный мост ограничен длиной бревна, поэтому реку бьют на пролёты сваями.

Свайные и понтонные переправы известны по ассирийским и персидским описаниям; наплавной мост Ксеркса через Геллеспонт — знаменитый пример инженерного решения, поставленного на службу походу.

Мост всегда стратегическая вещь: он собирает торговлю к себе, задаёт место города и первым разрушается при отступлении.'),
  (45, 1, 't_iron', 'Плавка железа', 1, 3, 1, NULL, 'Кричное железо и науглероживание: дешёвый металл для орудий и оружия.', 'Железо требует иной металлургии, чем бронза: в древних горнах его не расплавляли, а получали тестообразную крицу, которую многократно проковывали, выбивая шлак.

Зато железная руда есть почти везде, тогда как олово редко. Поэтому железо — металл демократический: оно вооружило ополчение и вложило топор и лемех в руки рядового хозяина, что бронза позволить не могла.

Науглероживание поверхности и закалка дали сталь, превосходящую бронзу по твёрдости, хотя ранние мастера владели этими приёмами скорее по опыту, чем по пониманию.'),
  (46, 1, 't_concrete', 'Бетон и обожжённый кирпич', 10, 3, 1, NULL, 'Римский бетон на вулканическом пепле и стандартный обожжённый кирпич.', 'Римский бетон — смесь извести, вулканического пепла и щебня — схватывается даже под водой и позволяет лить монолит любой формы, а не складывать его из блоков.

Купол Пантеона отлит из бетона с облегчением состава кверху и почти два тысячелетия остаётся крупнейшим неармированным куполом мира.

Обожжённый кирпич стандартного размера сделал строительство массовым и быстрым: он не требует каменоломни и позволяет вести кладку силами обычной артели.'),
  (47, 1, 't_arches', 'Своды и арки', 10, 3, 1, NULL, 'Арка, свод и купол: перекрытие больших пролётов камнем.', 'Балка работает на изгиб и потому ограничена: камень плохо держит растяжение. Арка переводит нагрузку в сжатие, в котором камень силён, и перекрывает пролёт, недостижимый для перемычки.

Плата за арку — распор: она стремится разъехаться и требует массивных опор или соседних арок, гасящих усилие. Отсюда аркада и толстые устои римских сооружений.

Свод и купол — та же идея, развёрнутая в пространстве. С них начинается архитектура больших внутренних объёмов: базилика, термы, крытый рынок.'),
  (48, 1, 't_aqueducts', 'Акведуки', 10, 3, 1, NULL, 'Самотёчный водовод: чистая вода в город на десятки километров.', 'Акведук работает без насосов: вся трасса выдержана с ничтожным постоянным уклоном, и вода идёт самотёком, ныряя в дюкеры под долинами и поднимаясь на аркады.

Точность нивелирования на десятках километров — главное достижение: ошибка в несколько сантиметров на километр останавливает воду или размывает лоток.

Водопровод изменил город: он сделал возможными термы, фонтаны и уборные, а постоянный проток снизил зависимость от колодцев. Обслуживание требовало постоянной службы, и её упадок гасил города вернее осады.'),
  (49, 1, 't_roads', 'Дорожное строительство', 13, 3, 1, NULL, 'Мощёная дорога с полотном и водоотводом: связь армии, почты и торговли.', 'Римская дорога — многослойное сооружение: выемка, подушка из бута, слой щебня на растворе и каменное покрытие с выпуклым профилем для стока воды.

Дорога строилась прежде всего для войска: она позволяла легиону идти в любую погоду и переводила скорость реакции империи из недель в дни. Торговля пользовалась ею уже вторым делом.

Вдоль дороги вырастала инфраструктура — станции смены лошадей, постоялые дворы, мильные столбы. Многие современные европейские трассы повторяют античные направления.'),
  (50, 1, 't_coinage', 'Чеканка монеты', 17, 3, 1, NULL, 'Монета с гарантией веса и пробы: расчёт счётом, а не взвешиванием.', 'Первые монеты чеканили в Лидии в VII веке до н. э. из электра — природного сплава золота и серебра. Смысл клейма прост: власть удостоверяет вес и пробу, и слиток больше не нужно взвешивать при каждой сделке.

Монета резко ускорила обмен и сделала возможной розничную торговлю, наём и жалованье. Афины опирались на серебро Лаврийских рудников, а «сова» стала международной валютой Средиземноморья.

Одновременно родилась и порча монеты: снижая содержание металла, правитель получает скрытый доход — и первый в истории инструмент инфляции.'),
  (51, 1, 't_usury', 'Ростовщичество', 17, 3, 1, NULL, 'Заём под процент, залог и долговая расписка.', 'Кредит старше монеты: зерно в долг до урожая давали ещё храмы Междуречья, и процент исчислялся натурой. С монетой заём становится денежным и куда более подвижным.

Долг быстро стал политической проблемой: долговое рабство разоряло крестьянство и не раз приводило к смутам. Реформы Солона в Афинах прямо отменили долговую кабалу, а римские законы веками пытались ограничить ставку.

Отсюда же тянется религиозный запрет на процент, который надолго определит устройство средневековых финансов и в христианском, и в исламском мире.'),
  (52, 1, 't_geometry', 'Математика и геометрия', 18, 3, 1, NULL, 'Доказательство и мера: планиметрия, дроби, начала алгебры.', 'Египетская и вавилонская математика была рецептурной: задача решалась по образцу, без объяснения, почему приём работает. Греки сделали решающий шаг — ввели доказательство, выводящее истину из принятых начал.

«Начала» Евклида на две тысячи лет стали образцом строгого рассуждения не только в математике: по их схеме строили трактаты юристы и философы.

Прикладная сторона не менее важна: размётка поля после разлива, расчёт объёма насыпи, проверка прямого угла — геометрия и буквально значит «землемерие».'),
  (53, 1, 't_mechanics', 'Механика Архимеда', 18, 3, 1, NULL, 'Рычаг, блок, винт и закон плавания: расчёт машин вместо угадывания.', 'Архимед первым связал устройство машины с числом: правило рычага позволяет заранее сказать, какой выигрыш в силе даст плечо, а закон плавания объясняет, почему тело тонет или всплывает.

На этом основании работают полиспаст, водоподъёмный винт и осадные машины, которыми, по преданию, оборонялись Сиракузы.

Античная механика не породила промышленной революции: дешёвый труд снимал спрос на машину. Но её понятия — сила, плечо, равновесие — перешли в науку Нового времени почти без изменений.'),
  (54, 1, 't_astronomy_geo', 'Геоцентрическая астрономия', 8, 3, 1, NULL, 'Модель неба с Землёй в центре: предсказание положений светил и затмений.', 'Вавилоняне накопили многовековые ряды наблюдений и научились предсказывать затмения по повторяемости циклов, не строя при этом модели мира.

Греки добавили геометрию: система вложенных сфер, а затем эпициклы Птолемея позволяли вычислить положение планеты на любую дату. Модель была неверна по сути, но точна по результату — и потому продержалась полторы тысячи лет.

Тогда же были измерены размеры Земли: Эратосфен получил длину окружности по разнице полуденных теней в двух городах с ошибкой в считанные проценты.'),
  (55, 1, 't_medicine_ant', 'Античная медицина', 7, 3, 1, NULL, 'Наблюдение, прогноз и режим: медицина как ремесло, а не заклинание.', 'Гиппократов корпус впервые отделил болезнь от гнева богов: даже «священную болезнь» он объявляет имеющей естественную причину. Врач наблюдает течение, записывает случаи и предсказывает исход.

Практическая сила античной медицины была в режиме, диете, вправлении и уходе; теория четырёх жидкостей объясняла мало, но задала связную картину, которой врачи пользовались до XVIII века.

Гален добавил анатомию, вскрывая животных, и его выводы стали каноном — включая ошибки, которые никто не решался проверять более тысячи лет.'),
  (56, 1, 't_library', 'Библиотеки и свитки', 4, 3, 1, NULL, 'Папирусный свиток, копирование и хранилище текстов.', 'Папирус дал дешёвый и лёгкий носитель, а свиток — форму книги, удобную для чтения подряд, но неудобную для поиска: чтобы найти место, свиток нужно перемотать.

Александрийская библиотека была не только хранилищем, но и институтом: там сверяли списки, отделяли подлинное от подложного и составляли комментарии — то есть занимались тем, что позже назовут филологией.

Уязвимость свитка в том, что он живёт лишь пока его переписывают. Большая часть античной литературы утрачена не в пожаре, а из-за того, что её перестали копировать.'),
  (57, 1, 't_catapult', 'Катапульты и баллисты', 16, 3, 1, NULL, 'Торсионные метательные машины: камень и стрела на сотни шагов.', 'Торсионная машина запасает энергию в скрученных жгутах из сухожилий или волоса. Это первое оружие, которое проектировали расчётом: греческие и римские трактаты задают все размеры машины через диаметр отверстия под жгут.

Баллиста била стрелой прицельно и применялась в полевом бою, камнемёт разбивал зубцы и кладку. Осадный парк стал постоянной частью армии со своими мастерами.

Слабость торсиона — жгут: он тянется, боится сырости и требует постоянной подтяжки. Именно поэтому его позже вытеснит противовесная машина.'),
  (58, 1, 't_siege_tower', 'Осадные башни', 16, 3, 1, NULL, 'Подвижная башня выше стены: штурм по перекидному мосту.', 'Башня решает главную беду штурма по лестнице: атакующий выходит на стену не по одному и не снизу, а сразу отрядом и на равной высоте.

Гелепола Деметрия Полиоркета под Родосом описана как многоярусное сооружение высотой в десятки метров, обшитое железом от зажигательных стрел и передвигаемое сотнями людей.

Цена такой машины огромна: нужны ровный подход, засыпанный ров и недели работы плотников. Поэтому башню строили там, где город решали взять во что бы то ни стало.'),
  (59, 1, 't_gastraphetes', 'Гастрафет', 9, 3, 1, NULL, 'Станковый самострел с ложем и упором в живот: механическое натяжение.', 'Гастрафет описан греческими механиками IV века до н. э.: лук закреплён на ложе, стрелок упирается животом в изогнутый упор и наваливается всем весом, взводя тетиву по зубчатой рейке.

Это первое оружие, где натяжение отделено от выстрела: удерживает тетиву замок, а не рука, поэтому сила натяжения больше не ограничена тем, что стрелок способен держать на весу.

Из этого принципа выросли обе линии: увеличенный до станкового размера гастрафет дал торсионные машины, а уменьшенный и переложенный на плечо — арбалет, который Европа заново освоит через полторы тысячи лет.'),
  (60, 1, 't_cavalry', 'Кавалерия', 15, 3, 1, NULL, 'Конные отряды как род войск: разведка, охват, преследование.', 'Пока не было стремян, конница не могла таранить строй, зато превосходно делала другое: вела разведку, охватывала фланги, рвала обозы и добивала бегущих.

Македонские гетайры показали, что удар конницы в нужный момент решает сражение, а парфяне довели до совершенства конную стрельбу и отход — приём, стоивший Крассу армии при Каррах.

Конница дорога: конь ест зерно и требует ухода, поэтому во всех античных армиях всадники — это состоятельное сословие, и военное дело прямо связано с имущественным цензом.'),
  (61, 1, 't_trireme', 'Триремы и боевые галеры', 12, 3, 1, NULL, 'Гребной боевой корабль с тараном: господство на море.', 'Трирема — узкое быстроходное судно с тремя рядами вёсел и бронзовым тараном на форштевне. Её оружие — не абордаж, а удар в борт: бой сводится к маневру и скорости.

Экипаж в полторы-две сотни гребцов требовал выучки и слаженности, поэтому морская мощь была прямо связана с числом свободных граждан, готовых сесть на весло. В Афинах флот и демократия росли вместе.

Галера почти не берёт груза и запаса воды, поэтому античный военный флот привязан к берегу и ночует на суше — стратегия войны на море определялась этим ограничением.'),
  (62, 1, 't_star_nav', 'Навигация по звёздам', 12, 3, 1, NULL, 'Счисление пути по светилам, ветрам и лоции: плавание вне видимости берега.', 'Античный мореход держался берега, но финикийцы и греки умели идти и открытым морем, правя по Полярной звезде, по высоте светил и по устойчивым сезонным ветрам.

Знание закреплялось в перипле — описании побережья с расстояниями, приметами и опасностями. Это первая форма морской лоции, передаваемая как ремесленный секрет.

Опасность плавания вне сезона была так велика, что мореходство прямо закрывалось на зиму: договоры и займы под морскую торговлю прямо оговаривали срок навигации.'),
  (63, 1, 't_viticulture', 'Виноградарство и оливководство', 11, 3, 1, NULL, 'Многолетние культуры: вино и масло как товар дальней торговли.', 'Виноградник и оливковая роща — вложение на годы: дерево начинает плодоносить не сразу и требует ухода, обрезки и защиты. Такое хозяйство возможно только при устойчивом владении землёй.

Зато их продукт не портится и хорошо переносит перевозку: амфоры с вином и маслом стали главным грузом средиземноморской торговли, и по их клеймам археологи восстанавливают торговые связи.

Специализация на вине и масле позволяла Греции и Италии покупать привозной хлеб — первая известная модель хозяйства, сознательно построенного на обмене, а не на самообеспечении.'),
  (64, 1, 't_glassblowing', 'Стеклодувное дело и красители', 6, 3, 1, NULL, 'Выдувание стекла и промышленная окраска тканей.', 'Выдувание, освоенное на сирийском побережье в I веке до н. э., превратило стекло из роскоши в бытовую вещь: сосуд формуется за минуты вместо часов.

Тогда же отлаживается окраска тканей. Пурпур из морских моллюсков был так трудоёмок, что стал знаком высшей власти, а марена и вайда давали дешёвые красные и синие тона для всех.

Обе отрасли — химия до химии: работали с флюсами, окислами, протравами и температурой, накапливая рецептуру, которую объяснить не могли, но воспроизводили надёжно.'),
  (65, 1, 't_water_wheel', 'Водяное колесо', 2, 3, 1, NULL, 'Мельница на реке: даровая механическая сила без человека и скота.', 'Водяное колесо впервые отвязало работу от мускула: река крутит вал днём и ночью, пока есть вода. Верхнебойное колесо, на которое вода падает сверху, отдаёт заметно больше энергии, чем подливное.

Комплекс в Барбегале на юге Галлии — шестнадцать колёс каскадом — молол зерно в масштабах, достаточных для целого города, и считается древнейшим известным промышленным производством.

Античность применяла колесо в основном на помоле; распилка камня и приведение молотов появятся позже, но принцип передачи вращения от воды к машине заложен именно здесь.'),
  (66, 1, 't_heavy_plough', 'Тяжёлый плуг', 11, 4, 1, NULL, 'Плуг с отвалом и колёсным передком: распашка тяжёлых северных почв.', 'Античное рало лишь прорезает борозду и годится для сухих лёгких почв юга. Тяжёлый плуг с ножом, лемехом и отвалом переворачивает пласт и осушает поле бороздой — именно это открыло земледелию влажные глинистые равнины Северной Европы.

Плата — тяга: такой плуг тянет упряжка из нескольких волов, которой нет у отдельного двора. Отсюда совместная запашка и длинные узкие полосы, которые дешевле пахать, чем квадраты: разворот тяжёлой упряжки долог.

Смещение хозяйственного центра Европы с юга на север — прямое следствие этого орудия.'),
  (67, 1, 't_blacksmith_steel', 'Кузнечная сталь', 1, 4, 1, NULL, 'Науглероживание, сварка пакетом и закалка: клинок, лемех, инструмент.', 'Средневековый кузнец не плавил сталь, а получал её обработкой крицы: сваривал в пакет полосы с разным содержанием углерода, чтобы соединить вязкую сердцевину с твёрдой кромкой.

Закалка и отпуск задавали свойства уже готового изделия, и мастер судил о температуре по цвету металла — умение, передававшееся только показом.

Кузница стала обязательной частью каждого поселения: без неё нет ни подковы, ни лемеха, ни гвоздя, ни оковки колеса.'),
  (68, 1, 't_horse_collar', 'Хомут и подкова', 13, 4, 1, NULL, 'Жёсткий хомут на плечи и подкова: лошадь как тягловое животное.', 'Античная упряжь давила лошади на горло и не давала тянуть в полную силу. Жёсткий хомут переносит усилие на плечи, увеличивая полезную тягу в несколько раз.

Подкова решила вторую беду: копыто лошади на сырой северной почве и на камне стирается быстрее, чем отрастает. Гвоздевая подкова распространяется по Европе примерно тогда же, что и хомут.

Лошадь пашет вдвое быстрее вола, хоть и требует овса. Там, где урожай позволял её кормить, она вытеснила вола и заметно ускорила и полевые работы, и извоз.'),
  (69, 1, 't_three_field', 'Трёхполье (севооборот)', 11, 4, 1, NULL, 'Деление пашни на озимое, яровое и пар: две трети поля в работе вместо половины.', 'При двуполье половина земли всегда отдыхает. Трёхполье вводит третье поле под яровые — прежде всего бобовые и овёс — и оставляет под паром лишь треть.

Выигрыш не только в площади: бобовые обогащают почву азотом, а овёс даёт корм лошади, без которого хомут бесполезен. Система работает как целое.

Трёхполье требует согласия всей общины: поля чередуются сообща, скот пасут по жнивью, и отдельный хозяин не может распорядиться своей полосой иначе. Отсюда прочность общинного порядка в деревне на много веков.'),
  (70, 1, 't_castle', 'Крепостное зодчество', 10, 4, 1, NULL, 'Замок как узел обороны: вал, донжон, каменные стены и башни.', 'Ранний замок — насыпной холм с деревянной башней и частоколом: его ставила за недели небольшая дружина. Каменный донжон приходит позже и означает уже устоявшуюся власть, способную вести стройку годами.

Замок изменил саму логику войны: захватывать надо не поле, а точки. Небольшой гарнизон держит округу и не даёт противнику закрепиться, поэтому кампания превращается в череду осад.

Он же стал центром управления: суд, склад, тюрьма и резиденция под одной крышей.'),
  (71, 1, 't_mangonel', 'Метательная машина (мангонель)', 16, 4, 1, NULL, 'Рычажный камнемёт на людской тяге: замена капризному торсиону.', 'Античный торсион зависел от жгутов, которые тянулись и боялись сырости. Рычажная машина, где расчёт разом дёргает за верёвки короткое плечо, проще, дешевле и не теряет силы от влаги.

Такая машина пришла в Средиземноморье с востока и стала основным осадным средством раннего Средневековья: её собирали на месте из подручного леса.

Точность была невысока, зато скорострельность и простота позволяли вести обстрел неделями, разрушая кладку и изматывая гарнизон.'),
  (72, 1, 't_crossbow', 'Арбалет', 9, 4, 1, NULL, 'Самострел со стальной дугой и воротом: пробивная сила без долгой выучки.', 'Арбалет запасает энергию в жёсткой дуге и удерживает её замком, поэтому стрелку не нужно держать натяжение. Обучить арбалетчика можно за недели, тогда как лучника растят годами.

Плата — скорострельность: тяжёлый арбалет с воротом даёт один-два выстрела в минуту против десятка у лучника.

Пробивая доспех, арбалет обесценивал дорогое снаряжение знати, и церковные соборы пытались запретить его против христиан — редкий случай попытки ограничить оружие по нравственным соображениям.'),
  (73, 1, 't_stirrup', 'Тяжёлая конница (стремя)', 15, 4, 1, NULL, 'Стремя и высокое седло: таранный удар копьём с коня.', 'Стремя и седло с высокими луками дают всаднику упор, без которого удар копьём выбил бы его самого. Только с ними появляется таранный удар, где в цель идёт масса коня и человека вместе.

Историки спорят, насколько стремя определило появление рыцарства, но связь устойчива: тяжёлый конник дорог, требует земли на содержание — и получает её вместе с обязанностью служить.

Так техника прямо вплетается в общественное устройство: способ боя задаёт способ владения землёй.'),
  (74, 1, 't_drakkar', 'Драккар и клинкерная обшивка', 12, 4, 1, NULL, 'Лёгкое судно с обшивкой внахлёст: море, река и высадка прямо на берег.', 'Клинкерная обшивка внахлёст даёт корпус лёгкий и гибкий: он играет на волне вместо того, чтобы ломаться. Малая осадка позволяет идти вверх по рекам и вытаскивать судно на песок без пристани.

Сочетание паруса и вёсел снимает зависимость от ветра, а разборная мачта — от мостов и низких берегов.

Именно эти качества, а не численность, обеспечили дальность походов северных мореходов: от Волги до Ньюфаундленда — на судах, которые могли причалить где угодно.'),
  (75, 1, 't_numerals', 'Индийские цифры и ноль', 18, 4, 1, NULL, 'Позиционная запись числа с нулём: счёт столбиком вместо счётной доски.', 'Позиционная система пришла из Индии и была изложена по-арабски аль-Хорезми, от чьего имени происходит слово «алгоритм». Ключ в нуле: он держит пустой разряд и делает запись однозначной.

Римские цифры пригодны для записи результата, но не для вычисления — умножать в них невозможно, и счёт вели на доске с камешками.

Новая запись позволила считать письменно, проверять ход вычисления и доверять расчёт ученику. Без неё немыслимы ни бухгалтерия, ни навигационные таблицы.'),
  (76, 1, 't_alchemy', 'Алхимия', 8, 4, 1, NULL, 'Опытная работа с веществом: перегонка, возгонка, кислоты, лабораторный обиход.', 'Алхимия ставила недостижимую цель — превращение металлов, — но по дороге создала почти всё оснащение будущей химии: перегонный куб, водяную баню, фильтрование, весовой учёт и подробную запись опыта.

Арабские мастера получили минеральные кислоты, без которых немыслима ни металлургия, ни производство красителей и пороха.

Важнее рецептов оказалась привычка: вещество надо не рассуждать, а брать, греть, смешивать и смотреть, что вышло. Это уже опыт в современном смысле.'),
  (77, 1, 't_astrolabe', 'Астролябия', 8, 4, 1, NULL, 'Прибор для измерения высоты светил: время, широта и направление.', 'Астролябия — плоская модель неба: подвижная сетка со звёздами накладывается на круг горизонта, и по высоте одного светила прибор даёт время, широту и высоту недоступных предметов.

Её довели до совершенства в исламском мире, где она решала и повседневную задачу — определение направления и часов молитвы.

Это первый массовый вычислительный инструмент: он не считает сам, но переводит громоздкий расчёт в наложение шкал, доступное человеку без математики.'),
  (78, 1, 't_monastic_med', 'Монастырская медицина', 7, 4, 1, NULL, 'Аптечный огород, уход и переписка античных врачебных текстов.', 'После упадка городов монастырь остался единственным местом, где лечили системно: при нём держали аптечный огород, лазарет и книги. Там же переписывали Галена и Диоскорида, сохранив античную медицину для будущего.

Основой лечения были травы, режим, покой и уход — то, что реально снижает смертность при многих болезнях даже без понимания их причин.

Монастырская больница стала прообразом госпиталя: заведения, где о больном заботятся постоянно, а не приходят к нему на дом.'),
  (79, 1, 't_paper', 'Бумага', 4, 4, 1, NULL, 'Дешёвый писчий материал из растительного волокна и тряпья.', 'Бумагу изобрели в Китае, а в исламский мир она пришла в VIII веке, где появились первые водяные бумажные мельницы, толкущие тряпьё в массу.

По сравнению с пергаментом выигрыш огромен: на книгу пергамента уходило стадо, а бумага делается из отходов. Письмо перестаёт быть роскошью, и появляются архив, черновик и деловая переписка в привычном смысле.

Позже именно дешёвая бумага сделает осмысленным книгопечатание: печатать на пергаменте тиражом не имеет смысла.'),
  (80, 1, 't_mint', 'Монетные дворы', 17, 4, 1, NULL, 'Государственная чеканка единой монеты и надзор за пробой.', 'Каролингская реформа задала счётную систему из фунта, шиллинга и денария, дожившую местами до XX века, и вернула денежному обращению единый образец после разнобоя раннего Средневековья.

Право чеканки стало важнейшей привилегией: оно давало доход от разницы между стоимостью металла и номиналом и потому постоянно оспаривалось между королём, епископом и городом.

Порча монеты — снижение содержания серебра — оставалась привычным способом покрыть расходы казны и столь же привычной причиной недовольства.'),
  (81, 1, 't_soap', 'Мыловарение', 6, 4, 1, NULL, 'Варка мыла из жира и щёлочи: стирка, валяние сукна, гигиена.', 'Мыло получают, обрабатывая жир щёлочью из древесной золы или соды. Средиземноморье варило твёрдое мыло на оливковом масле, север — мягкое на сале.

Первое назначение мыла было промышленным: без него не отмыть шерсть от жиропота и не свалять сукно. Бытовая гигиена шла следом.

Мыловарение — одно из первых химических производств со своим сырьевым хозяйством: золу и соду добывали, возили и продавали как отдельный товар.'),
  (82, 1, 't_windmill', 'Ветряная мельница', 2, 4, 1, NULL, 'Помол там, где нет падающей воды: сила ветра на равнине.', 'Ранние ветряные мельницы известны в Персии: у них вертикальная ось и лопасти, закрытые стеной с одной стороны. Европейская мельница с горизонтальной осью появляется позже и умеет разворачиваться на ветер целиком.

Ветер капризнее воды, зато мельницу можно поставить где угодно — на равнине, у моря, в степи, где рек с достаточным падением нет.

Мельница почти всюду стала собственностью сеньора или города: помол был обязателен именно на господской мельнице, и это один из самых спорных поборов эпохи.'),
  (83, 1, 't_broadcloth', 'Сукноделие', 5, 4, 1, NULL, 'Валяное шерстяное сукно: плотная ткань, не пропускающая ветер.', 'Сукно получают, уваливая тканое полотно в воде: волокна сцепляются, ткань садится и уплотняется так, что не продувается и почти не промокает.

Раньше сукно топтали ногами; водяная валяльная мельница передала эту работу молотам и стала одним из первых применений механической силы в текстильном деле.

Сукно — главный экспортный товар средневековой Европы. Вокруг него сложились Фландрия и Флоренция, и именно на сукне выросли крупнейшие торговые состояния эпохи.'),
  (84, 1, 't_land_clearing', 'Внутренняя колонизация', 19, 4, 1, NULL, 'Раскорчёвка леса и распашка пустошей: рост площади пашни.', 'С X по XIII век Европа расчистила под поля огромные лесные площади: рубили, жгли, корчевали и осушали, основывая новые деревни на пустошах.

Двигателем был рост населения, а условием — новый плуг и трёхполье, дававшие прокорм с распаханного участка. Монастырские ордена вели расчистку особенно методично.

Последствия оказались долгими: сведение лесов изменило ландшафт и водный режим Европы, а нехватка дерева к концу Средневековья подтолкнёт переход на каменный уголь.'),
  (85, 1, 't_deep_mining', 'Рудничное дело', 3, 5, 1, NULL, 'Глубокие рудники с креплением, вентиляцией и водоотливом.', 'Пока руду брали с поверхности, шахта была ямой. Глубокая разработка потребовала крепления штолен, отвода грунтовых вод и подачи воздуха — иначе забой затапливает и в нём нечем дышать.

Водоотлив стал главной задачей: цепи с черпаками и насосы приводились от водяного колеса, а позже именно эта задача вызовет к жизни паровую машину.

Горняки рано получили особые права и собственный суд: ремесло было настолько опасным и нужным, что власть шла на уступки ради серебра и меди.'),
  (86, 1, 't_cam_shaft', 'Кулачковый вал и привод', 2, 5, 1, NULL, 'Передача вращения в удар и качание: молот, пила, толчея, мех.', 'Кулачковый вал превращает равномерное вращение колеса в возвратное движение: выступы на валу поднимают молот или толкач и отпускают его.

Это открыло воде и ветру всё, что раньше делали руками: ковку, распилку брёвен, дробление руды, валяние сукна, раздувание мехов в горне.

Средневековая Европа применяла механическую силу шире, чем античность, и именно поэтому смогла поднять металлургию до доменной плавки: без механического дутья нужной температуры не получить.'),
  (87, 1, 't_blast_furnace', 'Доменная печь (чугун)', 1, 5, 1, NULL, 'Высокая печь с механическим дутьём: жидкий чугун вместо крицы.', 'Подняв температуру механическим дутьём, металлурги получили не тестообразную крицу, а жидкий металл, насыщенный углеродом, — чугун. Его можно лить в форму.

Чугун хрупок и не куётся, поэтому появился второй передел: выжигание излишнего углерода для получения ковкого железа. Металлургия стала двухступенчатой и на столетия сохранила эту схему.

Литьё сразу нашло применение: чугунные ядра и стволы дешевле кованых, и артиллерия во многом обязана домне своим распространением.'),
  (88, 1, 't_gothic', 'Готическая архитектура', 10, 5, 1, NULL, 'Стрельчатая арка, нервюрный свод и контрфорс: высота, свет и лёгкость стены.', 'Готика решает задачу распора: стрельчатая арка направляет усилие круче вниз, нервюры собирают нагрузку свода в точки, а аркбутаны выносят её на внешние опоры.

Освободившаяся стена перестаёт быть несущей и превращается в витраж. Свет, пропущенный через цветное стекло, был для строителей богословским доводом не меньше, чем инженерным достижением.

Собор строили десятилетиями, и вокруг стройки складывались артели с собственными приёмами разметки, чертежа и подъёма грузов — прообраз инженерной профессии.'),
  (89, 1, 't_trebuchet', 'Требушет', 16, 5, 1, NULL, 'Противовесная машина: точный и мощный настильный обстрел кладки.', 'Требушет заменяет людскую тягу подвешенным грузом в несколько тонн. Энергия падения противовеса передаётся длинному плечу и праще, разгоняющей снаряд.

Машина оказалась поразительно точной: меняя массу снаряда и длину пращи, расчёт клал ядра в одну точку стены раз за разом, пробивая её методично.

Требушет господствовал в осадах около двух веков и уступил только пороховой артиллерии, да и то не сразу: первые бомбарды уступали ему в надёжности.'),
  (90, 1, 't_longbow', 'Длинный лук', 9, 5, 1, NULL, 'Тисовый лук в рост человека: залповая стрельба пехоты.', 'Длинный лук не хитроумен — он просто большой: длина плеч позволяет запасти много энергии без сложного клееного composite. Тис даёт готовый композит от природы: упругая заболонь снаружи, плотная сердцевина внутри.

Сила натяжения такого лука огромна, и стрелка растили с детства; скелеты лучников несут характерные изменения плеча и позвоночника.

Сила его была в залпе: сотни стрел в минуту накрывают площадь, и рыцарская атака разваливается ещё до сшибки — как при Креси и Азенкуре.'),
  (91, 1, 't_plate_cavalry', 'Латная рыцарская конница', 15, 5, 1, NULL, 'Сплошной доспех и таранный удар: главная ударная сила поля боя.', 'Кольчугу постепенно вытеснил сплошной доспех из кованых пластин: он лучше держит стрелу и распределяет удар. Полный латный доспех, вопреки расхожему мнению, не сковывал движений и весил меньше современной выкладки пехотинца.

Такое снаряжение требовало домны и умелой кузницы, а конь под латника — отдельного разведения. Рыцарь стал самым дорогим бойцом эпохи.

Именно дороговизна и погубила его: плотный строй пикинёров и дешёвый арбалет с аркебузой уравнивали шансы, а разорение владения оружием не восполнить.'),
  (92, 1, 't_magnetism', 'Магнетизм', 18, 5, 1, NULL, 'Свойства магнита и магнитной стрелки: первое дальнодействие в науке.', 'Пьер де Марикур в 1269 году описал опыты с магнитным шаром, ввёл понятие полюсов и показал, что разноимённые притягиваются, — это одно из первых сочинений, целиком построенных на эксперименте.

Магнит был странен: он действует через пустоту и без прикосновения, чего аристотелевская физика не допускала. Именно эта странность заставила искать новые объяснения.

Практическое следствие пришло раньше теории: намагниченная стрелка стала компасом задолго до того, как кто-либо понял, почему она поворачивается.'),
  (93, 1, 't_optics_medieval', 'Оптика Ибн аль-Хайсама', 18, 5, 1, NULL, 'Учение о зрении и преломлении, опыт с камерой-обскурой, линзы.', 'Ибн аль-Хайсам показал, что глаз не испускает лучи, а принимает свет от предметов, и подкрепил это опытами с тёмной комнатой и отверстием.

Его «Книга оптики» в латинском переводе определила европейскую науку о свете на столетия и дала образец рассуждения, где вывод проверяется устройством, а не авторитетом.

Прикладной итог — очки, появившиеся в Италии в конце XIII века. Они продлили работоспособность писцов и ремесленников на десятилетия и резко расширили круг читающих.'),
  (94, 1, 't_astronomy_tables', 'Астрономические таблицы', 8, 5, 1, NULL, 'Обсерватории и вычисленные таблицы движения светил.', 'Исламские обсерватории от Багдада до Мараги и Самарканда вели систематические измерения на больших инструментах, добиваясь точности, недоступной глазу без многолетнего усреднения.

Итогом были зиджи — таблицы, по которым можно вычислить положение планеты на нужную дату. Толедские и Альфонсовы таблицы легли в основу европейской астрономии.

Накопленные расхождения таблиц с наблюдением и стали тем поводом, который заставит Коперника искать иную схему мира.'),
  (95, 1, 't_compass', 'Компас', 12, 5, 1, NULL, 'Магнитная стрелка на картушке: курс при пасмурном небе.', 'Компас пришёл в Средиземноморье из Китая и решил ту задачу, которая раньше останавливала плавание: при закрытом небе мореход терял и звёзды, и солнце.

Сухой компас с картушкой, насаженной на иглу, позволил читать курс прямо в румбах, а не гадать по колеблющейся стрелке в воде.

Следствие было хозяйственным: навигация перестала закрываться на зиму, и средиземноморская торговля перешла с одного круга плаваний в год на два.'),
  (96, 1, 't_cog', 'Когг и навесной руль', 12, 5, 1, NULL, 'Вместительное судно с рулём на ахтерштевне и одной мачтой.', 'Когг — судно грузовое: высокий борт, плоское днище, большой трюм. Он берёт втрое больше груза при том же экипаже, чем прежние ладьи, и потому дешевле в перевозке.

Навесной руль на ахтерштевне заменил рулевое весло и дал управление, не зависящее от силы рулевого. Это сделало возможными и рост размеров судна, и его манёвренность.

На когге держалась ганзейская торговля Балтики и Северного моря: зерно, лес, соль и сукно шли именно на нём.'),
  (97, 1, 't_mech_clock', 'Механические часы', 8, 5, 1, NULL, 'Башенные часы с боем: равномерный отсчёт времени независимо от солнца.', 'Механические часы с билянцевым регулятором появляются в европейских городах в конце XIII века. Точность их была невелика — расхождение в четверть часа за сутки, — но важно другое: они идут всегда.

До них час был долей светового дня и потому летом длиннее, чем зимой. Часы сделали его постоянным и уравняли время суток и время года.

Городская башня с боем задала распорядок работы, торга и школы. Впервые время стало общим расписанием, а не личным ощущением, — сдвиг, последствия которого трудно переоценить.'),
  (98, 1, 't_woodblock', 'Ксилографическая печать', 4, 5, 1, NULL, 'Оттиск с резной доски: гравюра, игральные карты, лубок, ранние книжки.', 'Резчик вырезает изображение и текст на доске целиком, оставляя выпуклым то, что должно отпечататься. Доска служит долго и даёт сотни оттисков.

Слабость очевидна: под каждую страницу нужна своя доска, а ошибка означает переделку. Поэтому ксилография прижилась там, где текст короток и повторяем — образки, карты, календари, азбуки.

Она приучила рынок к тиражной картинке и подготовила спрос, который затем удовлетворит наборный шрифт.'),
  (99, 1, 't_bill_exchange', 'Вексель и кредит', 17, 5, 1, NULL, 'Переводной вексель: перевод денег без перевозки монеты.', 'Вексель родился из потребности не возить серебро через опасные дороги: купец вносит деньги в одном городе и получает их в другом по письму, поданному партнёру менялы.

Разница курсов позволяла спрятать в сделке процент, формально запрещённый церковью, и вексель на века стал главным обходом запрета ростовщичества.

С ним появляется и понятие делового доверия: платёж обеспечен не залогом, а именем и сетью корреспондентов, ведущих счета друг друга.'),
  (100, 1, 't_banking', 'Банковское дело', 17, 5, 1, NULL, 'Депозит, безналичный перевод, филиалы и первые товарищества.', 'Итальянские дома XIII–XIV веков соединили обмен, вклад и кредит: клиент вносит деньги в одном отделении, распоряжается ими в другом, а банк ведёт счета обеих сторон и переводит суммы записью в книге.

Кредит государям приносил прибыль и губил банкиров: отказ английской короны платить разорил флорентийские дома Барди и Перуцци.

Тогда же складывается товарищество с долями и ограничением ответственности — форма, из которой вырастет вся позднейшая корпорация.'),
  (101, 1, 't_distillation', 'Дистилляция', 6, 5, 1, NULL, 'Перегонка: спирт, кислоты, эфирные масла, чистые вещества.', 'Перегонный куб позволяет разделить смесь по температуре кипения и получить то, чего в природе не встречается в чистом виде.

Спирт, полученный перегонкой вина, назвали «водой жизни» и применяли как лекарство и растворитель. Минеральные кислоты дали возможность разделять металлы и травить металлическую поверхность.

Дистилляция впервые дала химии понятие чистоты вещества: не «сильнее» или «слабее», а именно очищенное, повторяемое от опыта к опыту.'),
  (102, 1, 't_gunpowder', 'Порох', 6, 5, 1, NULL, 'Смесь селитры, серы и угля: химическая энергия вместо мускульной.', 'Порох изобрели в Китае, где его формула появляется в трактатах IX–XI веков, и применяли сначала в зажигательных и сигнальных устройствах.

Главная трудность — селитра: её выщелачивали из перепревшего навоза и земли хлевов, и селитряное дело стало отдельной, строго надзираемой отраслью.

Порох изменил соотношение сил: энергия выстрела больше не зависит от силы человека, и обученный годами лучник теряет преимущество перед стрелком, обученным за недели.'),
  (103, 1, 't_guild_production', 'Цеховое производство', 14, 5, 1, NULL, 'Мастерская с уставом: качество, ученичество и раздел рынка.', 'Цех задавал всё: рецепт, размер изделия, число подмастерьев, часы работы и цену. Это ограничивало произвол и обман, но и надёжно душило новшества, если они грозили устоявшемуся порядку.

Ученичество на годы вперёд связывало мастера и подростка договором и превращало передачу ремесла в правовой институт, а не в семейное дело.

Клеймо мастера — предок и торговой марки, и знака качества: по нему отвечали за изделие поимённо.'),
  (104, 1, 't_spinning_wheel', 'Прядильное колесо', 5, 5, 1, NULL, 'Прялка с колесом: втрое-вчетверо быстрее ручного веретена.', 'Ручное веретено — узкое место всего текстильного дела: на одного ткача нужно несколько прядильщиц. Колесо ускорило прядение в несколько раз, разом расширив это горло.

Позже добавили рогульку с катушкой, позволившую крутить нить и наматывать её одновременно, — прялка стала непрерывной.

Прядение оставалось преимущественно женской работой, дававшей заработок вне поля; английское слово spinster, «незамужняя», хранит память об этом ремесле.'),
  (105, 1, 't_polders', 'Осушение и польдеры', 19, 5, 1, NULL, 'Отвоевание земли у моря и болот: дамбы, каналы, ветряной водоподъём.', 'Польдер — участок, огороженный дамбой, из которого воду выкачивают наружу. Пока качали вручную и волами, площади были невелики; ветряной водоподъём сделал работу непрерывной и дешёвой.

Осушение требовало постоянного содержания дамб и потому породило особые объединения жителей с правом облагать сборами и принуждать к работам — одну из древнейших форм местного самоуправления.

Осушенный торфяник со временем проседает, и земля оказывается ниже уровня моря: отвоёванный участок навсегда становится зависим от насосов.'),
  (106, 1, 't_wool_trade', 'Товарное овцеводство', 11, 5, 1, NULL, 'Разведение овец на шерсть как рыночный товар, а не для своего двора.', 'Английская и испанская шерсть стала сырьём для фламандских и итальянских суконщиков, и целые области перешли от хлеба к овцам, потому что шерсть давала больше дохода с той же земли.

Испанская мериносовая система с сезонными перегонами стад между зимними и летними пастбищами получила королевскую защиту и особый суд.

Хозяйственные последствия оказались тяжёлыми: пастбище требует мало рук, и переход на овец вытеснял крестьян с земли — это отзовётся огораживаниями и социальными потрясениями следующих веков.'),
  (107, 1, 't_trigonometry', 'Тригонометрия', 18, 6, 1, NULL, 'Таблицы синусов и решение треугольников: расчёт недоступных расстояний.', 'Тригонометрия выросла из астрономии: чтобы вычислить положение светила, нужно уметь решать треугольник по неполным данным. Исламские математики ввели привычные нам функции и составили подробные таблицы.

Регимонтан в XV веке издал их в Европе отдельным трудом, оторвав от астрономии и сделав самостоятельным инструментом.

Отсюда всё прикладное измерение: высота башни, ширина реки, положение судна, дальность стрельбы. Тригонометрия — математика, которая напрямую кормила навигацию, артиллерию и съёмку местности.'),
  (108, 1, 't_nav_instruments', 'Навигационные приборы', 8, 6, 1, NULL, 'Квадрант, морская астролябия, лаг и таблицы склонения.', 'Морская астролябия и квадрант дают широту по высоте солнца в полдень или Полярной звезды ночью. Для этого нужны таблицы склонения — их составление стало государственной задачей в Португалии.

Долготу измерять не умели, поэтому путь считали счислением: курс по компасу, скорость по лагу, время по склянкам — и накопленная ошибка росла с каждым днём плавания.

Практика была такой: выйти на нужную широту, а затем идти вдоль неё до земли. Этот приём и определил маршруты великих плаваний.'),
  (109, 1, 't_caravel', 'Каравелла', 12, 6, 1, NULL, 'Судно для океана: косое парусное вооружение и малая осадка.', 'Каравелла соединила косой латинский парус, позволяющий круто идти к ветру, с корпусом, способным выдержать океанскую волну. Прежние суда либо не могли лавировать, либо не выдерживали открытого моря.

Малая осадка позволяла заходить в устья и обследовать незнакомый берег, а смешанное вооружение — переставлять паруса под задачу перехода.

Главное качество каравеллы — способность вернуться: португальцы прокладывали путь вдоль Африки, зная, что против ветра и течения им придётся выходить далеко в океан, чтобы поймать обратный ветер.'),
  (110, 1, 't_cannon_casting', 'Пушечное литьё', 1, 6, 1, NULL, 'Отливка стволов из бронзы и чугуна вместо кованых полос.', 'Ранние бомбарды ковали из полос, стянутых обручами, как бочку, и они нередко разрывались. Литой ствол однороден и держит несравнимо большее давление.

Бронза дороже, но надёжнее и не даёт осколков; чугун дешевле и позволил вооружить артиллерией флот и крепости массово.

Литейщик стал ключевой фигурой военного дела: калибры, вес заряда и толщина стенок рассчитывались по накопленным правилам, и это одна из первых областей, где практика потребовала таблиц и единых стандартов.'),
  (111, 1, 't_bombard', 'Бомбарда', 16, 6, 1, NULL, 'Тяжёлое осадное орудие: пролом каменной стены выстрелом.', 'Бомбарда бьёт редко — несколько выстрелов в день, — но каждое ядро делает то, чего требушет добивался неделями. Осада Константинополя в 1453 году показала это наглядно.

Высокие тонкие стены, рассчитанные на защиту от лестниц и камнемётов, оказались беззащитны против настильного удара ядра в основание.

Ответ последует быстро: стены станут ниже и толще, появятся земляные валы и бастионы. Артиллерия перекроила не только осаду, но и облик города.'),
  (112, 1, 't_arquebus', 'Аркебуза', 9, 6, 1, NULL, 'Ручное огнестрельное оружие с фитильным замком.', 'Аркебуза уступала луку в скорострельности и точности, но превосходила в главном: стрелка можно обучить за две недели, а пуля пробивает доспех, против которого стрела бессильна.

Фитильный замок требовал тлеющего фитиля, выдававшего стрелка ночью и гаснущего в дождь. Отсюда строй, где мушкетёров прикрывают пикинёры.

Сражение при Павии в 1525 году считают переломом: испанские аркебузиры расстроили и уничтожили цвет французской рыцарской конницы.'),
  (113, 1, 't_cuirassier', 'Кирасиры', 15, 6, 1, NULL, 'Конница в кирасе с пистолетами: залп с седла вместо копья.', 'С распространением огнестрельного оружия полный доспех потерял смысл: удержать пулю могла только кираса, а всё остальное стало лишним весом.

Появился новый приём боя — караколь: шеренги конницы подъезжают, стреляют из пистолетов и отходят перезаряжать, сменяя друг друга.

Приём быстро раскритиковали за то, что он лишает конницу главного — удара, — и к XVII веку кавалерия вернулась к сшибке холодным оружием, оставив пистолет как дополнение.'),
  (114, 1, 't_docks', 'Морские порты и доки', 10, 6, 1, NULL, 'Каменные причалы, склады, сухие доки и верфи постоянного действия.', 'Океанское плавание требует берегового хозяйства: судно нужно не только принять, но и снабдить, разгрузить, починить и сохранить груз.

Сухой док, где судно осушается для ремонта подводной части, — сооружение государственного масштаба: Портсмут получил его ещё в конце XV века.

Порт стягивал к себе всё: таможню, склады, страховщиков, вербовку экипажей и верфи. Города, сумевшие построить такое хозяйство, и стали центрами морской торговли.'),
  (115, 1, 't_plantation', 'Плантационное земледелие', 11, 6, 1, NULL, 'Монокультура на экспорт: сахар, табак, хлопок на больших массивах.', 'Плантация — не крестьянское хозяйство, а предприятие: одна культура, единый распорядок работ, переработка на месте и вывоз готового товара за океан.

Сахарный тростник задал образец ещё на атлантических островах, а затем эта модель была перенесена в Америку в огромном масштабе.

Экономика плантации держалась на принудительном труде: работа однообразна, тяжела и не требует квалификации, и именно на этом выросла трансатлантическая работорговля — прямое следствие технологии, а не только злой воли.'),
  (116, 1, 't_columbian_exchange', 'Колумбов обмен', 19, 6, 1, NULL, 'Взаимный перенос культур, животных и болезней между полушариями.', 'Кукуруза, картофель, томат, какао и табак ушли в Старый Свет; пшеница, сахарный тростник, лошадь и корова — в Новый. Картофель и кукуруза позже вдвое увеличат продовольственную базу Европы и Китая.

Обратной стороной стал перенос болезней: у населения Америки не было иммунитета к оспе и кори, и потери были катастрофическими — по оценкам, до девяти десятых населения в отдельных областях.

Это крупнейшее биологическое событие в истории человечества, вызванное исключительно техникой мореплавания.'),
  (117, 1, 't_colonial_harvest', 'Колониальные промыслы', 3, 6, 1, NULL, 'Добыча заморского сырья: пряности, меха, серебро, красильное дерево.', 'Заморские владения ценились прежде всего как источник того, чего нет дома: перца и гвоздики, мехов, красильной древесины и, главное, серебра.

Серебро Потоси и Сакатекаса хлынуло в Европу и через неё в Азию, вызвав долгий рост цен, который историки называют революцией цен, и связав денежные системы разных континентов.

Промысел строился на выкачивании, а не на развитии: рудник, факторию и порт устраивали ради вывоза, и хозяйственный уклад колоний надолго определился этой задачей.'),
  (118, 1, 't_portolan', 'Портуланы и морские карты', 4, 6, 1, NULL, 'Карты побережий с сеткой румбов и описанием опасностей.', 'Портулан — карта, построенная не по координатам, а по компасным направлениям: сетка лучей позволяет проложить курс линейкой прямо между портами.

Точность очертаний Средиземноморья на них поразительна, зато удалённые области рисовались по слухам, и карты бывали одновременно надёжными и фантастическими.

Карты стали государственной тайной: португальский и испанский дворы держали образцовые экземпляры под запретом вывоза, поскольку знание пути стоило дороже самого груза.'),
  (119, 1, 't_quarantine', 'Карантин и лазареты', 7, 6, 1, NULL, 'Изоляция прибывших на сорок дней и городская санитарная служба.', 'После чумы XIV века портовые города ввели обязательное задержание судов и прибывших. Итальянское quaranta giorni — сорок дней — дало имя всей мере.

Теория о причинах болезни была неверной, но мера работала: разрыв цепочки передачи не требует понимания возбудителя.

Это первый пример общественного здравоохранения: город берёт на себя право ограничить свободу передвижения ради общей безопасности и создаёт для этого постоянную службу с врачами, лазаретом и записями.'),
  (120, 1, 't_univ_medicine', 'Университетская медицина', 7, 6, 1, NULL, 'Врач с дипломом: канон текстов, экзамен и право практики.', 'Медицинские школы Салерно, Монпелье и Болоньи сделали врачевание учёной профессией: курс, экзамен, степень и право практиковать, отделяющее врача от цирюльника и знахаря.

Обучение опиралось на канон Галена и Авиценны, а вскрытие долго служило лишь иллюстрацией к тексту: увиденное расхождение объясняли ошибкой глаза, а не книги.

Тем не менее сложилось главное — сообщество, спорящее по правилам и хранящее общий корпус знания, без которого позднейший переворот в медицине был бы невозможен.'),
  (121, 1, 't_post_roads', 'Почтовые тракты', 13, 6, 1, NULL, 'Станции смены лошадей и регулярная доставка сообщений.', 'Почта — это не дорога, а расписание: цепочка станций, где гонец меняет лошадь и едет дальше, тогда как усталая отдыхает. Скорость определяется частотой станций.

Семейство Таксис веками держало имперскую почту и превратило её в предприятие, возившее и частные письма за плату.

Регулярная почта сделала возможными и управление на расстоянии, и деловую переписку, и, позже, газету: без предсказуемой доставки нет ни векселя в срок, ни свежей новости.'),
  (122, 1, 't_double_entry', 'Двойная бухгалтерия', 17, 6, 1, NULL, 'Запись каждой операции дважды: проверяемый баланс дела.', 'Двойная запись фиксирует не только что получено, но и откуда, поэтому итог по дебету всегда сходится с итогом по кредиту, а ошибка обнаруживается сама.

Лука Пачоли изложил метод в 1494 году, описав уже сложившуюся венецианскую практику; печатный станок разнёс её по Европе.

Главное следствие — понятие прибыли: становится видно, зарабатывает ли дело в целом, а не удачна ли отдельная поездка. Отсюда возможность вести предприятие постоянно и отвечать перед вкладчиками.'),
  (123, 1, 't_manufactory', 'Мануфактурное производство', 14, 6, 1, NULL, 'Разделение операций под одной крышей при ручном труде.', 'Мануфактура ещё не знает машины, но уже разбивает изготовление на простые операции, закреплённые за отдельными работниками. Выигрыш даёт не техника, а порядок.

Она обходит цеховые ограничения: работника нанимают, а не принимают в мастера, и хозяин свободен в числе рук и в приёмах.

Рассеянная мануфактура раздавала сырьё по деревенским домам и собирала готовое — так промышленность впервые вышла за стены города и втянула в себя крестьянский труд.'),
  (124, 1, 't_early_chemistry', 'Ранняя химия', 6, 6, 1, NULL, 'Пробирное дело, минеральные кислоты, аптечное и рудничное вещество.', 'Пробирное искусство — определение содержания металла в руде взвешиванием после плавки — стало первой количественной химией: результат выражался числом и проверялся повтором.

Агрикола в трактате о горном деле описал печи, реактивы и приёмы разделения металлов так подробно, что книга служила руководством два столетия.

Парацельс развернул химию к медицине, утверждая, что действует не форма вещества, а его начало, и что дозой определяется, лекарство перед нами или яд.'),
  (125, 1, 't_powder_mill', 'Зернение пороха', 2, 6, 1, NULL, 'Пороховая мельница и зернение: устойчивая мощная навеска.', 'Мякотный порох слёживался и расслаивался при перевозке, отчего выстрел выходил непредсказуемым. Зернение — увлажнение массы, прессование и дробление на зёрна — решило обе беды сразу.

Зерно горит быстрее и полнее, поэтому мощность выстрела заметно выросла; ранние стволы, рассчитанные на слабую мякоть, такого не выдерживали и требовали переделки.

Пороховая мельница на водяном приводе стала опасным, но необходимым казённым производством, а размер зерна — первым артиллерийским стандартом: своя фракция для пушки, своя для ружья.'),
  (126, 1, 't_printing_press', 'Печатный станок', 4, 7, 1, NULL, 'Наборный шрифт и пресс: одинаковая книга сотнями экземпляров.', 'Гутенберг соединил три вещи: разборный литой шрифт, масляную краску, держащуюся на металле, и винтовой пресс. Ключ — не пресс, а словолитная форма, дающая тысячи одинаковых литер.

Себестоимость книги упала в десятки раз. За полвека Европа напечатала больше текстов, чем переписала за предыдущее тысячелетие.

Главное следствие — точная копия. Раньше каждое переписывание вносило ошибки; теперь тысячи читателей видят один и тот же текст с одними и теми же чертежами и таблицами, и на это можно ссылаться. Наука получила возможность спорить по существу.'),
  (127, 1, 't_precision_metal', 'Точная металлообработка', 1, 7, 1, NULL, 'Опиловка, нарезка резьбы, шестерни и подгонка по размеру.', 'Часовое и оружейное дело потребовали работы с долями миллиметра: шестерня, пружина, винт и ствол не работают при грубой подгонке.

Появились винтовая резьба как соединение, а не диковина, делительная головка для нарезки зубьев и первые меры для проверки размера.

Мастер-механик становится отдельной фигурой: он не кузнец и не литейщик, а человек, изготавливающий приборы по чертежу. Без него не будет ни телескопа, ни насоса, ни паровой машины.'),
  (128, 1, 't_heliocentric', 'Гелиоцентрическая система', 8, 7, 1, NULL, 'Солнце в центре: движение планет как следствие устройства мира.', 'Коперник в 1543 году предложил поставить в центр Солнце — не потому, что имел новые наблюдения, а потому, что так система выходила стройнее, объясняя попятные движения планет естественно.

Точность пришла позже: Тихо Браге накопил измерения невиданной точности, а Кеплер, разбирая их, отказался от круга и вывел эллиптические орбиты и законы движения.

Спор был не только астрономическим. Отняв у Земли центральное место, гелиоцентризм столкнулся с богословием и стал первым большим случаем конфликта научного вывода с общепринятой картиной мира.'),
  (129, 1, 't_telescope', 'Телескоп и микроскоп', 8, 7, 1, NULL, 'Приборы, расширяющие зрение: спутники Юпитера и мир мельчайшего.', 'Телескоп появился как забава голландских очковых мастеров, но Галилей направил его в небо и за год увидел горы на Луне, фазы Венеры и спутники Юпитера — прямые свидетельства против неподвижной Земли в центре.

Микроскоп открыл другую бесконечность: Гук описал ячейки пробки и назвал их клетками, Левенгук увидел движущихся «зверушек» в капле воды.

Впервые прибор стал источником фактов, недоступных ни одному авторитету древности. Спорить с книгой стало можно, просто предложив посмотреть в окуляр.'),
  (130, 1, 't_galileo', 'Механика Галилея', 18, 7, 1, NULL, 'Опыт и математика: равноускоренное падение, инерция, маятник.', 'Галилей заменил рассуждение о природе тел измерением их движения: скатывая шары по наклонной плоскости и отмеряя время, он показал, что путь растёт как квадрат времени независимо от веса.

Отсюда принцип инерции: тело сохраняет движение само по себе, и объяснения требует не движение, а его изменение. Это переворачивает физику Аристотеля.

Метод оказался важнее выводов: поставить опыт, выразить результат числом, найти закон и проверить его предсказанием. Именно этот порядок и назовут естествознанием.'),
  (131, 1, 't_anatomy', 'Анатомия', 7, 7, 1, NULL, 'Вскрытие и точный атлас: строение тела по наблюдению, а не по книге.', 'Везалий в 1543 году издал атлас, построенный на собственных вскрытиях, и открыто указал десятки мест, где Гален ошибался, потому что вскрывал животных, а не людей.

Решающую роль сыграл печатный станок: гравюры позволили показать увиденное точно и одинаково всем читателям — словесное описание тела почти бесполезно.

Так утвердился принцип, ставший основой медицины: смотреть самому и доверять увиденному больше, чем авторитету текста.'),
  (132, 1, 't_circulation', 'Кровообращение', 7, 7, 1, NULL, 'Замкнутый круг кровотока: сердце как насос.', 'Гарвей в 1628 году привёл довод, который трудно оспорить: сердце за час прогоняет крови больше, чем весит человек, значит, кровь не создаётся заново, а возвращается по кругу.

Он подкрепил это опытами с перевязкой вен и наблюдением клапанов, пропускающих кровь только к сердцу. Капилляры, замыкающие круг, увидели позже в микроскоп.

Это первый случай, когда работу органа объяснили количественным расчётом, а не описанием. С Гарвея физиология становится наукой об измеримых процессах.'),
  (133, 1, 't_iatrochemistry', 'Ятрохимия', 6, 7, 1, NULL, 'Химические препараты в медицине и понятие дозы.', 'Парацельс утверждал, что болезнь — расстройство химических начал тела, и лечить её надо веществом: солями ртути, сурьмы, железа. Часть препаратов работала, часть калечила.

Ему же принадлежит мысль, ставшая основой токсикологии: всё есть яд и всё есть лекарство, различает их только доза.

Ятрохимия столкнула аптеку с лабораторией: аптекарь стал изготовителем препаратов по прописи, а спор о минеральных лекарствах на век расколол медицинский цех.'),
  (134, 1, 't_technical_drawing', 'Чертёж и проекция', 14, 7, 1, NULL, 'Перспектива и проекционный чертёж: замысел, передаваемый без слов.', 'Возрождение решило задачу изображения пространства: перспектива дала правило, по которому объём переносится на плоскость и обратно.

Для техники важнее оказалась ортогональная проекция — вид спереди, сверху и сбоку, по которым деталь восстанавливается однозначно и может быть изготовлена другим человеком в другом городе.

Чертёж отделил замысел от изготовления. Конструктор и мастер стали разными людьми, а машина — предметом, который можно спроектировать заранее.'),
  (135, 1, 't_bastion', 'Бастионная фортификация', 10, 7, 1, NULL, 'Низкие земляные валы и бастионы: крепость против артиллерии.', 'Высокая стена — идеальная мишень для ядра. Ответ оказался геометрическим: низкий толстый вал, гасящий удар землёй, и выступающие пятиугольные бастионы, простреливающие подступы вдоль стен, чтобы у осаждающего не осталось мёртвых зон.

Такая крепость проектируется расчётом: углы бастионов, длина фасов и дальность выстрела связаны между собой, и это первая архитектура, целиком выведенная из числа.

Стоила она дорого и надолго стала главной статьёй военных расходов, подталкивая рост налогов и государственного аппарата.'),
  (136, 1, 't_classicism_arch', 'Архитектура классицизма', 10, 7, 1, NULL, 'Ордер, пропорция и трактат: архитектура как правило, а не традиция.', 'Альберти и Палладио переосмыслили Витрувия и превратили античный ордер в систему пропорций, которую можно изложить в книге и применить где угодно.

Печатный трактат с гравюрами разнёс эти правила по Европе: заказчик и мастер получили общий язык, и здание стало строиться по образцу, а не по памяти артели.

Так родилась профессия архитектора в современном смысле — автора замысла, отвечающего за композицию целого, а не старшины строителей.'),
  (137, 1, 't_field_artillery', 'Полевая артиллерия', 16, 7, 1, NULL, 'Подвижное орудие на лафете: пушка в полевом сражении.', 'Осадная бомбарда неподвижна. Полевое орудие на колёсном лафете едет с войском, разворачивается за минуты и стреляет по строю картечью и ядром.

Стандартизация калибров и заранее отмеренных зарядов резко подняла скорострельность и позволила рассчитывать снабжение боеприпасами.

Артиллерия стала родом войск со своей школой, счётом и офицером-математиком: стрельба требовала таблиц и понимания траектории, а не только храбрости.'),
  (138, 1, 't_musket', 'Мушкет', 9, 7, 1, NULL, 'Тяжёлое ружьё с сошкой: пуля, пробивающая любой доспех.', 'Мушкет крупнее и мощнее аркебузы: его пуля пробивала кирасу на дистанции, где доспех ещё имел смысл. Из-за веса стреляли с сошки.

Строй мушкетёров с пикинёрами стал основой пехоты: пики держат конницу, мушкеты ведут огонь сменяющимися шеренгами.

Именно мушкет окончательно похоронил рыцарский доспех: защита, останавливающая пулю, оказалась слишком тяжёлой, чтобы в ней воевать.'),
  (139, 1, 't_dragoons', 'Драгуны', 15, 7, 1, NULL, 'Ездящая пехота: подвижность конницы и огонь пехоты.', 'Драгун едет верхом, а дерётся пеший. Это дало армии способность быстро занять переправу, деревню или высоту силами, которые затем удерживают позицию огнём.

Лошадь драгуна дешевле строевой, выучка проще, поэтому драгунские полки было быстрее сформировать — важное качество в долгих войнах эпохи.

Со временем драгуны втянулись в собственно кавалерию, но сама идея посаженной на транспорт пехоты дожила до мотопехоты нашего времени.'),
  (140, 1, 't_galleon', 'Галеон', 12, 7, 1, NULL, 'Океанский корабль с артиллерийскими палубами и пушечными портами.', 'Галеон — судно, спроектированное вокруг пушек: батарейные палубы, порты в борту, закрывающиеся крышками, и корпус, рассчитанный на вес и отдачу артиллерии.

Пушечный порт позволил ставить тяжёлые орудия низко, у ватерлинии, не теряя остойчивости, — до этого артиллерию держали на надстройках, и корабль опрокидывался.

Морской бой окончательно перешёл от абордажа к артиллерийской дуэли, а флот — к постоянному государственному хозяйству с верфями, арсеналами и уставом.'),
  (141, 1, 't_canals_locks', 'Каналы и шлюзы', 13, 7, 1, NULL, 'Судоходный канал с камерными шлюзами: путь через водораздел.', 'Камерный шлюз с двумя воротами позволяет поднять судно на ступень: камера заполняется, судно всплывает, ворота открываются. Так канал перестал зависеть от рельефа.

Канал дю Миди во Франции соединил Атлантику со Средиземным морем, пройдя водораздел и потребовав отдельного водохранилища для питания верхнего участка.

Водный путь долго оставался самым дешёвым: одна лошадь тянет по воде груз, для которого на дороге нужен обоз. Именно каналы, а не шоссе, обслуживали раннюю промышленность.'),
  (142, 1, 't_joint_stock', 'Акционерные компании', 17, 7, 1, NULL, 'Складочный капитал, доли и постоянное предприятие вместо разовой поездки.', 'Ост-Индские компании собрали капитал не под одно плавание, а под дело без срока: доля не гасится по возвращении судна, её можно продать другому.

Отсюда вырос вторичный рынок долей и вместе с ним биржевая спекуляция — амстердамский рынок акций сложился уже в начале XVII века.

Компании получали от государства монополии, право войны и суда в заморских землях, и различие между торговым предприятием и властью на десятилетия стёрлось.'),
  (143, 1, 't_logarithms', 'Логарифмы', 20, 7, 1, NULL, 'Замена умножения сложением: таблицы и счётная линейка.', 'Непер заметил, что если сопоставить числам показатели степени, то умножение сводится к сложению. Таблицы логарифмов сократили труд астронома и штурмана в разы.

Счётная линейка перенесла тот же принцип на две скользящие шкалы и дала мгновенный приблизительный расчёт — инструмент, дослуживший инженерам до конца XX века.

Значение выходит за арифметику: впервые вычисление было сознательно упрощено заменой одной операции другой. Это способ мышления, из которого позже вырастет вся вычислительная техника.'),
  (144, 1, 't_horticulture', 'Огородничество и селекция', 11, 7, 1, NULL, 'Отбор сортов, огород и сад как товарное хозяйство.', 'Заморские культуры требовали приспособления: картофель, кукурузу и томат десятилетиями отбирали под местный климат, прежде чем они дали урожай.

Голландское огородничество превратило пригород в товарное хозяйство с интенсивным удобрением, парниками и специализацией на овощах и цветах для городского рынка.

Сознательный отбор растений задолго до генетики опирался на простое наблюдение: сеять от лучшего. Именно на этой практике позже будет построена вся селекция.'),
  (145, 1, 't_cannon_boring', 'Сверлильный станок', 14, 7, 1, NULL, 'Рассверливание ствола из цельной отливки вместо литья по сердечнику.', 'Ствол, отлитый вокруг сердечника, всегда имел кривой и неровный канал. Вильгельм Марицу предложил лить сплошную болванку и высверливать канал вращающимся резцом, что дало прямой и точный ствол.

Точность канала сразу повысила дальность и кучность и позволила уменьшить толщину стенок, облегчив орудие.

Значение станка вышло далеко за артиллерию: именно расточка цилиндров с той же точностью сделает позже возможной паровую машину Уатта.'),
  (146, 1, 't_pumps', 'Насосы и водоподъём', 2, 7, 1, NULL, 'Поршневой и всасывающий насос: борьба с водой в шахте.', 'Глубокая шахта тонет, и водоотлив был главным ограничением горного дела. Поршневые насосы, приводимые водяным колесом или лошадьми, поднимали воду ступенями по нескольку десятков метров.

Тогда же выяснилось странное: всасывающий насос не поднимает воду выше десяти метров. Объяснение — давление атмосферы — дали Торричелли и Паскаль, и оно стало одним из первых физических открытий, рождённых прямо из техники.

Из этого же тупика вырастет паровая машина: раз воздух давит, его можно заставить работать, создав под поршнем пустоту.'),
  (147, 1, 't_scientific_method', 'Научный метод и академии', 8, 8, 1, NULL, 'Опыт, публикация и проверка: наука как постоянное учреждение.', 'Лондонское королевское общество и Парижская академия превратили разрозненные занятия в institution: заседание, демонстрация опыта, протокол и журнал.

Ключевым стало требование воспроизводимости: опыт описывают так, чтобы его мог повторить другой, и только тогда результат считается установленным.

Появилась научная переписка и приоритет открытия, а вместе с ними — фигура учёного как признанного обществом занятия, а не чудака при дворе.'),
  (148, 1, 't_calculus', 'Дифференциальное исчисление', 18, 8, 1, NULL, 'Математика непрерывного изменения: производная и интеграл.', 'Ньютон и Лейбниц независимо создали аппарат для работы с мгновенной скоростью и площадью под кривой. Спор об их первенстве отравил отношения английской и континентальной математики на десятилетия.

Обозначения Лейбница оказались удобнее и победили; ими пользуются и сегодня.

Значение шире математики: впервые появился язык для описания процессов, а не состояний. Всё позднейшее естествознание — от механики до экономики — говорит на нём.'),
  (149, 1, 't_gravitation', 'Теория гравитации', 18, 8, 1, NULL, 'Один закон для яблока и планеты: всемирное тяготение.', 'Ньютон показал, что сила, роняющая тело на Землю, и сила, удерживающая Луну на орбите, — одна и та же, и что из закона обратных квадратов выводятся законы Кеплера.

«Начала» 1687 года дали образец физической теории: несколько аксиом, математический вывод следствий и проверка их наблюдением.

Предсказательная сила поразила современников: возвращение кометы Галлея в рассчитанный срок и позже открытие Нептуна «на кончике пера» стали доводами, которые невозможно оспорить.'),
  (150, 1, 't_electrostatics', 'Электростатика', 18, 8, 1, NULL, 'Заряд, лейденская банка и опыты с молнией.', 'Электричество из салонного фокуса превратилось в предмет исследования, когда лейденская банка позволила накапливать заряд и получать ощутимый разряд.

Франклин показал, что молния и лабораторная искра — одно и то же явление, и вывел из этого громоотвод: редкий случай, когда чистое любопытство сразу дало полезное устройство.

Тогда же сложилось понятие двух зарядов и их сохранения. Всё это ещё статика — тока не было, пока Вольта не построил столб, — но язык будущей электротехники рождается здесь.'),
  (151, 1, 't_crucible_steel', 'Тигельная сталь', 1, 8, 1, NULL, 'Плавка стали в закрытом тигле: однородный металл заданного состава.', 'Хантсмен в 1740-х годах научился расплавлять цементованную сталь в закрытом тигле. Расплав однороден: шлак всплывает, состав выравнивается, и слиток не имеет прослоек.

Такая сталь нужна была прежде всего часовым пружинам и инструменту, а затем режущей кромке станков — то есть тому, от чего зависела точность всей техники.

Шеффилд стал центром производства, а сам приём оставался дорогим: тигельная сталь мерялась килограммами, тогда как чугун — тоннами. Массовую сталь даст только Бессемер столетием позже.'),
  (152, 1, 't_civil_engineering', 'Гражданское строительство', 10, 8, 1, NULL, 'Расчёт сооружений: мосты, порты, дороги и первые инженерные школы.', 'Появление инженера как профессии связано с французской школой мостов и дорог, где будущего строителя учили математике, механике и черчению, а не подмастерьем при артели.

Расчёт сменил традицию: балку, свод и опору стали проверять по нагрузке заранее, а не подбирать сечение с запасом по опыту.

Слово civil — «гражданский» — появилось, чтобы отделить эту работу от военной фортификации, из которой она и выросла.'),
  (153, 1, 't_flintlock', 'Кремнёвый мушкет', 9, 8, 1, NULL, 'Ударно-кремнёвый замок и штык: пехота без пикинёров.', 'Кремнёвый замок высекает искру ударом при спуске: не нужно ни тлеющего фитиля, ни укрытия от дождя и ветра. Осечки остались, но ружьё стало пригодно для любой погоды и для строя.

Втульчатый штык надевался на ствол, не мешая стрельбе, и разом сделал пикинёров ненужными: каждый пехотинец стал и стрелком, и копейщиком.

Из этого выросла линейная тактика: развёрнутый в три шеренги батальон даёт залп, а затем идёт в штыки. Такая пехота продержалась почти полтора века.'),
  (154, 1, 't_light_cavalry', 'Лёгкая кавалерия', 15, 8, 1, NULL, 'Гусары и уланы: разведка, набег и преследование.', 'Когда пехота с ружьями стала способна отбить лобовую атаку, конница нашла себя в другом: разведке, налёте на обозы, прикрытии отхода и преследовании разбитого противника.

Гусарские полки, заимствованные из венгерской практики, распространились по всем европейским армиям вместе с формой и повадкой.

Ценность лёгкой конницы была прежде всего в сведениях: до появления телеграфа и авиации полководец видел глазами своих разъездов, и от них зависело всё планирование.'),
  (155, 1, 't_ship_of_line', 'Линейный корабль', 12, 8, 1, NULL, 'Трёхдечный корабль для боя в кильватерной колонне.', 'Линейная тактика на море требовала однотипных кораблей: колонна идёт кильватером и ведёт огонь бортом, а слабое звено разрывает строй. Отсюда деление кораблей по рангам и запрет ставить в линию суда ниже определённого класса.

Корпус проектировался вокруг веса артиллерии — до сотни орудий на трёх палубах, — и постройка требовала многолетней выдержки корабельного леса, который заготавливали за десятилетия вперёд.

Линейный корабль был самым сложным изделием эпохи, а флот — крупнейшим государственным предприятием со своими верфями, лесными угодьями и школами.'),
  (156, 1, 't_chronometer', 'Хронометр и долгота', 8, 8, 1, NULL, 'Точные морские часы: определение долготы в открытом море.', 'Долгота — это разница времени: зная точное время порта отправления и полдень на борту, штурман получает своё положение. Задача упиралась в часы, идущие точно на качке и при перепадах температуры.

Британский парламент назначил за решение огромную премию, и Джон Гаррисон потратил десятилетия, доведя хронометр до ошибки в считанные секунды за плавание.

С хронометром судовождение перестало быть искусством догадки: положение судна стало вычисляемым, а кораблекрушения из-за ошибки в счислении — редкостью.'),
  (157, 1, 't_clinical_med', 'Клиническая медицина', 7, 8, 1, NULL, 'Больница как школа: осмотр у постели, история болезни, вскрытие.', 'Лейденская, а затем венская школа поставили обучение у постели больного: студент видит течение болезни, ведёт запись и сопоставляет её с тем, что находят при вскрытии.

Так родилась патологическая анатомия: Морганьи сопоставил тысячи вскрытий с прижизненными жалобами и показал, что у болезни есть определённое место в теле.

Больница из приюта для бедных превратилась в учреждение, где лечат и учат, а история болезни — в документ, позволяющий сравнивать случаи между собой.'),
  (158, 1, 't_vaccination', 'Вакцинация', 7, 8, 1, NULL, 'Прививка коровьей оспы: защита без риска заболеть.', 'До Дженнера применяли вариоляцию — намеренное заражение лёгкой формой натуральной оспы, которая давала защиту, но убивала часть привитых.

Дженнер в 1796 году проверил народное наблюдение: доярки, переболевшие коровьей оспой, не заболевают человеческой. Прививка безопасного возбудителя давала защиту без смертельного риска.

Это первый случай, когда болезнь научились предупреждать целенаправленно, не зная её возбудителя. Оспа впоследствии станет единственной болезнью человека, полностью уничтоженной прививками.'),
  (159, 1, 't_stagecoach', 'Дилижансы и шоссе', 13, 8, 1, NULL, 'Регулярное пассажирское сообщение по дорогам с твёрдым покрытием.', 'Дорога с щебёночным покрытием и водоотводом, которую связывают с именами Телфорда и Мак-Адама, впервые за полторы тысячи лет вернула Европе всепогодный путь.

Дилижанс шёл по расписанию со сменой лошадей на станциях, и время в пути между крупными городами сократилось в несколько раз.

Расписание потребовало общего времени и подготовило то, что доведёт до конца железная дорога: жизнь по часам, одинаковым для разных городов.'),
  (160, 1, 't_optical_telegraph', 'Оптический телеграф', 4, 8, 1, NULL, 'Цепь семафорных вышек: сообщение через страну за часы.', 'Система Шаппа состояла из вышек в пределах видимости друг друга; поворотные перекладины складывались в знаки, которые следующий пост считывал в трубу и повторял.

Депеша через Францию проходила за считанные часы вместо дней — впервые в истории сообщение обогнало гонца.

Ограничения были жёсткими: ночь, туман и дождь останавливали линию, а содержание постов стоило дорого, поэтому телеграф оставался государственным и почти исключительно военным.'),
  (161, 1, 't_exchanges', 'Биржи и страхование', 17, 8, 1, NULL, 'Организованный рынок бумаг и распределение риска между многими.', 'Биржа свела покупателей и продавцов в одном месте и в одно время, и цена стала публичной. Появились срочные сделки, а с ними и первые биржевые крахи — тюльпанная горячка и Компания Южных морей.

Страхование выросло из морской торговли: подписчики брали на себя долю риска плавания за долю премии, и лондонская кофейня Ллойда стала центром этого дела.

Основой расчёта стала статистика смертности и кораблекрушений — первый случай, когда деньгами управляли по вероятности, а не по чутью.'),
  (162, 1, 't_division_labor', 'Разделение труда на производстве', 14, 8, 1, NULL, 'Разбиение работы на простые операции и рост выработки.', 'Адам Смит начал «Богатство народов» с булавочной мастерской: один работник сделает едва десяток булавок в день, а восемнадцать операций, разделённых между людьми, дают тысячи на человека.

Выигрыш даёт не только навык, но и экономия на переходах между операциями и возможность приспособить инструмент под одно действие.

Смит же назвал и цену: однообразный труд отупляет работника, и это, по его словам, требует ответа со стороны общества — замечание, которое вспомнят через столетие.'),
  (163, 1, 't_pneumatic_chem', 'Пневматическая химия и кислород', 6, 8, 1, NULL, 'Газы как вещества; вес в реакции; конец теории флогистона.', 'Выделив и собрав углекислый газ, водород и кислород, химики впервые получили возможность работать с газом как с обычным веществом, а не с «воздухом вообще».

Лавуазье поставил на этом весы: тщательно взвешивая до и после, он показал, что горение — соединение с кислородом, а масса в реакции сохраняется. Флогистон оказался лишним.

Он же ввёл систематическую номенклатуру, и химия получила язык, на котором её утверждения стали проверяемыми и переводимыми.'),
  (164, 1, 't_calc_machines', 'Счётные машины', 20, 8, 1, NULL, 'Механический арифмометр: сложение и умножение шестернями.', 'Машина Паскаля складывала и вычитала переносом через зубчатую передачу; Лейбниц добавил ступенчатый валик и получил умножение повторным сложением.

Практическое распространение задержалось на век: точность деталей была на пределе тогдашних мастерских, и машины оставались дорогими диковинами.

Важна была идея: расчёт можно поручить механизму. Лейбниц тогда же рассуждал о двоичной записи и о том, что рассуждение можно свести к вычислению, — мысль, до которой техника дорастёт только в XX веке.'),
  (165, 1, 't_newcomen', 'Первые паровые машины', 2, 8, 1, NULL, 'Атмосферная машина для откачки воды из шахт.', 'Машина Ньюкомена работала не давлением, а пустотой: пар заполнял цилиндр, впрыснутая вода конденсировала его, и атмосферное давление вгоняло поршень внутрь.

Коэффициент полезного действия был ничтожен, но у шахты уголь под ногами, поэтому расход топлива не имел значения. Десятки таких машин десятилетиями откачивали воду на рудниках.

Главное — принцип доказан: тепло можно превратить в работу. Всё дальнейшее развитие будет борьбой за то, чтобы делать это экономно.'),
  (166, 1, 't_linnaeus', 'Систематика Линнея', 21, 8, 1, NULL, 'Двойное латинское имя и иерархия рангов: порядок в живом мире.', 'Линней ввёл двухсловное название — род и вид — и выстроил соподчинение групп. Система была искусственной, опиралась на удобные признаки, но давала главное: любой организм получал однозначное имя, понятное во всех странах.

Это сделало возможным обмен образцами и описаниями между натуралистами разных стран и превратило коллекционирование в науку.

Иерархия групп сама подсказывала вопрос о причине сходства, на который через столетие ответит теория эволюции.'),
  (167, 1, 't_barometer', 'Барометр и метеонаблюдения', 19, 8, 1, NULL, 'Приборы для воздуха: давление, температура, влажность, сеть наблюдений.', 'Барометр Торричелли показал, что воздух имеет вес и что его давление меняется; связь падения ртути с приближением непогоды заметили почти сразу.

Термометр потребовал общей шкалы: предложения Фаренгейта и Цельсия сделали показания сравнимыми между городами, без чего наблюдения бессмысленны.

Из этого выросли первые сети наблюдателей, ведущих записи по единому образцу, — прообраз всей позднейшей службы погоды и вообще массового научного наблюдения.'),
  (168, 1, 't_balloon', 'Аэростаты', 22, 8, 1, NULL, 'Полёт на тёплом воздухе и водороде: человек поднимается в небо.', 'Братья Монгольфье в 1783 году подняли оболочку тёплым воздухом, а через считанные месяцы Шарль применил водород, который держит подъёмную силу несравнимо дольше.

Аэростат неуправляем: он летит туда, куда дует ветер. Поэтому применение нашлось прежде всего наблюдательное — привязной шар над полем боя как вышка.

Значение было и научным: подъём с приборами дал первые измерения давления, температуры и состава воздуха на высоте.'),
  (169, 1, 't_norfolk', 'Норфолкский севооборот и сеялка', 11, 8, 1, NULL, 'Четырёхполье без пара, кормовые культуры и рядовой посев.', 'Норфолкская система убрала пар вовсе: чередование пшеницы, репы, ячменя и клевера держит землю в работе постоянно, а клевер возвращает ей азот.

Репа и клевер дали зимний корм, и скот перестали забивать осенью. Больше скота — больше навоза, а значит, и урожая: система замкнулась сама на себя.

Рядовая сеялка Джетро Талла клала зерно на равную глубину полосами, что позволило полоть междурядья и резко сократило расход семян по сравнению с разбросным посевом.'),
  (170, 1, 't_machine_tools', 'Станок с суппортом и калибры', 14, 9, 1, NULL, 'Резец, ведомый механически, и измерение по калибру: одинаковые детали.', 'Пока резец держала рука, точность зависела от мастера. Суппорт Модсли ведёт резец по направляющим винтом, и деталь получается такой, как задано чертежом, у любого рабочего.

Витворт добавил меры: эталонные плоскости, калибры и единую резьбу. Гайка перестала быть подогнанной к своему болту и стала взаимозаменяемой.

Это ключевая технология всей промышленной эпохи: машины начали делать машины, и точность перестала быть редким искусством, превратившись в свойство оборудования.'),
  (171, 1, 't_coal_mines', 'Угольные шахты', 3, 9, 1, NULL, 'Массовая добыча каменного угля: топливо, не зависящее от леса.', 'Европа подошла к пределу дровяного хозяйства: лес свели, а металлургия и города требовали всё больше топлива. Уголь снял этот предел разом.

Глубокие шахты потребовали откачки, вентиляции и подъёмников, а также рельсовых путей под землёй — все эти решения затем вышли на поверхность.

Уголь привязал промышленность к месторождению: заводы стали расти не там, где торговый путь, а там, где пласт, и это перекроило хозяйственную карту.'),
  (172, 1, 't_steam_engine', 'Паровой двигатель', 2, 9, 1, NULL, 'Машина Уатта с отдельным конденсатором и вращательным ходом.', 'Уатт заметил, что охлаждение цилиндра при каждом такте — главная потеря, и вынес конденсацию в отдельный сосуд. Расход угля упал в несколько раз.

Второе решающее новшество — преобразование возвратного движения во вращение. С ним машина перестала быть насосом и смогла крутить любой станок.

Регулятор Уатта, сам сбрасывающий обороты при разгоне, стал первым массовым устройством с обратной связью — понятием, которое через полтора века назовут основой управления.'),
  (173, 1, 't_puddling', 'Пудлингование', 1, 9, 1, NULL, 'Передел чугуна в ковкое железо на каменном угле в отражательной печи.', 'Кричный передел требовал древесного угля: сера каменного портила металл. Отражательная печь разделила топливо и металл — пламя гуляет над ванной, не касаясь её.

Пудлинговщик перемешивал расплав ломом, пока выгорающий углерод не превращал массу в тестообразные комья железа, которые затем прокатывали. Работа была нечеловечески тяжёлой и горячей.

Вместе с прокатным станом это дало дешёвое железо в брусках, полосах и рельсах — материал, из которого построена вся ранняя индустриальная эпоха.'),
  (174, 1, 't_iron_frames', 'Чугунные каркасы', 10, 9, 1, NULL, 'Чугунные колонны, балки и арки: несгораемая фабрика и большой пролёт.', 'Первый чугунный мост в Колбрукдейле был отлит с запасом в разы: никто не умел считать такую конструкцию, и её строили по опыту деревянного мостостроения.

На фабрике чугунный каркас решал прежде всего задачу пожара: деревянные перекрытия, пропитанные маслом и хлопковой пылью, горели постоянно, унося и здание, и машины.

Чугун прекрасно держит сжатие и плохо — растяжение, и несколько тяжёлых обрушений мостов заставили разобраться в этом различии. Из разбора аварий и выросла наука о сопротивлении материалов.'),
  (175, 1, 't_spinning_machines', 'Прядильные и ткацкие машины', 5, 9, 1, NULL, 'Прялка «Дженни», ватермашина, мюль и механический ткацкий станок.', 'Прядение было узким местом: механический ткацкий челнок обогнал прялку, и нити перестало хватать. Ответом стали машины, ведущие сразу десятки веретён.

Мюль-машина дала нить достаточно тонкую и прочную, чтобы полностью вытеснить ручное прядение, а затем механизировали и ткачество.

Именно здесь родилась фабрика в современном смысле: машины требовали общего привода, значит, работников надо собрать под одну крышу и подчинить их день ходу вала.'),
  (176, 1, 't_factory', 'Фабричное производство', 14, 9, 1, NULL, 'Машины под одной крышей на общем приводе и работа по гудку.', 'Фабрика — не просто большая мастерская: её распорядок задаёт машина. Трансмиссионный вал крутится непрерывно, и работник обязан поспевать за ним, а не за собой.

Отсюда новшества, ставшие приметой эпохи: смена, гудок, штраф за опоздание, надзиратель. Труд впервые измеряется временем присутствия, а не сделанной вещью.

Производительность выросла невиданно, но вместе с ней — детский труд, двенадцатичасовой день и заводской посёлок. Социальный вопрос XIX века вырастает прямо отсюда.'),
  (177, 1, 't_railway', 'Железная дорога', 13, 9, 1, NULL, 'Паровоз на рельсовом пути: массовая перевозка по расписанию.', 'Рельс появился раньше паровоза: чугунные пути на конной тяге давно возили уголь от шахты. Паровая тяга превратила их в сеть.

Линия Ливерпуль — Манчестер 1830 года показала, что дорога выгодна и для пассажиров, и началось строительство по всей Европе и Америке.

Железная дорога перекроила расстояние и время: она потребовала единого времени вместо местного солнечного, породила расписание, телеграф вдоль путей и акционерные компании невиданного прежде размера.'),
  (178, 1, 't_steamship', 'Пароходство', 12, 9, 1, NULL, 'Судно на паровой тяге: рейс независимо от ветра.', 'Первые пароходы были речными: колёсный движитель хорош на спокойной воде, а частые пристани решают вопрос топлива.

Океан потребовал винта, железного корпуса и экономичной машины — только тогда судно смогло взять груз, а не одни лишь запасы угля.

Регулярное сообщение по расписанию изменило и торговлю, и переселение: срок перехода через Атлантику упал с месяцев до дней, а сроки поставки стали предсказуемыми, что сделало возможной современную торговлю.'),
  (179, 1, 't_electromagnetism', 'Электромагнетизм', 18, 9, 1, NULL, 'Ток рождает магнетизм, движение магнита рождает ток.', 'Эрстед в 1820 году заметил, что стрелка компаса поворачивается у провода с током, связав два явления, которые считались разными.

Фарадей нашёл обратное: движущийся магнит наводит ток в катушке. Отсюда и генератор, и электродвигатель — вся будущая электротехника.

Фарадей же ввёл понятие поля, а Максвелл записал его уравнениями и предсказал электромагнитные волны — предсказание, из которого позже вырастет радио.'),
  (180, 1, 't_telegraph', 'Телеграф', 4, 9, 1, NULL, 'Электрическая передача знаков по проводу на любое расстояние.', 'Телеграф отделил сообщение от гонца: сигнал идёт по проводу почти мгновенно, и расстояние перестаёт значить что-либо для передачи новости.

Код Морзе свёл алфавит к точкам и тире, что позволило работать на одной линии с простейшим ключом и приёмником.

Линии пошли вдоль железных дорог — они и решали задачу безопасности движения. Трансатлантический кабель связал континенты, и биржа, дипломатия и газета впервые стали работать в общем времени.'),
  (181, 1, 't_dalton', 'Атомная теория Дальтона', 8, 9, 1, NULL, 'Вещество из атомов с определённым весом: химия становится счётной.', 'Дальтон объяснил постоянство состава соединений тем, что вещества состоят из неделимых частиц с определённым весом, соединяющихся простыми целыми отношениями.

Из этого следовала возможность приписать элементу число — атомный вес — и предсказывать пропорции реакции расчётом, а не пробой.

Химия перешла из области рецептов в область количества, и все дальнейшие открытия — от периодического закона до структурной формулы — опираются на эту мысль.'),
  (182, 1, 't_thermodynamics', 'Термодинамика', 18, 9, 1, NULL, 'Пределы превращения тепла в работу: КПД, энтропия, сохранение энергии.', 'Карно, размышляя о паровой машине, задал вопрос иначе всех: какой предел полезной работы поставлен самой природой? Ответ — предел зависит от разности температур и не зависит от устройства машины.

Затем был сформулирован закон сохранения энергии, объединивший тепло, работу, электричество и химию в единую величину.

Второе начало ввело необратимость: часть энергии неизбежно рассеивается. Это первый физический закон, различающий прошлое и будущее.'),
  (183, 1, 't_industrial_chem', 'Промышленная химия', 6, 9, 1, NULL, 'Сода, серная кислота, хлорная отбелка — химия тоннами.', 'Процесс Леблана дал соду из поваренной соли, а свинцовые камеры — дешёвую серную кислоту. Эти два вещества нужны почти всем: мылу, стеклу, тканям, бумаге, удобрениям.

Хлорная отбелка сократила отбеливание тканей с месяцев на лугу до часов в чане и сняла ограничение, сдерживавшее текстильную промышленность.

Тогда же появилось и промышленное загрязнение: выбросы содовых заводов губили растительность вокруг, и британский закон о щелочном производстве стал одним из первых природоохранных актов в истории.'),
  (184, 1, 't_gas_light', 'Газовое освещение', 2, 9, 1, NULL, 'Светильный газ из угля по трубам: освещённый вечерний город.', 'Сухая перегонка угля даёт горючий газ, который можно подать по трубам в фонари, лавки и цеха. Первые сети появились в Лондоне в 1810-х годах.

Свет продлил рабочий день на фабрике и вечернюю жизнь города: театры, лавки и читальни получили несколько дополнительных часов.

Газовое хозяйство стало первой городской сетью: труба, счётчик, тариф, авария. Все позднейшие сети — водопровод, электричество, телефон — строились по этому образцу.'),
  (185, 1, 't_needle_rifle', 'Игольчатая винтовка', 9, 9, 1, NULL, 'Заряжание с казны и унитарный патрон: огонь лёжа и втрое чаще.', 'Игольчатое ружьё Дрейзе заряжалось с казённой части бумажным патроном, в котором уже были и пуля, и порох, и капсюль. Игла прокалывала патрон и била по капсюлю.

Скорострельность выросла в несколько раз, и главное — стрелять и перезаряжать стало можно лёжа, тогда как дульнозарядное ружьё требовало встать в полный рост.

Австро-прусская война 1866 года показала это со всей ясностью и заставила все армии спешно перейти на казнозарядное оружие.'),
  (186, 1, 't_howitzer', 'Гаубица и шрапнель', 16, 9, 1, NULL, 'Навесной огонь и разрывной снаряд с готовыми поражающими элементами.', 'Гаубица бьёт по крутой траектории и достаёт противника за укрытием, куда настильное ядро не попадёт.

Шрапнель — снаряд, начинённый пулями и вышибным зарядом с дистанционной трубкой: он раскрывается над строем и накрывает площадь. Это первый снаряд, рассчитанный на поражение живой силы, а не укреплений.

Артиллерия перестала быть только средством пролома стен и стала главным средством поражения в полевом бою — роль, которую она сохранит до сего дня.'),
  (187, 1, 't_farm_machines', 'Механизация сельского хозяйства', 11, 9, 1, NULL, 'Молотилка, жатка и стальной плуг: поле без толпы работников.', 'Молотьба цепом занимала всю зиму; молотилка сделала её делом дней и первой вызвала сопротивление батраков, оставшихся без зимнего заработка.

Стальной отвальный плуг не залипал на жирных почвах прерий и открыл под пашню земли, которые деревянный плуг не брал.

Механизация освободила рабочие руки — и вытолкнула их в город, на фабрику. Рост промышленности и обезлюдение деревни — две стороны одного процесса.'),
  (188, 1, 't_stethoscope', 'Стетоскоп и обследование', 7, 9, 1, NULL, 'Выслушивание и выстукивание: диагноз по физическим признакам.', 'Лаэннек свернул трубку из бумаги, чтобы выслушать сердце пациентки, и получил звук яснее, чем ухом. Из этой случайности вырос стетоскоп и целое направление диагностики.

Вместе с выстукиванием грудной клетки это позволило судить о состоянии внутренних органов у живого человека — то, что раньше открывалось только на вскрытии.

Медицина сделала решающий шаг: диагноз перестал строиться на одних жалобах и стал опираться на признаки, которые врач наблюдает сам и может проверить.'),
  (189, 1, 't_industrial_capital', 'Промышленный капитал', 17, 9, 1, NULL, 'Вложения в машины и заводы; банк, кредитующий производство.', 'Фабрика требует вложить деньги задолго до первой выручки, поэтому промышленности понадобился долгосрочный кредит, а не купеческая ссуда под рейс.

Появились банки, финансирующие строительство и покупку оборудования, и рынок облигаций, на котором собирали средства железнодорожные компании — крупнейшие предприятия эпохи.

Вместе с этим приходят и биржевые кризисы нового типа: крах железнодорожных акций бьёт по банкам, а через них — по всей хозяйственной жизни, что раньше было невозможно.'),
  (190, 1, 't_sanitation', 'Санитария', 19, 9, 1, NULL, 'Канализация, водопровод и городская санитарная служба.', 'Промышленный город XIX века убивал: скученность, выгребные ямы и загрязнённые колодцы держали смертность на уровне, при котором город не воспроизводил себя без притока из деревни.

Джон Сноу связал вспышку холеры в Лондоне с одной водоразборной колонкой, нанеся случаи на карту, — это классический пример того, как рассуждение о данных спасает жизни до всякого знания о возбудителе.

Ответом стали канализация, фильтрованный водопровод и санитарная инспекция. Продолжительность жизни в городах выросла благодаря трубам сильнее, чем благодаря лекарствам.'),
  (191, 1, 't_bessemer', 'Бессемеровская сталь', 1, 10, 1, NULL, 'Продувка чугуна воздухом: сталь тоннами и дёшево.', 'Бессемер продул расплавленный чугун воздухом снизу: примеси выгорают сами, и выделяющегося при этом тепла хватает, чтобы металл не застыл. Топлива не требуется вовсе.

Конвертер давал за двадцать минут столько стали, сколько пудлинговая печь — за сутки, и цена упала в разы. Мартеновский процесс добавил возможность перерабатывать лом и точно вести состав.

Сталь из дорогого материала для клинков превратилась в конструкционный: рельсы, мосты, корпуса судов, каркасы зданий, станки. Весь облик второй половины XIX века определён этим переходом.'),
  (192, 1, 't_spectroscopy', 'Спектроскопия', 8, 10, 1, NULL, 'Разложение света в спектр: состав вещества по линиям излучения.', 'Кирхгоф и Бунзен показали, что каждый элемент даёт свой набор спектральных линий, по которому его можно опознать в любой смеси и в любом количестве.

Тёмные линии в спектре Солнца оказались теми же линиями поглощения, и человечество внезапно получило способ узнать состав звёзд — предмет, который философы совсем недавно объявляли принципиально непознаваемым.

Спектроскопия открыла новые элементы, а необъяснимая правильность линий стала той загадкой, из которой через полвека вырастет квантовая теория.'),
  (193, 1, 't_microbiology', 'Микробиология', 7, 10, 1, NULL, 'Микроб как причина болезни: посев, стерилизация, вакцина по заказу.', 'Пастер доказал, что брожение и гниение вызываются живыми организмами, а не возникают сами, и что нагревание убивает их — отсюда пастеризация.

Кох дал строгий метод: выделить возбудителя, вырастить в чистой культуре, вызвать им болезнь и снова выделить. Эти правила и сегодня остаются образцом доказательства в инфекционной медицине.

Впервые болезнь получила конкретную причину, которую можно увидеть, вырастить и убить. Медицина перешла от лечения признаков к борьбе с возбудителем.'),
  (194, 1, 't_em_waves', 'Электромагнитные волны', 18, 10, 1, NULL, 'Предсказание Максвелла и опыт Герца: свет как электромагнитная волна.', 'Максвелл свёл электричество и магнетизм в четыре уравнения, из которых следовало существование волн, бегущих со скоростью света. Значит, и сам свет — такая волна.

Герц через двадцать лет получил эти волны в лаборатории, показав отражение и преломление, и тем подтвердил теорию. Практического применения он не видел.

Именно этот случай стали приводить как образец: чистая теория предсказала явление, о котором никто не подозревал, а через десятилетие на нём выросла целая отрасль связи.'),
  (195, 1, 't_ice_engine', 'Двигатель внутреннего сгорания', 2, 10, 1, NULL, 'Четырёхтактный двигатель: мощность в малом объёме без котла.', 'Паровая машина требует котла, воды и времени на разведение пара. Двигатель внутреннего сгорания сжигает топливо прямо в цилиндре и готов к работе сразу.

Четырёхтактный цикл Отто и дизель с воспламенением от сжатия задали две схемы, которые применяются и сегодня.

Решающим оказалось отношение мощности к весу: только такой двигатель можно поставить на повозку и тем более на летательный аппарат. Автомобиль и самолёт становятся возможны именно здесь.'),
  (196, 1, 't_photography', 'Фотография', 4, 10, 1, NULL, 'Светопись: изображение, полученное без руки художника.', 'Соединив камеру-обскуру с солями серебра, чувствительными к свету, получили изображение, которое рисует сам свет. Выдержка в первых опытах измерялась часами, затем секундами.

Фотография изменила представление о достоверности: снимок стал доказательством в суде, документом в науке и свидетельством с войны.

Она же изменила искусство: точное воспроизведение видимого перестало быть задачей живописи, и та ушла в сторону цвета, впечатления и формы.'),
  (197, 1, 't_corporations', 'Корпорации', 17, 10, 1, NULL, 'Акционерное общество с ограниченной ответственностью и наёмным управлением.', 'Закон об ограниченной ответственности отделил судьбу вкладчика от судьбы предприятия: акционер рискует вложенным, но не всем имуществом. Это резко расширило круг тех, кто готов вкладываться.

Размер предприятий вырос настолько, что собственник перестал ими управлять: появился наёмный директор и с ним постоянное расхождение интересов владельца и управляющего.

Корпорация стала самостоятельным юридическим лицом, переживающим своих основателей, — и вместе с тем предметом нового политического беспокойства о власти монополий.'),
  (198, 1, 't_fertilizers', 'Промышленные удобрения', 11, 10, 1, NULL, 'Суперфосфат, гуано и калийные соли: питание поля из мешка.', 'Либих показал, что растение берёт из почвы определённые вещества и что урожай ограничен тем из них, которого меньше всего. Отсюда прямой вывод: недостающее можно внести.

Обработка костей и фосфоритов кислотой дала суперфосфат, а залежи гуано на тихоокеанских островах стали предметом настоящей международной гонки.

Земледелие впервые перестало зависеть только от навоза своего скота, и урожайность оторвалась от вековых пределов. Азот, однако, оставался узким местом до синтеза аммиака.'),
  (199, 1, 't_steel_frame', 'Стальной каркас', 10, 10, 1, NULL, 'Здание на стальном скелете: небоскрёб и большие пролёты.', 'Пока стена несёт вес, высота ограничена её толщиной внизу. Стальной каркас переносит нагрузку на скелет, а стена становится лёгкой оболочкой.

Чикаго после пожара 1871 года стал полигоном: там сложилась и конструкция, и сам тип высотного делового здания.

Небоскрёб невозможен без второго изобретения — безопасного лифта с ловителем: без него верхние этажи оставались бы самыми дешёвыми, как в доходном доме.'),
  (200, 1, 't_rifled_artillery', 'Нарезная артиллерия', 16, 10, 1, NULL, 'Нарезной ствол и продолговатый снаряд: дальность и точность вдвое.', 'Нарезы закручивают продолговатый снаряд, и он летит устойчиво носом вперёд. Дальность и кучность вырастают в разы по сравнению с шаровым ядром.

Заряжание с казны потребовало надёжного затвора, способного выдержать давление, — именно здесь пригодилась дешёвая сталь.

Крепости, рассчитанные на гладкоствольную артиллерию, разом устарели: новые орудия разбивали их с дистанции, недосягаемой для ответного огня.'),
  (201, 1, 't_repeating_rifle', 'Магазинная винтовка', 9, 10, 1, NULL, 'Металлический патрон и магазин: несколько выстрелов без перезарядки.', 'Металлическая гильза решила сразу две задачи: обтюрацию — она сама уплотняет казённик при выстреле — и защиту заряда от сырости.

Магазин на несколько патронов с продольно-скользящим затвором дал десяток прицельных выстрелов в минуту вместо двух-трёх.

Плотность огня стрелковой цепи выросла настолько, что атака сомкнутым строем стала самоубийственной. Пехота залегла и начала окапываться — облик войны изменился необратимо.'),
  (202, 1, 't_ironclad', 'Броненосцы', 12, 10, 1, NULL, 'Железный корпус, броневой пояс и башенная артиллерия.', 'Первый же бой броненосцев при Хэмптон-Роудс в 1862 году окончился ничьей: снаряды не пробивали броню. Деревянный флот в тот день устарел целиком.

Началась гонка брони и снаряда, продолжавшаяся полвека: усиление одного немедленно вызывало усиление другого.

Броненосец стал самым дорогим изделием эпохи и мерилом державной мощи; постройка флота превратилась в важнейшую статью бюджета и в постоянный повод для международного соперничества.'),
  (203, 1, 't_dynamo', 'Электрические сети и динамо', 2, 10, 1, NULL, 'Генератор, трансформатор и передача энергии на расстояние.', 'Динамо-машина превратила механическую энергию в электрическую в промышленных количествах, а трансформатор позволил передавать её на расстояние высоким напряжением с малыми потерями.

Спор постоянного и переменного тока решился в пользу переменного именно из-за передачи: станцию стало можно строить у водопада или угольной шахты, а не в центре города.

Электричество — первая энергия, которую можно подать в любую точку по проводу. Завод перестал строиться вокруг вала трансмиссии: у каждого станка появился свой мотор.'),
  (204, 1, 't_mendel', 'Законы наследственности', 21, 10, 1, NULL, 'Дискретные признаки, доминирование и расщепление в потомстве.', 'Мендель на горохе показал, что признаки передаются не смешиваясь, а отдельными единицами, и что их сочетания подчиняются простым числовым отношениям.

Работу 1866 года не заметили: она была слишком математической для тогдашней биологии. Её переоткрыли независимо трое исследователей на рубеже веков.

Дискретность наследственности разрешила главное затруднение теории эволюции: при «смешивании» признаков любое новшество растворялось бы в потомстве и отбору не за что было бы зацепиться.'),
  (205, 1, 't_antisepsis', 'Асептика и антисептика', 7, 10, 1, NULL, 'Обеззараживание рук, инструмента и раны: операция перестаёт убивать.', 'До Листера послеоперационная смертность доходила до половины: чистая на вид рана нагнаивалась, и это считали неизбежным свойством заживления.

Прочитав Пастера, Листер применил карболовую кислоту к ране, инструменту и рукам. Смертность упала в несколько раз.

Земмельвейс за двадцать лет до того добился того же в родильном отделении простым мытьём рук, но был осмеян и умер непризнанным — классический и печальный пример того, как медицина сопротивляется неудобной правде.'),
  (206, 1, 't_periodic_law', 'Периодический закон', 8, 10, 1, NULL, 'Свойства элементов повторяются с ростом атомного веса.', 'Менделеев расположил элементы по возрастанию атомного веса и увидел, что свойства повторяются через правильные промежутки. Ради стройности он оставил в таблице пустые клетки.

Он предсказал свойства ещё не открытых элементов — вплоть до плотности и температуры плавления, — и, когда галлий и германий были найдены и совпали с предсказанием, закон приняли безоговорочно.

Причину периодичности объяснит только строение атома через полвека, но сама таблица уже давала химии систему вместо перечня.'),
  (207, 1, 't_automobile', 'Автомобиль', 13, 10, 1, NULL, 'Самодвижущийся экипаж с бензиновым двигателем.', 'Автомобиль соединил лёгкий двигатель, пневматическую шину, дифференциал и рулевое управление. Каждая часть решала свою задачу, но работать они начали только вместе.

Первые машины были дорогой забавой и вызывали враждебность: в Британии несколько десятилетий действовал закон, требовавший, чтобы перед самоходным экипажем шёл человек с красным флагом.

Личная подвижность, не привязанная к расписанию и рельсам, изменит расселение, торговлю и облик городов сильнее, чем железная дорога, — но это станет ясно уже в следующем веке.'),
  (208, 1, 't_organic_chem', 'Органическая химия', 6, 10, 1, NULL, 'Строение молекулы и синтез: вещества, которых нет в природе.', 'Синтез мочевины разрушил представление о том, что вещества живого требуют особой жизненной силы. Химия получила право строить что угодно из чего угодно.

Теория строения и открытие кольца бензола дали язык, на котором молекулу можно нарисовать и предсказать её поведение.

Первым большим применением стали анилиновые красители из каменноугольной смолы: они разорили производителей природных красок и создали немецкую химическую промышленность — первую отрасль, целиком выросшую из лаборатории.'),
  (209, 1, 't_explosives', 'Взрывчатые вещества', 6, 10, 1, NULL, 'Динамит и бездымный порох: горное дело и новая артиллерия.', 'Нитроглицерин чудовищно чувствителен к удару; Нобель связал его пористым материалом и получил динамит — взрывчатку, которую можно возить и закладывать без смертельного риска.

Горное дело, тоннели и каналы получили средство, ускорившее работы в разы: без динамита не было бы ни альпийских тоннелей, ни Панамского канала.

Бездымный порох изменил бой: пороховой дым перестал закрывать поле и выдавать позицию стрелка, а рост мощности заряда позволил перейти к малому калибру с высокой скоростью пули.'),
  (210, 1, 't_quickfire_artillery', 'Скорострельная артиллерия', 16, 10, 1, NULL, 'Откатный лафет и унитарный выстрел: орудие не сбивает наводку.', 'Прежде отдача откатывала орудие, и наводку приходилось восстанавливать после каждого выстрела. Гидропневматический откатник поглощает отдачу, а ствол сам возвращается в прежнее положение.

Французская 75-миллиметровая пушка давала до двадцати прицельных выстрелов в минуту вместо двух и на десятилетия стала образцом.

Вместе с шрапнелью и бездымным порохом это сделало открытое поле непроходимым для пехоты и прямо привело к позиционному тупику мировой войны.'),
  (211, 1, 't_machine_gun', 'Пулемёт', 9, 10, 1, NULL, 'Автоматическое оружие на энергии отдачи: огонь одного за роту.', 'Максим использовал энергию отдачи для перезаряжания, и оружие стало стрелять само, пока нажат спуск. Водяное охлаждение позволило вести огонь длинными очередями.

Один расчёт давал плотность огня, для которой прежде нужна была рота стрелков. В колониальных войнах это дало подавляющее превосходство и было воспринято как техническое чудо.

В Европе выводов не сделали, и в 1914 году пехота пошла в атаку сомкнутым строем. Пулемёт в паре с колючей проволокой и создал окопную войну.'),
  (212, 1, 't_torpedo', 'Торпедное оружие', 12, 10, 1, NULL, 'Самодвижущаяся мина: малый корабль опасен для броненосца.', 'Торпеда Уайтхеда шла на сжатом воздухе и держала глубину благодаря гидростатическому механизму, который долго оставался секретом.

Она била ниже броневого пояса, в самое уязвимое место корпуса, и делала дешёвый миноносец угрозой для самого дорогого корабля флота.

Ответом стали противоминная артиллерия, сети и, в конце концов, эсминец. Но главное следствие пришло позже: именно торпеда сделала подводную лодку грозным оружием.'),
  (213, 1, 't_telephone', 'Телефон', 4, 10, 1, NULL, 'Передача голоса по проводу и коммутируемая сеть.', 'Телеграф передаёт знаки и требует обученного оператора; телефон передаёт голос, и пользоваться им может любой. Это и определило его судьбу.

Главным изобретением оказалась не трубка, а коммутатор: чтобы соединить каждого с каждым, нужна станция, а не провод между парами абонентов.

Телефон вошёл в контору и дом, изменив темп деловой жизни: решения стали приниматься в разговоре, а не в переписке, и это ускорило хозяйственную жизнь сильнее, чем видно по цифрам.'),
  (214, 1, 't_airship', 'Управляемые дирижабли', 22, 10, 1, NULL, 'Жёсткий корпус, двигатель и руль: полёт по заданному курсу.', 'Аэростат летит по ветру; дирижабль с двигателем и рулём идёт куда нужно. Жёсткий каркас позволил довести размеры до сотен метров и нести серьёзную нагрузку.

Дирижабли первыми освоили дальние воздушные рейсы, включая трансатлантические, и применялись для разведки и бомбардировки.

Их погубило сочетание водорода как несущего газа с уязвимостью к погоде: катастрофы, самая известная из которых — гибель «Гинденбурга», закрыли эпоху, а самолёт к тому времени уже перехватил задачу.'),
  (215, 1, 't_refrigeration', 'Холодильная техника', 14, 10, 1, NULL, 'Машинный холод: хранение и перевозка скоропортящихся продуктов.', 'Компрессионная машина отбирает тепло испарением рабочего вещества и даёт холод в любом количестве и в любое время года, не завися от заготовки льда.

Рефрижераторное судно связало Австралию, Аргентину и Новую Зеландию с европейским столом: мясо стало перевозиться через океан.

Следствия оказались широкими: пивоварение перестало зависеть от сезона, города получили надёжное снабжение молоком и мясом, а питание горожан заметно улучшилось.'),
  (216, 1, 't_water_treatment', 'Очистные сооружения', 19, 10, 1, NULL, 'Фильтрация и обеззараживание воды, очистка сточных вод.', 'Медленный песчаный фильтр задерживает большую часть микроорганизмов, а хлорирование добивает остальное. Города, применившие оба приёма, практически покончили с брюшным тифом и холерой.

Очистка сточных вод решала обратную задачу: не отравить реку ниже по течению, куда город сбрасывал всё, что не хотел видеть у себя.

Историки здравоохранения сходятся в том, что вклад чистой воды в рост продолжительности жизни в XIX–XX веках превысил вклад всех лекарств вместе взятых.'),
  (217, 1, 't_relativity', 'Теория относительности', 8, 11, 1, NULL, 'Единство пространства и времени; тяготение как искривление.', 'Специальная теория 1905 года вывела из постоянства скорости света замедление времени и сокращение длины, а также соотношение массы и энергии.

Общая теория объяснила тяготение искривлением пространства-времени и предсказала отклонение света у Солнца. Наблюдение затмения 1919 года подтвердило предсказание и сделало Эйнштейна всемирно известным.

Практические следствия долго казались отдалёнными, но сегодня без релятивистских поправок спутниковая навигация ошибалась бы на километры в сутки.'),
  (218, 1, 't_quantum', 'Квантовая физика', 18, 11, 1, NULL, 'Энергия порциями, вероятность и принцип неопределённости.', 'Планк ввёл кванты как вынужденное допущение для объяснения излучения нагретого тела; Эйнштейн применил их к фотоэффекту, Бор — к строению атома.

Затем пришла полноценная теория, в которой состояние описывается волновой функцией, а предсказать можно лишь вероятность исхода. Спор о том, что это значит, продолжается по сей день.

Прикладное значение огромно: без квантовой механики нет ни полупроводника, ни лазера, ни понимания химической связи. Большая часть современной техники стоит на ней.'),
  (219, 1, 't_light_alloys', 'Лёгкие сплавы', 1, 11, 1, NULL, 'Дюралюминий и промышленный алюминий: прочность при малом весе.', 'Алюминий был дороже золота, пока электролиз расплава не сделал его дешёвым. Производство сразу привязалось к дешёвой электроэнергии — прежде всего к гидростанциям.

Дюралюминий — сплав с медью и магнием, упрочняющийся со временем сам, — дал прочность стали при трети веса.

Всё воздухоплавание держится на этом: цельнометаллический самолёт возможен только с лёгким сплавом, и авиация росла ровно настолько, насколько позволяли материалы.'),
  (220, 1, 't_reinforced_concrete', 'Железобетон', 10, 11, 1, NULL, 'Бетон со стальной арматурой: дешёвая прочная конструкция любой формы.', 'Бетон отлично держит сжатие и плохо — растяжение; сталь наоборот. Соединив их, получили материал, работающий на любую нагрузку, — и, что решило дело, у них совпадает температурное расширение.

Опалубка позволяет отлить любую форму, а сырьё дёшево и есть почти везде, поэтому железобетон вытеснил камень и кирпич из крупного строительства.

На нём построены плотины, мосты, бомбоубежища и жилые массивы XX века: он и определил облик современного города больше любого архитектурного стиля.'),
  (221, 1, 't_oil_refining', 'Нефтепереработка', 2, 11, 1, NULL, 'Перегонка и крекинг: бензин, керосин, мазут и сырьё для химии.', 'Сначала из нефти нужен был только керосин для ламп, а бензин считали опасным отходом и нередко сливали.

Автомобиль перевернул спрос, и понадобился крекинг — расщепление тяжёлых фракций нагревом и катализатором, дающее вдвое больше бензина из той же нефти.

Нефть стала стратегическим товаром: обеспеченность топливом прямо определяла ход мировых войн, а нефтяная политика на век вперёд задала расстановку сил на Ближнем Востоке.'),
  (222, 1, 't_aviation', 'Авиация', 22, 11, 1, NULL, 'Аппарат тяжелее воздуха: крыло, двигатель и управление по трём осям.', 'Братья Райт выиграли не мощностью, а управлением: они первыми решили задачу поперечного равновесия перекашиванием крыла и связали его с рулём поворота.

Дальше развитие шло стремительно: за десять лет от первого полёта самолёт стал боевым средством, а за тридцать — регулярным транспортом.

Авиация свела расстояние к часам и обесценила географическую защищённость: море и горы перестали быть преградой, и это изменило и войну, и представление о безопасности страны.'),
  (223, 1, 't_carrier', 'Авианосцы', 12, 11, 1, NULL, 'Плавучий аэродром: удар авиацией за сотни миль от корабля.', 'Авианосец переносит бой из зоны видимости в зону досягаемости авиации: удар наносится за сотни миль, задолго до того, как противники увидят друг друга.

Потопление линкоров у Таранто и Пёрл-Харбора, а затем бой в Коралловом море, где флоты не увидели друг друга вовсе, окончательно решили спор о главном корабле флота.

Линкор с его броней и калибром сошёл со сцены за считанные годы: авианосец бьёт дальше, а броня против авиабомбы бесполезна.'),
  (224, 1, 't_auto_weapons', 'Автоматическое оружие', 9, 11, 1, NULL, 'Самозарядная винтовка, пистолет-пулемёт и ручной пулемёт.', 'Опыт мировой войны показал, что бой идёт на коротких дистанциях, где важнее плотность огня, чем дальность прицельного выстрела.

Отсюда пистолет-пулемёт под пистолетный патрон, ручной пулемёт как оружие отделения и, наконец, автомат под промежуточный патрон, соединивший дальность винтовки с автоматическим огнём.

Тактика перестроилась вокруг огневой группы: отделение стало действовать вокруг своего пулемёта, а не как цепочка одиночных стрелков.'),
  (225, 1, 't_tanks', 'Бронетехника', 15, 11, 1, NULL, 'Гусеничная бронированная машина: прорыв обороны с пулемётами.', 'Танк родился как ответ на окопный тупик: нужна была машина, способная пройти проволоку и траншею под пулемётным огнём. Гусеница дала проходимость, броня — защиту.

Первые танки были тихоходны и ненадёжны, и до конца войны их применяли разрозненно.

Выводы сделали в межвоенные годы: собранные в самостоятельные соединения и поддержанные авиацией и радиосвязью, танки дали ту манёвренную войну, которая определила ход следующей мировой.'),
  (226, 1, 't_siege_heavy', 'Тяжёлая осадная артиллерия', 16, 11, 1, NULL, 'Сверхтяжёлые орудия и мортиры против бетонных укреплений.', 'Бетонные форты потребовали снаряда, пробивающего перекрытие сверху. Ответом стали мортиры калибра свыше четырёхсот миллиметров, разбиравшиеся для перевозки по железной дороге.

Бельгийские форты в 1914 году пали за считанные дни, показав, что никакая постоянная крепость не устоит перед сосредоточенной осадной артиллерией.

Это положило конец крепости как основе обороны: её сменила протяжённая полевая позиция, которую нельзя обойти и невыгодно разбивать по частям.'),
  (227, 1, 't_assembly_line', 'Конвейер и массовое производство', 14, 11, 1, NULL, 'Движущаяся сборка и взаимозаменяемые части: цена падает в разы.', 'Форд соединил взаимозаменяемость деталей, разбиение сборки на простейшие операции и движущуюся ленту, задающую темп. Сборка автомобиля сократилась с двенадцати часов до полутора.

Цена упала настолько, что автомобиль стал доступен рабочему, — и Форд сознательно поднял зарплату, рассуждая, что его работники должны быть его покупателями.

Обратной стороной стал предельно однообразный труд, текучесть кадров и подчинение человека темпу ленты — то, что позже назовут отчуждением и сделают предметом долгого спора.'),
  (228, 1, 't_mass_consumption', 'Массовое потребление', 17, 11, 1, NULL, 'Реклама, рассрочка и торговая сеть: сбыт как отдельная задача.', 'Массовое производство создало новую трудность: произведённое надо продать. Отсюда реклама, ставшая отраслью, и продажа в рассрочку, позволившая покупать до накопления.

Универмаг, сеть, каталог и марка приучили покупателя к постоянному обновлению вещей, а не к их долгому сроку службы.

Экономика получила новую опору — потребительский спрос, — и вместе с ней новую уязвимость: спад расходов домохозяйств стал самостоятельной причиной кризиса, что ярко показала Великая депрессия.'),
  (229, 1, 't_radio', 'Радиосвязь', 4, 11, 1, NULL, 'Беспроводная передача сигнала и голоса; вещание на массовую аудиторию.', 'Маркони превратил лабораторные волны Герца в средство связи, добившись передачи через Атлантику. Первым и решающим применением стала морская связь: радио спасало суда, лишённые всякой связи с берегом.

Ламповый усилитель позволил передавать не только точки и тире, но и голос, и радио стало вещательным — из средства связи между двумя превратилось в обращение к миллионам.

Политические последствия оказались громадными: голос вождя, звучащий одновременно в каждом доме, стал новым инструментом власти, что двадцатые и тридцатые годы показали в полной мере.'),
  (230, 1, 't_radar', 'Радиолокация', 8, 11, 1, NULL, 'Обнаружение объектов по отражённой радиоволне: зрение сквозь ночь и туман.', 'Радар измеряет время возврата отражённого импульса и даёт направление и дальность до цели независимо от погоды и темноты.

Британская сеть станций в 1940 году позволила поднимать истребители точно навстречу налёту, а не держать их в воздухе постоянно, и это уравняло силы в воздушной битве.

Резонаторный магнетрон дал компактный источник сантиметровых волн, что сделало радар пригодным для самолёта и корабля; после войны из той же техники выросли микроволновая печь и радиоастрономия.'),
  (231, 1, 't_antibiotics', 'Антибиотики', 7, 11, 1, NULL, 'Пенициллин и сульфаниламиды: излечение бактериальных инфекций.', 'Флеминг заметил, что плесень подавляет рост бактерий, но выделить вещество не смог; это сделали Флори и Чейн, а промышленное производство развернули под давлением войны.

Действие было ошеломляющим: болезни, которые убивали наверняка — сепсис, воспаление лёгких, раневая инфекция, — стали излечимы за дни.

Флеминг же в нобелевской речи предупредил о том, что бактерии приобретут устойчивость при небрежном применении. Предупреждение сбылось, и сегодня это одна из главных угроз медицине.'),
  (232, 1, 't_plastics', 'Пластмассы', 6, 11, 1, NULL, 'Синтетические полимеры: материал, который делают под задачу.', 'Бакелит стал первым полностью синтетическим полимером, а понимание, что это длинные цепочки повторяющихся звеньев, превратило случайные находки в управляемое конструирование.

Дальше пошли нейлон, полиэтилен и поливинилхлорид — материалы дешёвые, лёгкие, не гниющие и формуемые в любую вещь.

Именно долговечность обернулась бедой: пластик не разлагается десятилетиями, и загрязнение им стало одной из главных экологических проблем следующего столетия.'),
  (233, 1, 't_ammonia', 'Синтез аммиака', 6, 11, 1, NULL, 'Азот из воздуха под давлением: неограниченные азотные удобрения.', 'Азота в воздухе неисчерпаемо, но он химически инертен. Габер под высоким давлением и с катализатором связал его с водородом, а Бош довёл процесс до промышленного масштаба.

Мир снял зависимость от чилийской селитры и получил азотные удобрения в любом количестве. По оценкам, значительная часть азота в теле современного человека прошла через этот процесс.

Двойственность разительна: тот же процесс дал сырьё для взрывчатки, продлив мировую войну, а сам Габер организовал применение боевых газов.'),
  (234, 1, 't_tractors', 'Трактора и комбайны', 11, 11, 1, NULL, 'Механическая тяга и уборка: поле обрабатывает один человек.', 'Трактор заменил упряжку и освободил земли, прежде занятые под корм тягловым лошадям, — в масштабах страны это миллионы гектаров под продовольствие.

Комбайн соединил жатву, обмолот и очистку в одном проходе, сократив уборку с недель до дней и сняв зависимость от сезонного наплыва работников.

Доля занятых в сельском хозяйстве упала за столетие с половины населения до нескольких процентов — самая глубокая перемена в устройстве общества за всю промышленную эпоху.'),
  (235, 1, 't_highways', 'Скоростные автомагистрали', 13, 11, 1, NULL, 'Дороги с разделёнными потоками и развязками без пересечений.', 'Автомагистраль отличается от шоссе принципом: встречные потоки разделены, пересечения только в разных уровнях, въезд и съезд — по полосам разгона.

Это позволило безопасно держать высокую скорость и пропускать поток, немыслимый на обычной дороге.

Сеть магистралей перекроила расселение: пригород стал доступен, грузовик отобрал перевозки у железной дороги, а придорожная торговля и мотель создали целый уклад жизни вдоль трассы.'),
  (236, 1, 't_electromech_computers', 'Электромеханические вычислители', 20, 11, 1, NULL, 'Программируемые машины на реле: расчёт по заданной последовательности.', 'Цузе в Берлине и Эйкен в Гарварде построили машины на реле, выполнявшие последовательность операций, заданную извне лентой или картами.

Тогда же Тьюринг описал абстрактную машину и доказал, что существует универсальное устройство, способное выполнить любой вычислимый алгоритм, — теоретический фундамент всей будущей информатики.

Реле медленны и ненадёжны, и предел был очевиден. Дальнейший шаг требовал переключателя без движущихся частей — и им станет электронная лампа, а затем транзистор.'),
  (237, 1, 't_soil_conservation', 'Охрана почв', 19, 11, 1, NULL, 'Борьба с эрозией: полезащитные полосы, безотвальная обработка, севооборот.', 'Распашка прерий тракторами вывернула степные почвы, веками державшиеся корнями трав. Засуха тридцатых подняла их в воздух: пыльные бури уносили верхний слой тысячами тонн и разоряли целые штаты.

Ответом стали лесополосы, обработка поперёк склона, залужение и государственная служба охраны почв.

Это первый случай, когда стало ясно: техника, повышающая урожай сегодня, способна уничтожить саму основу земледелия завтра. Отсюда тянется весь позднейший разговор об устойчивом хозяйстве.'),
  (238, 1, 't_nuclear_physics', 'Ядерная физика', 8, 12, 1, NULL, 'Строение ядра, деление и цепная реакция.', 'Опыт Резерфорда с рассеянием частиц показал, что почти вся масса атома сосредоточена в крошечном ядре. Открытие нейтрона дало частицу, которой можно бомбардировать ядро, не преодолевая отталкивания.

В 1938 году Ган и Штрассман обнаружили, что ядро урана раскалывается, а Мейтнер и Фриш объяснили это делением и подсчитали выделяющуюся энергию.

Ключевым оказалось то, что при делении вылетают новые нейтроны: реакция способна поддерживать себя сама. С этого мгновения и реактор, и бомба стали вопросом инженерии и времени.'),
  (239, 1, 't_transistor', 'Транзистор', 20, 12, 1, NULL, 'Полупроводниковый переключатель: усиление без лампы, накала и вакуума.', 'Транзистор делает то же, что электронная лампа, но в тысячи раз меньше, без разогрева и с ничтожным потреблением. Работа его целиком объясняется квантовой теорией твёрдого тела.

Следующий шаг оказался решающим: научились изготавливать множество транзисторов сразу на одной пластине кремния вместе с соединениями между ними — это интегральная схема.

С этого момента сложность устройства перестала упираться в число паяных соединений, и вычислительная техника пошла в рост, который продолжается по сей день.'),
  (240, 1, 't_jet_aviation', 'Реактивная авиация', 22, 12, 1, NULL, 'Газотурбинный двигатель: скорость и высота, недоступные винту.', 'Винт теряет эффективность при приближении к скорости звука. Реактивный двигатель отбрасывает поток сам и работает тем лучше, чем выше скорость и разреженнее воздух.

Стреловидное крыло отодвинуло волновой кризис, и сверхзвук стал достижим. Военная авиация перешла на реактивную тягу за считанные годы.

Гражданские последствия оказались не меньше: реактивный лайнер сократил перелёт через океан до часов и сделал дальние путешествия массовыми, что перестроило и туризм, и деловые связи.'),
  (241, 1, 't_composites', 'Композитные материалы', 1, 12, 1, NULL, 'Стекло- и углепластик: прочность стали при доле её веса.', 'Композит соединяет волокно, держащее нагрузку, и связующее, передающее усилие между волокнами. Свойства задаются направлением укладки, поэтому материал проектируется вместе с деталью.

Стеклопластик дал корпуса катеров и кузова, углепластик — конструкции, где важен каждый грамм.

Слабость композита в другом: он плохо переносит удар и почти не поддаётся ремонту и переработке, а скрытое расслоение трудно обнаружить — отсюда строгие правила контроля в авиации.'),
  (242, 1, 't_panel_housing', 'Крупнопанельное строительство', 10, 12, 1, NULL, 'Дом из заводских панелей: массовое жильё в предельно короткий срок.', 'Панель изготавливают на заводе и привозят готовой; на площадке остаётся сборка краном. Дом возводится за недели, а качество бетона выше, чем при заливке на морозе.

Послевоенная нехватка жилья была так остра, что скорость перевесила всё: десятки миллионов людей впервые получили отдельную квартиру с водопроводом и отоплением.

Цена — однообразие застройки, слабая звукоизоляция и ограниченный срок службы. Спор о том, было ли это благом или бедствием для городов, не окончен и сегодня.'),
  (243, 1, 't_pesticides', 'Пестициды и гербициды', 11, 12, 1, NULL, 'Химическая защита посевов: урожай без потерь от вредителя и сорняка.', 'ДДТ и последующие препараты дали земледелию средство, которого у него не было никогда: вредителя стало возможно уничтожить, а не пережидать. Потери урожая упали резко.

Гербициды избирательного действия убивают сорняк, не трогая злак, и сделали прополку ненужной — без них немыслимо современное крупное хозяйство.

Оборотную сторону вскрыла книга Рейчел Карсон: яд накапливается по пищевой цепи и губит птиц и рыбу далеко от поля. С этого спора и начинается современное экологическое движение.'),
  (244, 1, 't_nuclear_energy', 'Ядерная энергия', 2, 12, 1, NULL, 'Реактор на управляемой цепной реакции: электричество из деления ядер.', 'Реактор удерживает цепную реакцию на постоянном уровне: замедлитель повышает вероятность деления, поглощающие стержни отбирают лишние нейтроны.

Энергия деления в миллионы раз плотнее химической: килограмм урана заменяет эшелон угля. Это обещало дешёвое электричество и на десятилетия определило энергетические планы.

Две трудности оказались упрямыми: отходы, опасные тысячи лет, и последствия тяжёлой аварии. Чернобыль и Фукусима переломили общественное отношение к атомной энергетике сильнее любых расчётов.'),
  (245, 1, 't_nuclear_weapon', 'Ядерное оружие', 16, 12, 1, NULL, 'Бомба на делении и термоядерный заряд: разрушение города одним ударом.', 'Манхэттенский проект собрал десятки тысяч людей и мощности целой отрасли ради разделения изотопов и наработки плутония — задача была не физической, а промышленной.

Хиросима и Нагасаки показали действие: разрушение, тепловое поражение и радиоактивное заражение от одного заряда. Термоядерная бомба увеличила мощность ещё в тысячу раз.

Оружие изменило саму политику: прямая война между владеющими им державами стала самоубийственной, и на этом парадоксе — мир, обеспеченный угрозой уничтожения, — простояла вторая половина века.'),
  (246, 1, 't_nuclear_med', 'Ядерная медицина', 7, 12, 1, NULL, 'Изотопы в диагностике и лучевая терапия опухолей.', 'Меченый изотопом препарат собирается в определённом органе, и его излучение показывает не строение, а работу ткани — то, чего рентген не даёт.

Лучевая терапия использует чувствительность делящихся клеток к излучению: опухоль гибнет раньше окружающей ткани, особенно при облучении с разных направлений.

Так родилась визуализация как отдельная область медицины; от неё прямая дорога к томографии, изменившей диагностику полностью.'),
  (247, 1, 't_radiochemistry', 'Радиохимия', 6, 12, 1, NULL, 'Химия радиоактивных элементов: разделение изотопов и меченые атомы.', 'Разделить изотопы химически почти невозможно — они одинаковы по свойствам и различаются лишь массой. Отсюда газовая диффузия и центрифуги, ставшие ключевой и самой охраняемой технологией.

Меченые атомы дали науке инструмент невероятной чувствительности: по радиоактивной метке прослеживают путь вещества в организме, в почве и в реакции.

Радиоуглеродный анализ перевернул археологию, впервые дав абсолютные даты вместо относительной последовательности слоёв.'),
  (248, 1, 't_computer', 'Электронная вычислительная машина', 20, 12, 1, NULL, 'Программа в памяти: универсальная машина, меняющая задачу без перепайки.', 'Ламповые машины считали в тысячи раз быстрее релейных, но перенастраивались перекоммутацией. Решающим стал принцип хранимой программы: команды лежат в памяти наравне с данными.

Отсюда universality — одна и та же машина считает баллистику, ведёт бухгалтерию и печатает расписание, если ей дать другую программу.

С переходом на транзисторы машина уменьшилась и подешевела настолько, что вышла из лабораторий в конторы, банки и на заводы, где и начала менять устройство труда.'),
  (249, 1, 't_laser', 'Лазер', 18, 12, 1, NULL, 'Когерентный свет: узкий пучок одной длины волны.', 'В основе — вынужденное излучение, предсказанное Эйнштейном: возбуждённый атом, получив фотон, испускает точно такой же. Резонатор из зеркал усиливает поток, и получается пучок почти без расхождения.

Лазер называли решением, ищущим задачу; применения нашлись повсюду — резка металла, хирургия глаза, измерение расстояний, считывание диска, передача по волокну, разметка и голография.

Без лазера нет ни оптической связи, ни точной обработки, ни современной метрологии: секунду и метр сегодня определяют именно через свет.'),
  (250, 1, 't_tv', 'Телевидение', 4, 12, 1, NULL, 'Передача движущегося изображения: единая картина для миллионов.', 'Электронно-лучевая трубка развёртывает изображение построчно, а передающая трубка делает обратное. К пятидесятым годам телевизор стал массовым предметом обихода.

Телевидение изменило политику: облик и манера кандидата стали значить не меньше доводов, а прямой репортаж с войны во Вьетнаме впервые показал избирателю то, что прежде оставалось в сводках.

Оно же создало общее культурное поле: миллионы людей одновременно видят одно и то же событие — этого не было ни при газете, ни при радио.'),
  (251, 1, 't_auto_lines', 'Автоматизированные линии', 14, 12, 1, NULL, 'Станки с числовым управлением и линия, работающая без рабочего у каждой операции.', 'Числовое управление задаёт станку траекторию программой, а не копиром или руками оператора. Сложная деталь изготавливается одинаково и повторяемо, а переналадка сводится к смене программы.

Связанные в линию станки с автоматической передачей заготовки убрали человека из промежуточных операций, оставив ему наладку и контроль.

Здесь начинается долгий спор о замещении труда машиной: производительность растёт, но рабочих мест на прежнем производстве становится меньше, а требования к оставшимся — выше.'),
  (252, 1, 't_molecular_bio', 'Молекулярная биология (ДНК)', 21, 12, 1, NULL, 'Двойная спираль и генетический код: наследственность как запись.', 'Структуру ДНК установили в 1953 году по рентгенограммам Розалинд Франклин, и двойная спираль сразу объяснила главное: цепи комплементарны, значит, каждая может служить образцом для копирования.

Затем был расшифрован код: тройка нуклеотидов задаёт аминокислоту, и он оказался почти одинаковым у всего живого — довод в пользу общего происхождения.

Наследственность стала информацией, которую можно читать и, как выяснится позже, переписывать. Вся современная биотехнология выросла из этого открытия.'),
  (253, 1, 't_nuclear_sub', 'Атомные подводные лодки', 12, 12, 1, NULL, 'Реактор на борту: автономность, ограниченная только запасом пищи.', 'Дизельная лодка обязана всплывать для зарядки батарей и потому уязвима. Реактор не требует воздуха, и лодка может месяцами не показываться на поверхности.

Соединённая с баллистическими ракетами, она стала самым неуязвимым звеном ядерного сдерживания: обнаружить её в океане практически невозможно, а значит, ответный удар гарантирован.

Именно эта неуязвимость, по мысли стратегов, и делала первый удар бессмысленным, стабилизируя противостояние.'),
  (254, 1, 't_particle_physics', 'Физика элементарных частиц', 18, 12, 1, NULL, 'Ускорители и стандартная модель: устройство вещества на глубине.', 'Ускоритель разгоняет частицы и сталкивает их: чем выше энергия, тем меньшие расстояния можно разглядеть. Обнаруженный зоопарк частиц потребовал наведения порядка.

Порядок дала кварковая модель и объединение взаимодействий в стандартную модель — теорию, подтверждённую с точностью, редкой для науки.

Побочные плоды оказались повсеместными: ускорители применяют в медицине и промышленности, а World Wide Web был придуман в ЦЕРНе для обмена данными между физиками.'),
  (255, 1, 't_rocketry', 'Ракетостроение', 22, 12, 1, NULL, 'Жидкостная ракета: тяга в пустоте и выход за пределы атмосферы.', 'Циолковский вывел уравнение, связывающее скорость ракеты с расходом топлива, и показал, что для орбиты нужна многоступенчатая схема. Годдард запустил первую жидкостную ракету.

Военная программа Фау-2 дала работающую конструкцию и производственную базу, а после войны её инженеры и решения оказались по обе стороны противостояния.

Ракета — единственное средство движения, не нуждающееся в опоре на среду, и потому единственная дорога в космос. Она же стала носителем ядерного оружия, соединив космонавтику и стратегию неразрывно.'),
  (256, 1, 't_rocket_artillery', 'Ракетная артиллерия', 16, 12, 1, NULL, 'Залповый огонь неуправляемыми ракетами по площади.', 'Реактивный снаряд не требует тяжёлого ствола: пусковая установка легка, а вся нагрузка приходится на направляющие. Отсюда возможность разом выпустить десятки снарядов с автомобиля.

Точность одиночного выстрела низка, но залп накрывает площадь, и по эффекту внезапного удара система превосходит ствольную артиллерию.

Тактика соответствует технике: залп — и немедленная смена позиции, поскольку пуск демаскирует установку мгновенно.'),
  (257, 1, 't_rpg', 'Реактивные гранатомёты', 9, 12, 1, NULL, 'Кумулятивный заряд с плеча: пехотинец против танка.', 'Кумулятивная струя пробивает броню не силой удара, а сфокусированным потоком металла, поэтому пробитие не зависит от скорости снаряда. Значит, гранату можно запускать со слабой отдачей.

Безоткатная схема с истечением газов назад позволила стрелять таким зарядом с плеча, не ломая стрелку ключицу.

Пехота впервые получила средство против танка, доступное каждому отделению, и танковый прорыв перестал быть неотразимым. Ответом стали разнесённая, а затем динамическая защита.'),
  (258, 1, 't_mbt', 'Основной боевой танк', 15, 12, 1, NULL, 'Единый танк вместо лёгких, средних и тяжёлых: броня, пушка и подвижность разом.', 'Опыт войны показал, что деление танков на классы неудобно: лёгкий беззащитен, тяжёлый неподвижен. Новые двигатели и материалы позволили соединить достоинства в одной машине.

Комбинированная броня из слоёв металла и керамики резко подняла защиту от кумулятивной струи, а стабилизатор и дальномер дали стрельбу с ходу.

Такой танк стал основой сухопутных сил на полвека, а его стоимость и сложность сделали танкостроение показателем промышленного уровня страны.'),
  (259, 1, 't_satellites', 'Спутники', 22, 12, 1, NULL, 'Аппарат на орбите: связь, разведка, навигация и наблюдение Земли.', 'Спутник виден одновременно с огромной территории, и это определило его применения: ретрансляция сигнала, съёмка, метеонаблюдение и навигация.

Запуск первого искусственного спутника в 1957 году стал политическим потрясением не меньшим, чем техническим: он означал, что и ракета через океан долетит.

Геостационарная орбита, на которой аппарат висит над одной точкой, сделала возможным непрерывное вещание и связь — идею предложил писатель Артур Кларк за полтора десятилетия до её осуществления.'),
  (260, 1, 't_manned_space', 'Пилотируемая космонавтика', 22, 12, 1, NULL, 'Человек на орбите и на Луне: жизнеобеспечение и возвращение.', 'Полёт Гагарина в 1961 году показал, что человек переносит невесомость и перегрузки, а главная инженерная трудность — не подъём, а возвращение: торможение об атмосферу и тепловая защита.

Лунная программа была предприятием невиданного масштаба — сотни тысяч участников — и решалась политическими, а не научными доводами.

После неё пилотируемая космонавтика перешла к долговременным станциям, где главным стало не рекордное достижение, а рутина жизни и работы на орбите месяцами.'),
  (261, 1, 't_containers', 'Контейнерные перевозки', 13, 12, 1, NULL, 'Стандартный ящик: единая перевозка судном, поездом и грузовиком.', 'Прежде груз перегружали поштучно, и стоянка судна под погрузкой длилась неделями. Стандартный контейнер перегружается краном за минуты и идёт дальше без распаковки.

Стоимость перевозки упала на порядок, и это, а не какие-либо соглашения, стало главной технической причиной глобализации: производить за океаном стало дешевле, чем рядом.

Изменились и порты: старые городские причалы с толпами грузчиков умерли, а грузооборот ушёл на новые терминалы, где работает техника.'),
  (262, 1, 't_waste', 'Переработка отходов', 19, 12, 1, NULL, 'Сбор, сортировка и обезвреживание промышленных и бытовых отходов.', 'Массовое производство породило массовый мусор, а пластик и радиоактивные отходы добавили к этому вещества, которые не разлагаются или опасны столетиями.

Сформировался подход: сокращать, использовать повторно, перерабатывать. Полигон перестал быть просто ямой и превратился в сооружение с гидроизоляцией и сбором газа.

Самой трудной задачей остаются высокоактивные отходы: их приходится изолировать на сроки, превышающие всю писаную историю человечества, и общепринятого решения до сих пор нет.'),
  (263, 1, 't_silicon', 'Кремниевая технология', 1, 13, 1, NULL, 'Сверхчистый кремний и фотолитография: схемы на одной пластине.', 'Кремний должен быть чище любого другого промышленного материала: посторонних атомов допускается меньше одного на миллиард. Монокристалл вытягивают из расплава медленным вращением затравки.

Фотолитография переносит рисунок схемы на пластину светом через маску, и весь процесс идёт сразу для сотен кристаллов — отсюда обвал цены на транзистор.

Наблюдение Мура о том, что число элементов на кристалле удваивается примерно каждые два года, оказалось не законом природы, а самоисполняющимся планом отрасли, по которому она сознательно жила полвека.'),
  (264, 1, 't_microprocessor', 'Микропроцессор', 20, 13, 1, NULL, 'Вычислитель на одном кристалле: универсальная деталь вместо шкафа.', 'Микропроцессор собрал арифметику, управление и регистры в один кристалл. Вычислитель перестал быть сооружением и стал деталью, которую можно купить и впаять.

Это сразу изменило проектирование: вместо разработки схемы под задачу стали брать готовый процессор и писать для него программу. Сложность ушла из железа в код.

Микропроцессоры разошлись повсюду — в станок, автомобиль, весы, часы и игрушку, — и их встроенных экземпляров сегодня во много раз больше, чем компьютеров в привычном смысле.'),
  (265, 1, 't_personal_computer', 'Персональный компьютер', 20, 13, 1, NULL, 'Машина на столе у одного человека и рынок готовых программ.', 'Пока машина стоила как здание, ею распоряжался вычислительный центр по заявкам. Персональный компьютер отдал вычисление прямо в руки человека, который решает задачу.

Решающим оказалось не железо, а программы массового спроса: электронная таблица окупала машину в конторе за недели, и покупали её именно ради этого.

Графический интерфейс с окнами и мышью убрал необходимость помнить команды и открыл компьютер людям без технической подготовки — после этого рост стал лавинообразным.'),
  (266, 1, 't_fiber', 'Оптическое волокно', 18, 13, 1, NULL, 'Свет в стеклянной нити: связь ёмкостью, недостижимой для меди.', 'Свет удерживается в сердцевине волокна полным внутренним отражением. Задача была в прозрачности: пока стекло гасило сигнал за метры, связь была невозможна; сверхчистое кварцевое волокно снизило потери в тысячи раз.

Одно волокно толщиной с волос несёт больше разговоров, чем целый медный кабель, и не боится наводок.

Трансокеанские оптические линии заменили спутниковую связь для основного объёма трафика: сегодня почти весь международный интернет идёт по кабелям на дне океана, а не через космос.'),
  (267, 1, 't_comp_modeling', 'Компьютерное моделирование', 8, 13, 1, NULL, 'Численный эксперимент: расчёт там, где опыт невозможен или дорог.', 'Многие уравнения не решаются в общем виде, но их можно просчитать шаг за шагом. Компьютер сделал такой расчёт практичным, и появился третий способ познания наряду с теорией и опытом.

Прогноз погоды, прочность конструкции, обтекание крыла, свёртывание белка, распространение эпидемии — всё это считается, а не измеряется.

Вместе с возможностями пришла и новая осторожность: модель воспроизводит заложенные в неё допущения, и красивый результат может не иметь отношения к действительности.'),
  (268, 1, 't_internet', 'Интернет', 4, 13, 1, NULL, 'Сеть сетей на общих протоколах: связь без единого центра.', 'Ключевое решение — пакетная передача: сообщение режется на части, каждая идёт своим путём и собирается у получателя. Сеть без центра переживает потерю любого узла.

Протоколы TCP/IP позволили соединять разнородные сети, не переделывая их, и рост пошёл без общего плана.

Всемирная паутина, придуманная в ЦЕРНе для обмена документами, дала простое средство навигации — гиперссылку — и превратила сеть исследователей в общедоступную среду, изменившую торговлю, печать, политику и повседневность.'),
  (269, 1, 't_ind_robots', 'Промышленные роботы', 14, 13, 1, NULL, 'Программируемый манипулятор: сварка, окраска, сборка без человека.', 'Промышленный робот отличается от автомата тем, что его задачу меняют программой, а не переделкой механизма. Одна и та же машина сваривает кузов и переставляет детали.

Роботы взяли на себя работы вредные и однообразные — окраску, сварку, литьё, — где человек быстро теряет здоровье и внимание.

Автомобильная промышленность стала главным заказчиком, и уровень роботизации на десятилетия сделался мерилом технического развития страны.'),
  (270, 1, 't_precision_weapons', 'Высокоточное оружие', 16, 13, 1, NULL, 'Управляемый снаряд: попадание вместо накрытия площади.', 'Управление в полёте — по лазерной подсветке, телевизионной картинке или спутниковому сигналу — сделало вероятность попадания близкой к единице.

Изменилась арифметика войны: цель, на которую прежде уходили сотни бомб, поражается одной. Отсюда и меньший расход, и меньшие сопутствующие разрушения.

Обратная сторона — политическая: точность создала представление о «чистой» войне и снизила порог применения силы, а зависимость от спутникового сигнала стала новым уязвимым местом.'),
  (271, 1, 't_attack_heli', 'Боевые вертолёты', 15, 13, 1, NULL, 'Винтокрылая машина с управляемым оружием: манёвр у самой земли.', 'Вертолёт может висеть, выглядывать из-за складки местности и уходить, оставаясь вне зоны видимости. Это сделало его идеальным носителем противотанковых ракет.

Появилась аэромобильность: пехоту стало возможно перебрасывать и снабжать через местность, непроходимую для техники, что впервые в больших масштабах показала война во Вьетнаме.

Уязвимость к переносным зенитным комплексам оказалась столь же значимой: дешёвая ракета с плеча ограничила применение дорогой машины.'),
  (272, 1, 't_high_rise', 'Высотное строительство', 10, 13, 1, NULL, 'Сверхвысокие здания: расчёт ветра, ядро жёсткости, скоростные лифты.', 'Выше определённой отметки главная нагрузка не вес, а ветер: здание раскачивается, и задача не в прочности, а в жёсткости и в допустимом ускорении для людей внутри.

Решением стали жёсткое ядро, наружные фермы и демпферы — маятники в сотни тонн, гасящие колебания.

Без компьютерного расчёта такие конструкции невозможны: число сочетаний нагрузок слишком велико для ручной проверки, и высотное строительство прямо зависит от вычислительной техники.'),
  (273, 1, 't_hsr', 'Высокоскоростные поезда', 13, 13, 1, NULL, 'Выделенные линии на 250–350 км/ч: поезд быстрее самолёта на средних дистанциях.', 'Высокая скорость требует отдельного пути: плавные кривые, отсутствие переездов, бесстыковой рельс и контроль в кабине вместо придорожных сигналов, которые невозможно прочесть на ходу.

На дистанциях в несколько сотен километров поезд выигрывает у самолёта «от центра до центра», потому что не требует поездки в аэропорт и досмотра.

Безопасность оказалась исключительной: за десятилетия работы первых сетей не было ни одной жертвы в столкновениях или сходах.'),
  (274, 1, 't_solar', 'Солнечная энергия', 2, 13, 1, NULL, 'Фотоэлектрические панели: электричество прямо из света.', 'Фотоэлемент рождает ток при поглощении света без единой движущейся части. Первым заказчиком стала космонавтика, где иного источника на орбите просто нет.

Цена ватта падала десятилетиями по мере роста производства, и солнечная энергия из экзотики превратилась в самый дешёвый источник в солнечных регионах.

Главная трудность не в панели, а в непостоянстве: выработка зависит от времени суток и погоды, поэтому солнечная энергетика неотделима от накопителей и перестройки сетей.'),
  (275, 1, 't_green_revolution', 'Зелёная революция', 11, 13, 1, NULL, 'Короткостебельные сорта, удобрения и полив: урожай втрое.', 'Обычная пшеница при обильном удобрении вытягивается и полегает. Выведенные короткостебельные сорта направляют питание в зерно, а не в солому, и выдерживают высокие дозы удобрений.

Сорта, азот, полив и защита растений работают только вместе — по отдельности каждый элемент даёт немного.

Индия и Мексика перешли от импорта зерна к самообеспечению, а предсказания неизбежного массового голода не сбылись. Ценой стали расход воды, зависимость от удобрений и утрата местных сортов.'),
  (276, 1, 't_genetic_engineering', 'Генная инженерия', 21, 13, 1, NULL, 'Рекомбинантная ДНК: перенос гена между организмами.', 'Ферменты рестрикции режут ДНК в определённых местах, лигаза сшивает — этого набора хватило, чтобы вставить чужой ген в бактерию и заставить её работать по новой программе.

Первым практическим итогом стал человеческий инсулин, производимый бактериями: прежде его добывали из поджелудочных желёз животных.

Учёные сами первыми забеспокоились: Асиломарская конференция 1975 года ввела добровольные ограничения на опыты — редкий и до сих пор приводимый в пример случай самоограничения научного сообщества.'),
  (277, 1, 't_bioweapon', 'Биологическое оружие', 21, 13, 1, NULL, 'Боевое применение возбудителей болезней и запрет на него.', 'Биологическое оружие обещает несоразмерный эффект при ничтожных затратах, но неуправляемо: возбудитель не различает своих и чужих и не признаёт линии фронта.

Именно военная бесполезность вместе с моральным отвращением сделала возможной конвенцию 1972 года — первый договор о полном запрете целого класса оружия.

Слабость конвенции в проверке: то же оборудование служит и вакцине, и оружию, поэтому надзор упирается в намерения, а не в технику, — и это остаётся нерешённой задачей.'),
  (278, 1, 't_genetic_diagnostics', 'Генетическая диагностика', 7, 13, 1, NULL, 'Выявление наследственных болезней и предрасположенностей.', 'Полимеразная цепная реакция позволила размножить ничтожное количество ДНК до объёма, пригодного для анализа. Это сделало генетический тест дешёвым и повседневным.

Диагностика наследственных болезней, определение отцовства и судебная идентификация выросли из одного и того же приёма.

Вместе с этим появились и трудные вопросы: знание о предрасположенности, которую нельзя предотвратить, и опасность отбора по генетическому признаку при страховании или найме.'),
  (279, 1, 't_tomography', 'Томография', 7, 13, 1, NULL, 'Послойное изображение тела: рентгеновская и магнитно-резонансная.', 'Компьютерная томография снимает объект с разных сторон и восстанавливает срез расчётом — задача, которую без вычислительной машины не решить.

Магнитно-резонансная томография использует отклик ядер водорода в сильном поле и прекрасно различает мягкие ткани, не облучая пациента.

Врач впервые увидел внутренность живого человека послойно и без разреза. По воздействию на диагностику это сравнимо разве что с появлением рентгена.'),
  (280, 1, 't_chromatography', 'Аналитическая химия', 6, 13, 1, NULL, 'Хроматография и масс-спектрометрия: состав смеси до следовых количеств.', 'Хроматография разделяет смесь, пропуская её через среду, где вещества движутся с разной скоростью. Масс-спектрометр определяет их по отношению массы к заряду.

Связка этих приборов даёт чувствительность в миллиардные доли: обнаружить примесь в воде, допинг в крови или следы взрывчатки стало рутиной.

Именно с этого начинается современный экологический и пищевой контроль: нормировать содержание вещества имеет смысл лишь тогда, когда его умеют измерять надёжно и дёшево.'),
  (281, 1, 't_derivatives', 'Финансовые деривативы', 17, 13, 1, NULL, 'Опционы, фьючерсы и модели их оценки; электронные торги.', 'Формула оценки опциона дала рынку общий язык: разные участники стали считать стоимость риска примерно одинаково, и рынок производных вырос взрывообразно.

Задуманы деривативы как страховка от колебаний цены и курса, и в этом качестве они полезны производителю и перевозчику.

Но те же инструменты позволяют принимать огромный риск при малом залоге. Крах хедж-фонда LTCM, а затем кризис 2008 года показали, что модель, верная в спокойное время, ломается именно тогда, когда она нужнее всего.'),
  (282, 1, 't_space_station', 'Орбитальные станции', 22, 13, 1, NULL, 'Долговременное присутствие в космосе и многоразовый корабль.', 'Станция сместила смысл космонавтики с рекорда на работу: экипаж живёт на орбите месяцами, ведёт опыты и обслуживает технику.

Накопились и медицинские сведения: невесомость вымывает кальций из костей и ослабляет мышцы, поэтому многочасовые ежедневные тренировки — обязательная часть распорядка.

Многоразовый корабль обещал удешевить доступ на орбиту, но обслуживание оказалось дороже расчётного, а две катастрофы показали цену сложности. Урок учли уже в следующем поколении носителей.'),
  (283, 1, 't_env_protection', 'Защита окружающей среды', 19, 13, 1, NULL, 'Нормирование выбросов, оценка воздействия и международные соглашения.', 'Смог, кислотные дожди и отравленные реки сделали загрязнение политическим вопросом. Появились предельно допустимые концентрации, обязательная экологическая экспертиза и ответственность за ущерб.

Монреальский протокол об озоноразрушающих веществах стал редчайшим примером полного успеха: запрет сработал, и озоновый слой восстанавливается.

Он же показал условия удачи: ясная причина, измеримый вред, доступная замена веществу и ограниченный круг производителей. Там, где этих условий нет, договориться намного труднее.'),
  (284, 1, 't_nanomaterials', 'Наноматериалы', 1, 14, 1, NULL, 'Углеродные трубки, графен, покрытия: свойства из размера частицы.', 'На масштабе нанометров вещество ведёт себя иначе: доля поверхностных атомов велика, и прочность, проводимость и цвет зависят уже от размера частицы, а не только от состава.

Углеродная нанотрубка и графен показывают рекордную прочность и проводимость, но перенос этих свойств на изделие макроскопического размера остаётся нерешённой задачей.

Практическая отдача пока в покрытиях и добавках: самоочищающиеся поверхности, катализаторы, упрочняющие присадки к бетону и полимерам.'),
  (285, 1, 't_hts', 'Высокотемпературные сверхпроводники', 18, 14, 1, NULL, 'Проводники без сопротивления при температуре жидкого азота.', 'Сверхпроводимость известна с начала века, но требовала жидкого гелия. Керамические материалы, открытые в 1986 году, работают при температуре жидкого азота, который дешевле молока.

Общепринятой теории этих материалов до сих пор нет — редкий случай, когда практика надолго обогнала объяснение.

Применения там, где нужны сильные поля: томографы, ускорители, установки термоядерного синтеза. Массовой передаче энергии мешает хрупкость керамики, из которой трудно сделать длинный кабель.'),
  (286, 1, 't_big_data', 'Big Data и аналитика', 8, 14, 1, NULL, 'Обработка потоков данных, не помещающихся в одну машину.', 'Когда данных больше, чем памяти любой машины, меняется сам подход: вычисление распределяют по тысячам узлов и приносят программу к данным, а не наоборот.

Появился новый способ рассуждения: на достаточно больших выборках устойчивая связь обнаруживается статистически, даже если механизм неизвестен.

Отсюда и главная опасность: корреляция без понимания причины легко ведёт к ложным выводам, а данные несут в себе перекосы того общества, которое их породило.'),
  (287, 1, 't_machine_learning', 'Машинное обучение', 20, 14, 1, NULL, 'Модель, настраиваемая на примерах, а не программируемая правилами.', 'Вместо описания правил системе показывают размеченные примеры, и она подбирает параметры так, чтобы ошибка на них была наименьшей.

Глубокие нейронные сети выстрелили, когда сошлись три условия: массивы размеченных данных, дешёвые параллельные вычисления на графических процессорах и приёмы обучения глубоких моделей.

Результат оказался двойственным: там, где раньше требовался специалист — перевод, распознавание речи и изображений, — качество выросло скачком, но объяснить решение модели зачастую невозможно.'),
  (288, 1, 't_mobile', 'Мобильная связь', 4, 14, 1, NULL, 'Сотовая сеть и смартфон: сеть в кармане у каждого.', 'Сотовый принцип решает нехватку частот: территория делится на ячейки, и одна и та же частота используется повторно в несотрудничающих ячейках.

Смартфон соединил телефон, компьютер, камеру, приёмник спутниковой навигации и магазин программ в одном предмете, который человек носит с собой постоянно.

Во многих странах мобильная связь пришла раньше проводной и стала первым способом доступа в интернет, а мобильные платежи — первой банковской услугой для миллионов людей.'),
  (289, 1, 't_digital_economy', 'Цифровая экономика', 17, 14, 1, NULL, 'Платформы, сетевые эффекты и товар с нулевой стоимостью копии.', 'У цифрового товара себестоимость копии практически нулевая, поэтому выгода полностью определяется масштабом, а рынок склоняется к нескольким победителям.

Платформа зарабатывает не производством, а посредничеством: она сводит стороны и берёт долю, а сетевой эффект делает её тем ценнее, чем больше на ней участников.

Отсюда и новые вопросы: концентрация рынков, данные пользователя как плата за бесплатную услугу и положение работников платформ, формально независимых, а фактически подчинённых её алгоритму.'),
  (290, 1, 't_crypto', 'Криптовалюты и блокчейн', 17, 14, 1, NULL, 'Распределённый реестр без доверенного посредника.', 'Блокчейн решает задачу согласия между незнакомыми участниками: цепочка блоков защищена хешами, а изменить прошлое дороже, чем следовать правилам.

Ценой стала расточительность: доказательство работой потребляет электричества столько же, сколько средняя страна, и это вызвало переход части сетей к другим способам согласования.

Как средство платежа криптовалюты не прижились из-за колебаний курса, зато сама идея реестра без центра нашла применение в учёте прав, поставок и подлинности документов.'),
  (291, 1, 't_additive', 'Аддитивное производство', 14, 14, 1, NULL, 'Печать изделия послойно: сложная форма без оснастки.', 'Обычная обработка отнимает лишнее, печать добавляет нужное. Сложность формы перестаёт удорожать деталь, а оснастка не нужна вовсе.

Отсюда выгода на единичных и мелких партиях: протез по мерке пациента, деталь для старой машины, снятой с производства, оптимизированный расчётом кронштейн со странными очертаниями.

Массовому производству печать пока проигрывает по скорости и цене, поэтому речь идёт о дополнении привычных способов, а не об их замене.'),
  (292, 1, 't_renewables', 'Возобновляемая энергетика', 2, 14, 1, NULL, 'Ветер, солнце и накопители: энергия без топлива и выбросов.', 'Ветровая и солнечная генерация стали дешевле угольной по стоимости киловатт-часа, и переход пошёл по экономическим причинам не меньше, чем по экологическим.

Главная трудность — непостоянство: сеть должна балансироваться ежесекундно, а солнце и ветер не подчиняются спросу. Отсюда роль накопителей, чья цена падала так же быстро.

Литий-ионный аккумулятор оказался ключевой технологией сразу двух переходов — энергетического и транспортного, что и определило спрос на литий, кобальт и никель.'),
  (293, 1, 't_ev', 'Электромобили', 13, 14, 1, NULL, 'Тяговый аккумулятор и электропривод вместо двигателя и коробки.', 'Электромобиль появился раньше бензинового, но проиграл ему из-за батареи. Вернуть его смог только литий-ионный аккумулятор с приемлемой ёмкостью и ресурсом.

Устройство машины упрощается радикально: нет коробки передач, сцепления, выхлопа и почти нет обслуживания, а рекуперация возвращает часть энергии при торможении.

Экологический выигрыш зависит от того, чем заряжают: на угольной генерации он невелик, на возобновляемой — значителен. Отдельная задача — переработка отслуживших батарей.'),
  (294, 1, 't_smart_buildings', 'Умные здания', 10, 14, 1, NULL, 'Датчики и управление климатом: здание как регулируемая система.', 'На здания приходится значительная доля потребления энергии, поэтому основной выигрыш даёт не архитектура, а управление: отопление, вентиляция и освещение по фактическому присутствию людей и погоде.

Пассивный дом добавляет к этому оболочку: толстое утепление, герметичность и рекуперация тепла вытяжки позволяют обходиться почти без отопления.

Обратная сторона — уязвимость и сложность: здание, зависящее от сети датчиков и контроллеров, требует обслуживания и защиты от вмешательства.'),
  (295, 1, 't_precision_ag', 'Точное земледелие', 11, 14, 1, NULL, 'Спутниковая навигация и датчики: норма вносится по каждому участку поля.', 'Поле неоднородно, а вносили всегда поровну. Навигация с точностью до сантиметров позволила менять норму удобрений и защиты прямо по ходу движения, следуя карте участка.

Результат двойной: расход химикатов падает, а урожайность растёт, потому что каждая часть поля получает своё.

Автоматическое вождение по спутнику убрало перекрытие проходов и работу «на глаз», а заодно избавило механизатора от самой утомительной части труда.'),
  (296, 1, 't_genome_seq', 'Секвенирование генома', 21, 14, 1, NULL, 'Чтение полной последовательности ДНК: от проекта века до рядового анализа.', 'Первый геном человека прочли за тринадцать лет и миллиарды долларов. Секвенирование нового поколения читает миллионы коротких фрагментов параллельно и собирает их расчётом.

Цена упала быстрее, чем дешевели микросхемы, и сегодня геном читают за сутки и за стоимость обычного медицинского обследования.

Это изменило и медицину, и историю: анализ древней ДНК переписал представления о расселении человека и о родстве народов, дав источник, независимый от археологии и языка.'),
  (297, 1, 't_personalized_med', 'Персонализированная медицина', 7, 14, 1, NULL, 'Лечение по генетическому профилю больного и его опухоли.', 'Один и тот же препарат помогает не всем: различия в генах обмена веществ меняют и действие, и переносимость. Тест до назначения позволяет выбрать лекарство и дозу осмысленно.

В онкологии подход зашёл дальше всего: лечение подбирают по мутациям конкретной опухоли, а не по органу, в котором она возникла.

Ограничения экономические: разработка препарата для узкой группы больных дорога, а цена такого лечения ставит перед системами здравоохранения тяжёлые вопросы справедливого распределения.'),
  (298, 1, 't_mrna', 'мРНК-вакцины', 7, 14, 1, NULL, 'Вакцина как код белка: разработка за дни, производство без выращивания вируса.', 'Классическая вакцина требует вырастить и обезвредить возбудителя. мРНК-вакцина передаёт клетке инструкцию собрать один белок оболочки, на который и вырабатывается иммунитет.

Достаточно знать последовательность: разработку ведут на компьютере за дни, а производство не зависит от культивирования вируса.

Технология вызревала десятилетиями и упиралась в две задачи — устойчивость молекулы и её доставку в клетку липидной оболочкой. Пандемия дала повод и средства довести её до применения в рекордный срок.'),
  (299, 1, 't_green_chem', 'Зелёная химия', 6, 14, 1, NULL, 'Синтез без токсичных растворителей и с минимумом отходов.', 'Классический синтез даёт отходов в разы больше, чем продукта. Зелёная химия ставит задачу иначе: считать не выход реакции, а долю исходного вещества, попавшую в продукт.

Средства — катализ вместо стехиометрических реагентов, вода вместо органических растворителей, биокатализ ферментами при обычной температуре.

Экономический довод оказался сильнее природоохранного: отходы приходится обезвреживать за деньги, поэтому чистый процесс просто дешевле, и отрасль перешла к нему добровольно.'),
  (300, 1, 't_drones', 'Ударные беспилотники', 15, 14, 1, NULL, 'Аппарат без экипажа: разведка и удар без риска для лётчика.', 'Беспилотник может часами висеть над районом, чего не выдержит экипаж, и стоит несравнимо дешевле самолёта, потому что не нуждается ни в кабине, ни в системах спасения.

Дешёвые аппараты изменили и войну малых сил: разведка и корректировка стали доступны любому подразделению, а серийный коммерческий квадрокоптер оказался эффективным оружием.

Отдельный вопрос — этический: удалённость оператора за тысячи километров меняет и восприятие применения силы, и порядок ответственности за него.'),
  (301, 1, 't_loitering', 'Барражирующие боеприпасы', 16, 14, 1, NULL, 'Боеприпас, ожидающий цель в воздухе и атакующий по обнаружении.', 'Барражирующий боеприпас соединяет разведчика и снаряд: он кружит над районом, передаёт картинку и пикирует на цель, когда она найдена.

Это снимает главную задержку между обнаружением и ударом, из-за которой подвижная цель обычно успевает уйти.

Стоимость такого боеприпаса на порядки ниже, чем у поражаемой им техники, и это перевернуло привычную экономику боя: дорогая машина уязвима для дешёвого расходуемого аппарата.'),
  (302, 1, 't_precision_small_arms', 'Высокоточное лёгкое оружие', 9, 14, 1, NULL, 'Оптика, баллистические вычислители и ночные прицелы.', 'Точность одиночного стрелка выросла не за счёт ствола, а за счёт прицела: баллистический вычислитель учитывает дальность, ветер, температуру и даже вращение Земли.

Тепловизор и ночной прицел отменили ночь как укрытие: сторона, видящая в темноте, получает подавляющее преимущество.

Стоимость прицельных приспособлений сегодня нередко превышает стоимость самого оружия — показатель того, куда сместился центр тяжести стрелкового дела.'),
  (303, 1, 't_usv', 'Автономные морские платформы', 12, 14, 1, NULL, 'Безэкипажные надводные и подводные аппараты.', 'Безэкипажный аппарат не ограничен выносливостью людей и может месяцами вести наблюдение, поиск мин или картографирование дна.

Подводная связь остаётся узким местом: радиоволны в воде не распространяются, поэтому аппарат обязан действовать самостоятельно и всплывать для передачи данных.

Военное значение выросло стремительно: дешёвые безэкипажные катера показали, что крупный боевой корабль уязвим для средств, стоящих несравнимо меньше него.'),
  (304, 1, 't_reusable_rockets', 'Многоразовые носители', 22, 14, 1, NULL, 'Возвращаемая первая ступень: снижение цены вывода на порядок.', 'Основная стоимость запуска — в ракете, которая используется один раз. Возврат первой ступени с посадкой на двигателях позволил применять её многократно.

Задача была в управлении: посадить пустую ступень с работающим двигателем на малой тяге — вопрос вычислений и точного управления, ставший разрешимым лишь недавно.

Снижение цены изменило то, что вообще имеет смысл запускать: спутниковые группировки из тысяч аппаратов немыслимы при прежней стоимости вывода.'),
  (305, 1, 't_climate_model', 'Климатическое моделирование', 19, 14, 1, NULL, 'Расчёт климата и оценка последствий выбросов.', 'Климатическая модель делит атмосферу и океан на ячейки и считает перенос тепла, влаги и вещества между ними. Проверяют её способностью воспроизвести уже наблюдавшийся климат прошлого.

Модели независимых групп сходятся в главном: рост концентрации парниковых газов ведёт к потеплению, а его величина зависит от того, сколько будет выброшено.

Отсюда и практический вывод, лёгший в основу соглашений: важна не сама скорость выбросов, а их накопленный итог, поэтому отсрочка мер дороже, чем кажется.'),
  (306, 1, 't_quantum_computing', 'Квантовые вычисления', 8, 15, 1, NULL, 'Вычисление на суперпозиции состояний: задачи, недоступные обычной машине.', 'Кубит может находиться в суперпозиции состояний, и вычисление идёт сразу по многим ветвям, а измерение выбирает одну. Выигрыш даёт не перебор, а интерференция, гасящая неверные ответы.

Известные алгоритмы обещают решить лишь узкий круг задач — разложение на множители, поиск, моделирование молекул, — но именно эти задачи чрезвычайно важны.

Главное препятствие — декогеренция: кубит теряет состояние от малейшего воздействия, и на один устойчивый логический кубит требуются тысячи физических.'),
  (307, 1, 't_agi', 'Искусственный интеллект общего назначения', 20, 15, 1, NULL, 'Система, переносящая обучение с задачи на задачу без переделки.', 'Нынешние модели сильны там, где много данных, но плохо переносят навык на непохожую задачу. Общий интеллект предполагает именно перенос: научившись одному, применить к другому.

Оценки сроков расходятся от единиц лет до столетия, и это само по себе показывает, что предмет ещё не понят.

Вопрос согласования целей стоит острее технического: система, преследующая заданную цель мощнее человека, опасна не злым умыслом, а буквальным пониманием задачи, поставленной неточно.'),
  (308, 1, 't_quantum_gravity', 'Квантовая гравитация', 18, 15, 1, NULL, 'Объединение тяготения с квантовой теорией.', 'Две опоры физики несовместимы: общая теория относительности описывает непрерывное пространство-время, квантовая механика — дискретность и вероятность. В обычных условиях это не мешает, но при огромной плотности обе теории нужны сразу.

Такие условия — центр чёрной дыры и первые мгновения Вселенной, где нынешние уравнения дают бесконечности вместо ответа.

Предложенные подходы пока не дают предсказаний, которые можно проверить доступными средствами, и это делает область необычной: математики много, опыта почти нет.'),
  (309, 1, 't_fusion', 'Термоядерный синтез', 2, 15, 1, NULL, 'Энергия слияния лёгких ядер: топливо из воды и почти без отходов.', 'Синтез требует удержать плазму в сотни миллионов градусов, не давая ей коснуться стенок. Магнитное удержание в токамаке и инерционное сжатие лазером — два основных подхода.

Награда велика: топливо из воды и лития, отсутствие цепной реакции и долгоживущих отходов, невозможность аварии с разгоном.

В 2022 году инерционная установка впервые получила больше энергии, чем поглотила мишень. До электростанции остаётся путь, но принципиальный порог наконец пройден.'),
  (310, 1, 't_hydrogen', 'Водородная энергетика', 2, 15, 1, NULL, 'Водород как накопитель и топливо для того, что не электрифицировать.', 'Водород ценен не как источник — его надо получать, — а как способ хранить и перевозить энергию там, где батарея не годится: в металлургии, химии, тяжёлом транспорте и авиации.

Смысл он имеет только при производстве электролизом на возобновляемой энергии; полученный из газа, он не даёт выигрыша по выбросам.

Трудности физические: водород занимает много места, просачивается сквозь металл и делает его хрупким, поэтому вся инфраструктура требует отдельных решений.'),
  (311, 1, 't_metamaterials', 'Метаматериалы', 1, 15, 1, NULL, 'Структура вместо состава: свойства, которых нет у природных веществ.', 'Свойства метаматериала задаёт не химия, а геометрия его ячеек, размер которых меньше длины управляемой волны. Так получают отрицательное преломление и управляемое огибание волной препятствия.

На звуковых и радиоволнах маскировка предмета уже достигнута; для видимого света требуется структура нанометрового масштаба на широкий диапазон, и это остаётся нерешённым.

Практическое применение ближе в другом: плоские линзы, антенны, поглотители шума и сейсмическая защита сооружений.'),
  (312, 1, 't_molecular_eng', 'Молекулярная инженерия', 6, 15, 1, NULL, 'Сборка вещества по заданной схеме на уровне отдельных молекул.', 'Замысел прост и труден: собирать материал не смешиванием, а укладкой отдельных молекул в заданном порядке, получая точно предсказанные свойства.

Пока сделано немногое: молекулярные машины, переключатели и роторы, отмеченные Нобелевской премией, работают в растворе и по отдельности.

Более реалистичным считается путь самосборки, где молекулы сами занимают нужные положения, — этому уже учится и природа, и лаборатория.'),
  (313, 1, 't_synth_bio', 'Синтетическая биология', 21, 15, 1, NULL, 'Организм как конструкция: стандартные генетические узлы и сборка генома.', 'Синтетическая биология относится к клетке как к платформе: гены собирают в узлы с предсказуемым поведением и составляют из них схемы — датчики, переключатели, счётчики.

Уже получены микроорганизмы, производящие лекарства и топливо, а также клетка с полностью синтезированным геномом.

Редактирование CRISPR сделало вмешательство дешёвым и доступным, и вместе с этим остро встал вопрос ограничений: технология, доступная небольшой лаборатории, плохо поддаётся надзору.'),
  (314, 1, 't_human_bioeng', 'Биоинженерия человека', 7, 15, 1, NULL, 'Замена и восстановление тканей, редактирование генома, продление здоровой жизни.', 'Направления складываются в одно: выращивание тканей и органов из собственных клеток пациента, исправление наследственных болезней редактированием и вмешательство в механизмы старения.

Терапия наследственных болезней уже применяется и излечивает состояния, прежде неизлечимые, хотя стоимость исчисляется миллионами.

Граница между лечением и улучшением остаётся спорной, а редактирование половых клеток затрагивает потомков, которые не могут дать согласия, — поэтому оно запрещено почти повсеместно.'),
  (315, 1, 't_neural_link', 'Нейроинтерфейсы', 4, 15, 1, NULL, 'Прямая связь мозга с машиной: управление мыслью и возврат чувствительности.', 'Интерфейс считывает активность нейронов и переводит её в команды. Парализованные пациенты уже управляют курсором и протезом, а обратная связь возвращает подобие осязания.

Неинвазивные способы безопасны, но грубы; вживляемые электроды точны, но требуют операции и со временем зарастают тканью.

Самый трудный вопрос не технический: активность мозга — предельно личные сведения, и право на неприкосновенность мысли уже обсуждается как отдельная правовая категория.'),
  (316, 1, 't_exoskeleton', 'Экзоскелеты', 15, 15, 1, NULL, 'Носимая силовая рама: усиление человека без замены его машиной.', 'Экзоскелет передаёт нагрузку на раму и добавляет усилие приводами, следуя движению человека. Ключевая трудность — угадать намерение достаточно быстро, чтобы помощь не мешала.

Медицинское применение самое зрелое: реабилитация после травм позвоночника и помощь в ходьбе.

В промышленности прижились пассивные конструкции без двигателей: они просто разгружают спину и плечи при подъёме и работе с поднятыми руками, и этого уже достаточно для снижения травматизма.'),
  (317, 1, 't_autonomous_weapons', 'Автономные боевые платформы', 9, 15, 1, NULL, 'Системы, выбирающие и поражающие цель без участия человека.', 'Техническая возможность распознать и поразить цель без оператора уже существует; спор идёт о допустимости.

Доводы за — скорость реакции выше человеческой и отсутствие усталости; доводы против — неспособность машины оценить соразмерность и различить сдающегося, а также неясность ответственности за ошибку.

Переговоры о запрете идут годами и упираются в определение: почти любое современное оружие содержит элементы автоматики, и провести границу оказывается труднее, чем договориться о принципе.'),
  (318, 1, 't_orbital_weapon', 'Кинетическое орбитальное оружие', 16, 15, 1, NULL, 'Удар с орбиты массивным телом без взрывчатого вещества.', 'Тело, сброшенное с орбиты, набирает такую скорость, что кинетической энергии хватает без всякой взрывчатки: разрушение сравнимо с мощным зарядом.

Соблазн в отсутствии радиоактивного заражения и в считанных минутах подлётного времени; препятствие — стоимость вывода массы на орбиту.

Договор о космосе запрещает размещать на орбите оружие массового поражения, но кинетические системы в него формально не попадают, и этот пробел остаётся предметом спора.'),
  (319, 1, 't_autonomous_factory', 'Автономные фабрики', 14, 15, 1, NULL, 'Производство, работающее без людей в цеху.', 'Полностью безлюдное производство существует там, где номенклатура узка, а операции повторяемы: обработка, сборка узлов, упаковка и склад.

Труднее всего даётся то, что человеку даётся легко: взять незакреплённую деталь произвольной формы, заметить неполадку по звуку, приспособиться к нестандартной ситуации.

Поэтому реалистичнее не безлюдный завод, а перераспределение: человек занимается наладкой, контролем и разбором нештатных случаев, а рутина уходит машине.'),
  (320, 1, 't_megastructures', 'Мегаструктуры', 10, 15, 1, NULL, 'Сооружения предельного масштаба: башни, купола, космические конструкции.', 'Предел высоты задаёт не прочность материала, а его собственный вес: конструкция должна нести прежде всего саму себя, и потому выигрыш даёт только рост удельной прочности.

Космический лифт требует троса длиной десятки тысяч километров, для которого не существует материала: даже расчётные свойства нанотрубок на таких длинах пока недостижимы.

Ближе к осуществлению закрытые купольные комплексы и подземные сооружения: они решают задачу защищённой среды, не требуя невозможных материалов.'),
  (321, 1, 't_interplanetary', 'Межпланетные экспедиции', 22, 15, 1, NULL, 'Пилотируемый полёт к другой планете и возвращение.', 'Главное препятствие не двигатель, а человек: полёт к Марсу и обратно занимает годы, в течение которых экипаж получает значительную дозу космического излучения и теряет костную массу.

Запас на дорогу неподъёмен, поэтому расчёт строится на использовании местных ресурсов: получении топлива и кислорода из атмосферы и грунта планеты назначения.

Отдельная трудность — психологическая: экипаж на годы оказывается в тесноте, без возможности вернуться досрочно и без разговора в реальном времени с Землёй.'),
  (322, 1, 't_space_colony', 'Космическая колонизация', 22, 15, 1, NULL, 'Постоянные поселения вне Земли с замкнутым жизнеобеспечением.', 'Поселение отличается от станции тем, что не может зависеть от снабжения: нужен замкнутый круговорот воды, воздуха и пищи. Опыты вроде «Биосферы-2» показали, как трудно удержать такую систему в равновесии.

Пониженная тяжесть остаётся неизвестной величиной: как она влияет на развитие ребёнка, никто не знает, и без ответа на это вопрос о постоянном поселении открыт.

Правовая сторона не проще: договор о космосе запрещает присвоение небесных тел, но ничего не говорит о том, кому принадлежит добытое на них.'),
  (323, 1, 't_autonomous_transport', 'Автономный транспорт', 13, 15, 1, NULL, 'Транспорт без водителя: город и логистика без человека за рулём.', 'Восприятие обстановки решено достаточно надёжно; трудность в редких и странных случаях, которых в обучающих данных почти нет, а на дороге они обязательно встретятся.

Ближе всего к применению замкнутые среды: карьер, порт, склад, выделенная полоса магистрали — там обстановка предсказуема.

Общественная сторона не проще технической: единичное происшествие с беспилотником вызывает несравнимо больший резонанс, чем тысячи обычных аварий, и порог доверия к машине заведомо выше, чем к человеку.'),
  (324, 1, 't_vertical_farms', 'Вертикальные фермы', 11, 15, 1, NULL, 'Многоярусное выращивание в замкнутой среде под искусственным светом.', 'Замкнутая ферма даёт урожай круглый год, расходует на порядок меньше воды и не нуждается в пестицидах, а расположена может быть прямо в городе, что убирает перевозку.

Плата — свет: он заменяет даровое солнце и составляет основную часть себестоимости, поэтому экономика фермы прямо зависит от цены электроэнергии.

Поэтому пока выгодны лишь зелень и ягода — культуры дорогие и скоропортящиеся. Зерновые в таком виде выращивать бессмысленно: поле даёт их несравнимо дешевле.'),
  (325, 1, 't_terraforming', 'Терраформирование', 19, 15, 1, NULL, 'Изменение среды планеты до пригодной для жизни.', 'Для Марса задача упирается в вещество: доступного углекислого газа не хватает, чтобы создать заметное давление, даже если испарить всё, что есть в грунте и полярных шапках.

Отсутствие магнитного поля означает, что атмосферу будет сдувать солнечным ветром, хотя и медленно по человеческим меркам.

Реалистичнее локальное решение — купола и подземные полости с созданной средой. Заодно обсуждается и обратная сторона: имеем ли мы право необратимо изменять планету, на которой может обнаружиться собственная жизнь.'),
  (326, 1, 't_postscarcity', 'Постдефицитная экономика', 17, 15, 1, NULL, 'Хозяйство, где производство почти не требует труда.', 'Если производство и услуги обеспечиваются автоматикой, привычная связь между трудом и доходом рвётся, а вместе с ней и способ распределения, на котором держится нынешнее хозяйство.

Дефицит при этом не исчезает совсем: остаются земля, редкие материалы, энергия, внимание и подлинность — то, что нельзя размножить копированием.

Отсюда обсуждение безусловного дохода, сокращения рабочего времени и общественной собственности на средства автоматизации. Вопрос не столько технический, сколько политический: кому достанется выигрыш от машин.'),
  (327, 1, 't_deep_sea', 'Глубоководное освоение', 12, 15, 1, NULL, 'Работа и добыча на дне океана.', 'Океанское дно исследовано хуже поверхности Луны: давление на глубине в сотни атмосфер, полная темнота и невозможность радиосвязи делают работу там сложнее космической.

Железомарганцевые конкреции на дне содержат никель, кобальт и редкие металлы, нужные для батарей, и добыча их технически возможна уже сегодня.

Против выступает биология: донные сообщества восстанавливаются веками, а последствия поднятия взвеси на километры вокруг непредсказуемы. Международный орган по морскому дну до сих пор не выдал разрешений на промышленную добычу.'),
  (328, 2, 'c_kinship', 'Родовые кланы', 23, 1, 1, 'uploads/tech/stone/kinship.svg', 'Счёт родства как основа общества: кто кому свой и кто кому обязан.', 'В обществе без государства родство — единственный способ определить обязанности: кого кормить, с кем не вступать в брак, за кого мстить и с кем делить добычу.

Этнографы описывают поразительно сложные системы терминов родства, различающие линии, поколения и стороны так подробно, как европейские языки не умеют. Это не прихоть: каждое различие несёт правило поведения.

Запрет брака внутри своей группы вынуждает искать супруга на стороне, и брак становится главным способом связать соседние коллективы прочнее любого договора.'),
  (329, 2, 'c_custom', 'Обычай и кровная месть', 24, 1, 1, 'uploads/tech/stone/custom.svg', 'Неписаное правило и ответ за вред: возмездие соразмерное или выкуп.', 'Право в дописьменном обществе — это обычай, который все знают и никто не записывал. Нарушение затрагивает не отдельного человека, а его род, поэтому и ответ даёт род.

Кровная месть кажется дикостью, но выполняет роль сдерживания там, где нет ни суда, ни силы принуждения: расплата неотвратима, и потому нападение невыгодно.

Рядом с местью почти всюду появляется выкуп — вира, композиция, — позволяющий прервать цепочку ответных убийств платой. Именно из этого выкупа вырастет позднейшее возмещение вреда.'),
  (330, 2, 'c_oral_teaching', 'Устная передача знаний', 25, 1, 1, 'uploads/tech/stone/oral_teaching.svg', 'Обучение показом и рассказом: ремесло, тропа, растение, обряд.', 'Всё знание общества хранится в живых головах, поэтому смерть старика — потеря библиотеки. Отсюда особое положение стариков и почтение к памяти.

Устная традиция вырабатывает приёмы удержания: ритм, повтор, формула, привязка сведений к местности и к обряду. Так запоминаются сотни растений и маршруты в тысячи километров.

Обучение идёт не уроком, а участием: ребёнок годами наблюдает и повторяет за взрослым, и умение переходит целиком вместе с обстоятельствами его применения.'),
  (331, 2, 'c_animism', 'Анимизм и тотемизм', 26, 1, 1, 'uploads/tech/stone/animism.svg', 'Одушевление природы и родство группы со зверем-покровителем.', 'Анимизм видит волю и намерение в звере, реке, камне и ветре. Это не наивность, а рабочая модель мира: с тем, у кого есть воля, можно договориться, попросить, умилостивить.

Тотем связывает группу с определённым животным или растением, задавая одновременно и запрет на его убийство, и знак принадлежности, отличающий своих от чужих.

Практический смысл заметен в правилах охоты: обряд извинения перед убитым зверем и запрет брать больше нужного работают как ограничение промысла задолго до всякой мысли об охране природы.'),
  (332, 2, 'c_burial', 'Ритуал погребения', 27, 1, 1, 'uploads/tech/stone/burial.svg', 'Намеренное захоронение с вещами: отношение к смерти как к переходу.', 'Намеренное погребение — древнейшее прямое свидетельство представлений о том, что смерть не есть простое исчезновение. Положение тела, охра, вещи и пища в могиле говорят о продолжении пути.

Богатство инвентаря в отдельных погребениях верхнего палеолита указывает и на различие положений: не все хоронились одинаково, а значит, не все были равны.

Могила — ещё и привязка к месту: она делает участок земли своим, связывая живых с предками через определённую точку на местности.'),
  (333, 2, 'c_taboo', 'Табу и запреты', 27, 1, 1, 'uploads/tech/stone/taboo.svg', 'Безусловный запрет, не требующий объяснения и обеспеченный страхом.', 'Табу отличается от правила тем, что не обсуждается: нарушение опасно само по себе, независимо от того, узнает ли кто-нибудь. Это делает его самым дешёвым способом принуждения — надзор не нужен.

Многие запреты имеют видимую пользу: пищевые ограничения, правила разделки, недопуск к определённым местам в определённый сезон.

Другие пользы не имеют вовсе и служат иначе: соблюдение непонятного запрета — заметный знак принадлежности к своим, а именно это в малом обществе ценится чрезвычайно высоко.'),
  (334, 2, 'c_shamanism', 'Шаманская практика', 27, 1, 1, 'uploads/tech/stone/shamanism.svg', 'Посредник между людьми и невидимым: лечение, гадание, обряд перехода.', 'Шаман — первый специалист в истории: человек, чьё занятие не добыча пищи. Его готовят через испытание, болезнь или обучение, и он один умеет то, чего не умеют остальные.

Он лечит, ищет пропавшее, предсказывает удачу охоты и ведёт обряды перехода — рождения, взросления, смерти, — в которых общество подтверждает своё устройство.

Появление такой фигуры означает, что группа способна прокормить того, кто не добывает пищи. С этого начинается всякая специализация — и жречество, и медицина, и власть.'),
  (335, 2, 'c_ancestor_cult', 'Культ предков', 26, 1, 1, 'uploads/tech/stone/ancestor_cult.svg', 'Умершие как продолжающие участвовать в жизни рода.', 'Предок не исчезает: он следит за соблюдением обычая, помогает потомкам и наказывает за отступление. Так умершие становятся хранителями порядка, которого некому больше охранять.

Отсюда обязанность приношений и поминовения: прервать её — значит лишить предка поддержки и навлечь беду, и это одно из самых устойчивых правил в истории.

Культ предков даёт и обоснование власти: тот, кто ведёт род от особенно могущественного предка, притязает на особое положение. Все позднейшие династии пользуются этим доводом.'),
  (336, 2, 'c_myth_thinking', 'Мифологическое мышление', 28, 1, 1, 'uploads/tech/stone/myth_thinking.svg', 'Объяснение мира рассказом о начале: как всё стало таким, как есть.', 'Миф отвечает не «почему», а «откуда»: устройство мира объясняется рассказом о событии первых времён, и порядок вещей оказывается следствием чьего-то поступка.

Такое объяснение практично: оно связывает разрозненные наблюдения в единую картину и одновременно обосновывает обычай — так поступают потому, что так было положено в начале.

Миф не проверяется и не опровергается, но именно он приучает к вопросу о причине и к связному рассказу о мире. Философия вырастет, поставив тот же вопрос иначе.'),
  (337, 2, 'c_cave_art', 'Наскальное искусство', 29, 1, 1, 'uploads/tech/stone/cave_art.svg', 'Изображение как действие: звери, знаки и отпечатки рук в пещерах.', 'Пещерная живопись возрастом в десятки тысяч лет поражает точностью наблюдения: художник передаёт повадку и движение зверя так, как способен лишь тот, кто много часов за ним следил.

Расположение росписей в труднодоступных залах говорит о том, что это не украшение жилья: до многих изображений нужно ползти сотни метров.

Отпечатки ладоней — древнейший знак присутствия: «я был здесь». С них начинается то, что позже станет и подписью, и памятником.'),
  (338, 2, 'c_music', 'Музыка', 29, 1, 1, 'uploads/tech/stone/music.svg', 'Ритм, голос и первые инструменты: согласование людей звуком.', 'Древнейшие найденные флейты из кости птицы и бивня имеют продуманный строй отверстий — это уже инструмент, а не свисток.

Ритм и совместное пение обладают редким свойством: они синхронизируют людей физически, снижая напряжение и укрепляя чувство общности. Многие исследователи видят в этом главную причину появления музыки.

Музыка неотделима от обряда и от труда: под ритм пляшут, гребут, толкут зерно и шагают. Она организует совместное действие лучше любой команды.'),
  (339, 2, 'c_signs', 'Знаковые системы', 30, 1, 1, 'uploads/tech/stone/signs.svg', 'Метка, зарубка и узор: устойчивый знак с закреплённым значением.', 'Между рисунком и письмом лежит долгий промежуточный слой: клеймо владельца, зарубка счёта, узор, обозначающий род, знак на тропе.

Такой знак ещё не передаёт речь, но уже несёт условленное значение и понятен без присутствия того, кто его оставил.

Именно этот навык — договориться о значении метки — окажется решающим: из хозяйственных клейм и счётных знаков через тысячелетия вырастет письменность.'),
  (340, 2, 'c_gift_exchange', 'Дарообмен и взаимность', 31, 1, 1, 'uploads/tech/stone/gift_exchange.svg', 'Обмен дарами, обязывающий к ответу: связь важнее выгоды.', 'В обществах без рынка вещи движутся не куплей, а дарением, которое обязывает к ответному дару. Отказ принять или не ответить — оскорбление и разрыв отношений.

Смысл такого обмена не хозяйственный, а связующий: дар создаёт длящееся обязательство, тогда как купля-продажа его гасит на месте.

Поэтому расстояние, на которое расходятся раковины и обсидиан, измеряется сотнями километров задолго до появления купцов: вещи идут по цепочке взаимных обязательств между соседями.'),
  (341, 2, 'c_labor_division', 'Разделение труда', 32, 1, 1, 'uploads/tech/stone/labor_division.svg', 'Распределение занятий по полу, возрасту и умению.', 'Древнейшее разделение — по полу и возрасту: собирательство, охота, обработка шкур, присмотр за детьми. Это не иерархия, а способ покрыть все нужды малой группой.

Постепенно добавляется разделение по умению: лучший мастер по камню, лучший следопыт, знающий травы. Такой человек получает долю добычи за своё умение.

Разделение труда создаёт взаимную зависимость: никто не обеспечивает себя целиком, и группа держится вместе не только родством, но и необходимостью.'),
  (342, 2, 'c_chiefdom', 'Вождество', 33, 1, 1, 'uploads/tech/stone/chiefdom.svg', 'Признанный глава над несколькими общинами: распределение и суд.', 'Вождь отличается от старейшины тем, что его положение наследуется и распространяется на несколько общин. Он собирает часть урожая и раздаёт её на пирах, в неурожай и на общие дела.

Власть его держится не на принуждении — постоянной силы у него нет, — а на щедрости, происхождении и умении разрешать споры.

Археологически вождество опознаётся по резко выделяющимся погребениям и по постройкам, которые не под силу одной общине: их возведение и есть доказательство того, что кто-то способен собрать людей.'),
  (343, 2, 'c_clan_militia', 'Родовое ополчение', 34, 1, 1, 'uploads/tech/stone/clan_militia.svg', 'Вооружённые мужчины рода: набег, оборона и месть.', 'Постоянного войска нет: воюют те же люди, что охотятся, тем же оружием и по тем же навыкам. Собираются по родству и расходятся, как только дело окончено.

Война такого рода — не сражение армий, а набег и засада, где потери в несколько человек считаются тяжёлыми. Но при малой численности групп доля погибших за жизнь оказывается высокой.

Мотив чаще всего не захват земли, а месть, угон скота и захват женщин — то есть продолжение тех же отношений родства и обязательства другими средствами.'),
  (344, 2, 'c_tribal_alliance', 'Межплеменные союзы', 35, 1, 1, 'uploads/tech/stone/tribal_alliance.svg', 'Договор соседних групп: мир, брак, торговля и общая оборона.', 'Союз скрепляется не бумагой, а обменом: брачным, дарственным и обрядовым. Обменялись жёнами и дарами — значит, связаны и воевать не будете.

Отсюда обязательные приёмы дипломатии, дожившие до наших дней: совместная трапеза, подарок, гостеприимство и неприкосновенность посланца.

Союзы делали возможным то, что не под силу одной группе: сезонные общие охоты, проход по чужой земле к нужному источнику сырья и совместный отпор чужакам.'),
  (345, 2, 'c_camp', 'Стойбище и очаг', 36, 1, 1, 'uploads/tech/stone/camp.svg', 'Постоянное место жизни: расположение жилищ, общее пространство, хранилище.', 'Планировка стоянки — первый градостроительный замысел: жилища ставят кругом или рядами, оставляя середину под общее дело, а хранилища и очаги размещают по определённому порядку.

Оседлость меняет всё: появляется имущество, которое не унести, запас, который нужно охранять, и мусорная куча, по которой археологи потом восстановят весь быт.

Постоянное поселение требует и новых правил: как делить пространство, кто где живёт, куда девать отходы. Это первые задачи городского общежития в зародыше.'),
  (346, 2, 'c_games', 'Состязания и игры', 37, 1, 1, 'uploads/tech/stone/games.svg', 'Соревнование в силе и ловкости: обучение, отбор и разрядка вражды.', 'Состязание тренирует ровно то, что нужно для охоты и войны — бег, метание, борьбу, стрельбу — но без риска потерять людей.

Оно же служит отбором: победитель получает признание и лучшие шансы в браке, а группа узнаёт, на кого можно положиться в трудном деле.

Между соседними группами состязание нередко заменяет столкновение: спор решается борьбой выставленных бойцов, а не набегом. Эта замена драки игрой окажется одним из самых долговечных общественных изобретений.'),
  (347, 2, 'c_proto_state', 'Протогосударства', 33, 2, 1, NULL, 'Власть над многими общинами с постоянным аппаратом сбора и учёта.', 'Государство отличается от вождества постоянством: есть люди, чьё занятие — управлять, они получают содержание и служат не по родству, а по должности.

Первые такие образования выросли в долинах больших рек, где ирригация требовала согласованного труда, а зерно можно было хранить, считать и изымать.

Именно хранимый и учитываемый излишек делает государство возможным: собранное зерно кормит чиновника, воина и жреца, которые сами не пашут.'),
  (348, 2, 'c_monarchy', 'Монархия', 33, 2, 1, NULL, 'Единоличная наследственная власть, обоснованная происхождением и богами.', 'Царь соединяет в себе три роли: военного вождя, верховного судьи и посредника между людьми и богами. Последнее и делает его власть неоспоримой.

Наследование решает главную беду вождества — смуту при смене власти, — но порождает свою: наследник может оказаться негоден, а обойти его нельзя без подрыва самого принципа.

Отсюда постоянное напряжение всех монархий: правило престолонаследия защищает от борьбы за власть ровно до тех пор, пока его признают все стороны.'),
  (349, 2, 'c_law_codes', 'Писаные своды законов', 24, 2, 1, NULL, 'Закон, записанный и выставленный: одно правило для всех подданных.', 'Законы Хаммурапи высечены на стеле, поставленной на виду, и это существенно: записанный закон нельзя переиначить по случаю, на него можно сослаться.

Содержание нам кажется суровым — талион, различие наказаний по сословиям, — но сама идея переворотна: спор решается по правилу, а не по воле судьи.

В прологе царь объявляет целью защиту слабого от сильного. Насколько это исполнялось, судить трудно, но само притязание власти на роль защитника справедливости появляется здесь и уже не исчезает.'),
  (350, 2, 'c_pantheon', 'Пантеон богов и жречество', 26, 2, 1, NULL, 'Упорядоченное собрание богов и сословие служителей храма.', 'Боги выстраиваются в иерархию, повторяющую земную: верховный владыка, его приближённые, покровители ремёсел и городов. Небо начинает выглядеть как двор.

Храм становится не только святилищем, но и хозяйством: он владеет землёй, стадами и складами, ведёт учёт и даёт в долг.

Жречество — первое сословие, живущее знанием: календарём, обрядом и письмом. Его власть держится на том, что сроки праздников и разливов знают только они.'),
  (351, 2, 'c_temple_rites', 'Храмовые обряды', 27, 2, 1, NULL, 'Регулярное служение по календарю: жертва, процессия, праздник.', 'Обряд из случая по нужде превращается в расписание: ежедневное кормление божества, сезонные праздники, торжества нового года.

Такой распорядок требует хозяйства — животных, зерна, масла, тканей — и потому напрямую связывает веру с изъятием части урожая.

Праздник выполняет и общественную работу: он собирает людей из разных общин, показывает им величие власти и на несколько дней снимает будничные различия между ними.'),
  (352, 2, 'c_cosmogony', 'Космогония и миропорядок', 28, 2, 1, NULL, 'Учение о происхождении мира и о месте в нём человека и власти.', 'Записанные космогонии — вавилонская, египетская, позже библейская — впервые излагают устройство мира связно и целиком, от начала до нынешнего порядка.

Важно их назначение: миропорядок объявляется установленным, а власть царя — частью этого установления. Мятеж оказывается не спором о власти, а посягательством на устройство мира.

Тогда же появляется и первое сомнение: тексты о невинном страдальце спрашивают, почему праведник терпит бедствие. Из этого вопроса вырастет вся позднейшая философия и богословие.'),
  (353, 2, 'c_retinue', 'Дружина и военные вожди', 34, 2, 1, NULL, 'Постоянный отряд при вожде, живущий войной и его содержанием.', 'Дружина — первое войско, которое не расходится по домам: воины живут при вожде, едят с его стола и получают долю добычи.

Это меняет и войну, и власть: у правителя появляется сила, не зависящая от согласия общин, и он может принуждать, а не только уговаривать.

Взамен он обязан водить дружину в походы и щедро одаривать: правитель, переставший воевать и раздавать, быстро терял и дружину, и власть.'),
  (354, 2, 'c_warrior_code', 'Кодекс воина', 34, 2, 1, NULL, 'Правила чести: с кем биться, как поступать с побеждённым, что позорно.', 'Воинская честь — не украшение, а способ сделать войну предсказуемой: правила о вызове, о неприкосновенности посла, об обращении с пленным ограничивают разрушение и позволяют закончить войну миром.

Кодекс задаёт и внутреннюю иерархию: воин, нарушивший правило, теряет положение среди своих вернее, чем от поражения в бою.

Эпос закрепляет эти правила образцами поведения: слушая о герое, воин заучивает, как надлежит поступать, — это обучение через рассказ, а не через устав.'),
  (355, 2, 'c_debt', 'Долг и обязательство', 31, 2, 1, NULL, 'Записанное обязательство вернуть: расписка, срок, поручительство и залог.', 'Долг древнее монеты: расписки на зерно и серебро с указанием срока и свидетелей составляют огромную часть древнейших письменных документов.

Долг создаёт зависимость, которой не знало родовое общество: должник обязан не родичу, а чужому человеку, и обязан не обычаем, а записью.

Долговое бремя быстро стало опасным для самого государства, и цари объявляли прощение долгов при восшествии на престол — древнейшая известная мера против разорения крестьянства.'),
  (356, 2, 'c_long_trade', 'Дальняя торговля', 31, 2, 1, NULL, 'Постоянные пути и фактории: металл, камень, ткани и предметы роскоши.', 'Бронза заставила торговать: медь и олово почти нигде не залегают рядом, и целые государства зависели от привозного металла.

Появились купеческие товарищества, фактории в чужих городах и договоры о защите торговцев — древнейшие известные международные соглашения касаются именно этого.

Вместе с товаром идут письмо, мера веса, обряд и рассказ. Дальняя торговля — главный переносчик всего остального, и по её путям культуры узнают друг о друге задолго до всякой политики.'),
  (357, 2, 'c_workshops', 'Ремесленные мастерские', 32, 2, 1, NULL, 'Постоянное ремесло при дворце или храме: мастер, живущий своим умением.', 'Мастерская при храме или дворце — первое производство, отделённое от домашнего хозяйства. Мастер получает сырьё и содержание и отдаёт готовое изделие.

Ремесло становится наследственным: приёмы держат в семье, и это надолго определяет устройство ремесленного мира.

Появляется и клеймо — знак мастера или мастерской, по которому отвечают за качество. Древнейшие торговые марки старше монеты.'),
  (358, 2, 'c_debt_slavery', 'Долговое рабство', 32, 2, 1, NULL, 'Обращение в зависимость за долг или плен: труд как имущество.', 'Рабство древнего мира происходит из двух источников: плена и долга. Второй опаснее — он превращает соплеменников в зависимых и подтачивает общество изнутри.

Положение раба сильно различалось: от почти домашнего до каторжного в рудниках. Во многих обществах рабство было срочным и заканчивалось отработкой долга.

Законы рано ограничивают долговую кабалу — сроком, запретом на продажу за границу, периодическим прощением. Это показывает, что опасность понимали и сами законодатели.'),
  (359, 2, 'c_scribe_schools', 'Школы писцов', 25, 2, 1, NULL, 'Обучение письму и счёту как профессии: первая школа с программой и экзаменом.', 'Школа писцов — древнейшее учебное заведение, известное по документам: сохранились учебные таблички с прописями, списками слов, задачами и жалобами учеников на розги.

Обучение долгое и трудное: клинопись насчитывает сотни знаков, и грамотность остаётся достоянием немногих.

Зато писец получает должность и достаток, и школа впервые даёт возможность продвинуться не по рождению, а по выучке — узкую, но настоящую.'),
  (360, 2, 'c_epic', 'Эпическая поэзия', 29, 2, 1, NULL, 'Большое повествование о героях: память, образец поведения и общая история.', 'Эпос о Гильгамеше, старейший из дошедших, говорит о дружбе, славе и неизбежности смерти — темах, которые не устареют.

Эпос выполняет работу учебника: он передаёт представление о должном и недолжном через поступки героев, и слушатель запоминает правило вместе с историей.

Он же создаёт общее прошлое: люди разных общин, знающие одни и те же сказания, начинают чувствовать себя единым народом. Это одно из древнейших средств объединения.'),
  (361, 2, 'c_alphabet', 'Алфавит', 30, 2, 1, NULL, 'Запись звуков десятками знаков вместо сотен: грамотность становится доступной.', 'Алфавитное письмо родилось на семитском Востоке из упрощения знаков и опиралось на решающую догадку: записывать надо не слово и не слог, а звук.

Число знаков падает с сотен до двух-трёх десятков, и выучиться письму становится делом месяцев, а не многих лет.

Последствия огромны: грамотность перестаёт быть привилегией жреческого сословия, а письмо распространяется по Средиземноморью вместе с торговлей и ложится в основу греческого, латинского и всех происходящих от них алфавитов.'),
  (362, 2, 'c_dynastic_union', 'Династические союзы', 35, 2, 1, NULL, 'Брак между правящими домами как договор, обеспеченный родством.', 'Переписка египетских и ближневосточных дворов показывает вполне сложившуюся дипломатию: цари называют друг друга братьями, обмениваются дарами, торгуются о приданом и жалуются на задержку золота.

Брак был самой прочной формой договора: общий внук связывает династии надёжнее любой клятвы.

Тогда же появляются признаки настоящего дипломатического обихода: постоянные посланцы, протокол приёма, обмен заложниками и договоры о выдаче беглецов.'),
  (363, 2, 'c_estates', 'Сословное деление', 23, 2, 1, NULL, 'Наследственные разряды с разными правами и занятиями.', 'Общество перестаёт быть однородным: жрецы, воины, писцы, ремесленники, земледельцы и зависимые различаются не богатством, а положением по рождению.

Различие закрепляется правом: законы прямо назначают разное наказание за одно и то же деяние в зависимости от сословия сторон.

Сословный порядок объявляется частью миропорядка, установленного богами, и потому не подлежащим обсуждению. Это делает его чрезвычайно устойчивым — и особенно уязвимым, когда сама картина мира меняется.'),
  (364, 2, 'c_city_community', 'Городская община', 36, 2, 1, NULL, 'Город как отдельная общность: стены, храм, рынок и собственный порядок.', 'Город бронзового века — это стена, храм, дворец, склад и рынок. Он живёт не своим полем, а тем, что стягивает из округи и с торговых путей.

Жизнь скученно и среди чужих требует нового: правил о соседстве, воде, отходах, мерах и надзора за порядком.

Появляется и городская гордость: имя города, его бог-покровитель и стены становятся предметом отождествления, зачастую более сильного, чем принадлежность к государству.'),
  (365, 2, 'c_heralds', 'Глашатаи и царские надписи', 38, 2, 1, NULL, 'Оглашение воли власти: указ, надпись на камне, победная реляция.', 'Правитель нуждается в том, чтобы его волю узнали все, и делает это двумя способами: глашатай оглашает указ на площади, а надпись на камне обращается к потомкам.

Царские надписи — древнейший образец пропаганды: победы преувеличены, поражения не упомянуты, а благодеяния перечислены подробно.

Историки читают их с поправкой на жанр, но сам жанр важен: власть впервые обращается к подданным напрямую и через века — и понимает, что образ правления нужно создавать, а не только править.'),
  (366, 2, 'c_polis', 'Полис и гражданство', 33, 3, 1, NULL, 'Город-государство, где верховная власть принадлежит собранию граждан.', 'Полис устроен иначе восточной монархии: власть принадлежит не царю, а собранию граждан, а должности замещаются на срок — по выбору или по жребию.

Гражданство — не подданство, а членство: гражданин участвует в решениях, служит в ополчении и владеет землёй. Оно замкнуто, и чужаку получить его почти невозможно.

Афинская демократия достигла того, что решения принимало собрание всех граждан, а должностных лиц назначал жребий. При этом женщины, переселенцы и рабы прав не имели, и меньшинство правило большинством.'),
  (367, 2, 'c_republic', 'Республика', 33, 3, 1, NULL, 'Разделённые должности, совет и выборность: власть, ограниченная устройством.', 'Римская республика построена на недоверии к единоличной власти: должности коллегиальны, срочны и подотчётны, а высшие магистраты могут отменять решения друг друга.

Сенат из бывших должностных лиц даёт преемственность, народные собрания — согласие, трибуны — защиту от произвола. Полибий видел в этом смешение монархии, аристократии и демократии и объяснял им устойчивость Рима.

Устройство выдержало столетия и рухнуло, когда войско стало верно полководцу, а не государству: республику погубила не идея, а армия.'),
  (368, 2, 'c_civil_law', 'Гражданское право', 24, 3, 1, NULL, 'Право собственности, договора и иска между частными лицами.', 'Римские юристы отделили частное право от власти: спор об имуществе решается по правилам, одинаковым для сторон, независимо от их положения.

Были выработаны понятия, которыми мы пользуемся до сих пор: собственность, владение, договор, обязательство, вина, добросовестность.

Отдельным достижением стало право народов — правила для споров с чужеземцами, из которых выросла мысль о нормах, общих всем людям.'),
  (369, 2, 'c_organized_religion', 'Организованная религия', 26, 3, 1, NULL, 'Государственный культ: жреческие должности, календарь праздников, храмы города.', 'Античный культ — дело общественное, а не личное: жертву приносят от имени города, а жреческая должность нередко выборная и совмещается с политической.

Требуется не вера, а участие: отказ от обряда воспринимался как нелояльность, поскольку от него зависело благополучие всей общины.

Отсюда веротерпимость к чужим богам и одновременно преследование тех, кто отказывался от общего культа: спор шёл не о догмате, а о принадлежности к городу.'),
  (370, 2, 'c_mysteries', 'Мистерии и культы', 27, 3, 1, NULL, 'Закрытые обряды посвящения с обещанием личного спасения.', 'Мистерии отвечали на то, чего не давал государственный культ: личную надежду. Посвящённому обещали иную участь после смерти.

Обряд был тайным, и о содержании его мы знаем мало — участники хранили молчание веками, что само по себе поразительно.

Мистериальные культы распространялись поверх границ и сословий, принимая рабов и женщин наравне со свободными, и подготовили почву для религий спасения, которые вскоре переменят весь античный мир.'),
  (371, 2, 'c_natural_philosophy', 'Натурфилософия', 28, 3, 1, NULL, 'Объяснение мира из его собственных начал, без ссылки на волю богов.', 'Милетские мыслители задали вопрос, которого не задавал миф: из чего всё состоит и по какому правилу устроено? Ответы были разными, важен сам ход.

Появилось и главное новшество — спор: ученик открыто возражает учителю, и объяснение принимается за довод, а не за авторитет.

Отсюда пошли и атомистика, и учение о стихиях, и логика. Античная философия не давала верных ответов о природе, но выработала способ рассуждения, на котором стоит вся наука.'),
  (372, 2, 'c_rhetoric_schools', 'Риторика и школы', 25, 3, 1, NULL, 'Обучение убеждающей речи и рассуждению как основа образования.', 'В обществе, где дела решаются в собрании и суде, умение говорить — прямой путь к влиянию. Софисты первыми стали учить этому за плату.

Риторика разработала строение речи, приёмы доказательства и работу с чувствами слушателя — по сути, первую теорию воздействия на аудиторию.

Сократ и Платон возражали, что искусство убеждать безразлично к истине, и из этого спора выросло различение между тем, что убедительно, и тем, что верно, — различение, нужное и сегодня.'),
  (373, 2, 'c_pro_army', 'Профессиональная армия', 34, 3, 1, NULL, 'Войско на постоянной службе и жалованье, с уставом и выслугой.', 'Реформа, открывшая службу неимущим и назначившая жалованье, превратила ополчение граждан в постоянное войско: воин служит десятилетиями и живёт военным делом.

Появились единое вооружение, обучение по образцу, инженерное дело и обоз — армия стала учреждением, а не собранием вооружённых людей.

Оборотная сторона выявилась быстро: воин, обязанный полководцу наделом и добычей, верен ему, а не государству. Гражданские войны Рима выросли прямо отсюда.'),
  (374, 2, 'c_formation_tactics', 'Строевая тактика', 34, 3, 1, NULL, 'Фаланга и легион: строй, где сила в согласованности, а не в удали.', 'Фаланга превращает толпу воинов в единое тело: щит прикрывает соседа, и строй силён ровно настолько, насколько каждый держит место.

Легион добавил гибкость: деление на манипулы позволяло перестраиваться, менять линии и действовать на пересечённой местности, где сплошная фаланга рассыпалась.

Строй имеет и общественное следствие: он требует равенства и доверия между бойцами. Не случайно расцвет фаланги совпадает с расцветом гражданских общин.'),
  (375, 2, 'c_watch', 'Дозор и стража', 39, 3, 1, NULL, 'Городская стража, охрана дорог и надзор за порядком.', 'Стража решает задачу, отличную от военной: не отразить врага, а поддержать повседневный порядок — тушить пожары, задерживать нарушителей, охранять ворота и рынок.

Римские когорты вигилов были одновременно пожарной охраной и ночным дозором, что показывает, какая опасность считалась главной в тесном городе.

Возникает и постоянное напряжение, знакомое всем позднейшим обществам: сила, поставленная охранять порядок, сама нуждается в надзоре, и вопрос «кто устережёт сторожей» задан именно тогда.'),
  (376, 2, 'c_taxation', 'Налоговая система', 31, 3, 1, NULL, 'Регулярный сбор с переписью, оценкой имущества и откупом.', 'Налог отличается от дани постоянством и расчётом: он опирается на перепись людей и имущества и взимается по правилу, а не по случаю.

Отсюда потребность в учёте — цензе, кадастре, списках — и в чиновниках, которые их ведут. Государство начинает видеть своё население.

Откуп сбора частным лицам решал задачу дёшево, но порождал злоупотребления: откупщик выжимал больше положенного, и ненависть к нему стала общим местом от античности до Нового времени.'),
  (377, 2, 'c_guilds_collegia', 'Ремесленные коллегии', 32, 3, 1, NULL, 'Объединения ремесленников и торговцев со своей кассой и культом.', 'Коллегия соединяла ремесленников одного дела: она вела общий культ, хоронила своих членов, помогала вдовам и представляла ремесло перед властью.

Погребальная касса была едва ли не главной: достойные похороны стоили дорого, и объединение решало эту заботу вскладчину.

Власть относилась к коллегиям с подозрением, видя в них возможный источник смуты, и не раз ограничивала их. Это первое известное столкновение государства с самоорганизацией горожан.'),
  (378, 2, 'c_latifundia', 'Латифундия и рабский труд', 32, 3, 1, NULL, 'Крупное поместье на труде рабов, работающее на рынок.', 'Латифундия — товарное хозяйство: она производит вино, масло и хлеб на продажу, а не для прокорма семьи, и потому нуждается в дешёвом и управляемом труде.

Приток пленных после победоносных войн сделал раба дешевле наёмного работника, и мелкий крестьянин не выдержал соперничества, разоряясь и уходя в город.

Историки видят в этом одну из глубинных причин кризиса республики: разорение крестьянства подорвало и ополчение, и общественное равновесие.'),
  (379, 2, 'c_theatre', 'Театр и скульптура', 29, 3, 1, NULL, 'Драма и пластика: искусство, обращённое ко всему городу.', 'Греческая трагедия выросла из обряда и стала общественным делом: постановка оплачивалась богатыми гражданами как повинность, а посещение считалось долгом.

Драма ставила вопросы, которые нельзя обсуждать прямо: о власти и законе, о долге перед семьёй и государством, о вине и роке.

Скульптура решала иную задачу — изображение человеческого тела как меры совершенства. Её образцы будут служить эталоном при каждом обращении Европы к античности, от Возрождения до классицизма.'),
  (380, 2, 'c_prose', 'Проза и историография', 30, 3, 1, NULL, 'Письменный рассказ о действительном: история, речь, трактат, письмо.', 'Геродот собирал рассказы и сопоставлял их, отделяя слышанное от виденного; Фукидид пошёл дальше, отбросив вмешательство богов и объясняя события расчётом и страстями людей.

Тогда же складываются жанры прозы: речь, письмо, трактат, жизнеописание — формы, которыми европейская словесность пользуется до сих пор.

Появляется и понятие источника: историк ссылается на очевидца, разбирает противоречия и объясняет, почему верит одному свидетельству больше другого.'),
  (381, 2, 'c_embassies', 'Посольства и договоры', 35, 3, 1, NULL, 'Переговоры через посланцев, письменный договор и клятва его соблюдать.', 'Неприкосновенность посла — древнейшая международная норма: без неё переговоры невозможны вовсе, и её соблюдали даже враждующие стороны.

Договор скреплялся клятвой богами обеих сторон и выставлялся на видном месте: нарушение считалось не только вероломством, но и святотатством.

Сложились и приёмы, дожившие до наших дней: посредничество третьей стороны, обмен заложниками как гарантия, разграничение сфер влияния и союз, направленный против общего противника.'),
  (382, 2, 'c_free_and_slave', 'Свободный и раб', 23, 3, 1, NULL, 'Основное деление античного общества и споры о его законности.', 'Различие свободного и раба было для античности главным: оно определяло всё — доступ в суд, право владеть, брак, наказание, самое тело человека.

Оправдание находили в природе: Аристотель писал о «рабах по природе», хотя тут же признавал, что многие оказались в рабстве по случайности войны.

Возражения звучали уже тогда: стоики утверждали, что все люди по природе равны и рабство есть установление людское, а не природное. Из этого довода вырастет вся позднейшая критика неволи.'),
  (383, 2, 'c_city_planning', 'Городское планирование', 36, 3, 1, NULL, 'Регулярная сетка улиц, площадь, водопровод и общественные здания.', 'Гипподамова планировка задала городу правильную сетку улиц с выделенными участками под общественные нужды — первый известный градостроительный замысел, осуществлённый сознательно.

Город получает набор обязательных мест: площадь для собраний, храм, театр, бани, рынок. Их наличие и делает поселение городом в античном смысле.

Римляне довели это до образца, по которому основывали новые города от Британии до Сирии, — и сетка улиц многих европейских городов до сих пор восходит к их лагерной планировке.'),
  (384, 2, 'c_olympics', 'Олимпийские состязания', 37, 3, 1, NULL, 'Общие для всех греков игры со священным перемирием.', 'Игры собирали участников из враждующих городов, и на время их проведения объявлялось священное перемирие, обеспечивавшее безопасный проход к святилищу.

Это редкий случай, когда состязание стало единственным общим делом разрозненных и постоянно воюющих общин: по олимпиадам вели даже летосчисление.

Победитель получал венок, но дома — почести и содержание за счёт города. Слава атлета была славой его полиса, и в этом состязания оказались вполне политическим делом.'),
  (385, 2, 'c_forum', 'Форум и публичное мнение', 38, 3, 1, NULL, 'Площадь как место новостей, слухов, споров и объявлений.', 'Форум и агора — не только рынок, но и главный узел сведений: там оглашают указы, судят, спорят, торгуют и разносят слухи.

В Риме выставлялись ежедневные ведомости с постановлениями сената и городскими происшествиями — древнейший известный прообраз газеты.

Политика тоже пришла на стены: предвыборные надписи Помпей, призывающие голосовать за конкретных кандидатов, сохранились до наших дней и показывают, что борьба за общественное мнение велась вполне узнаваемыми средствами.'),
  (386, 2, 'c_imperial_idea', 'Имперская идея', 40, 3, 1, NULL, 'Мысль о единой державе, несущей порядок многим народам.', 'Империя нуждается в обосновании, отличном от родового: власть над чужими народами надо объяснить не происхождением, а назначением.

Рим нашёл его в идее миссии — усмирять надменных, щадить покорных и нести закон и мир. Римский мир как благо для покорённых стал устойчивой формулой.

Одновременно это подрывает полисную замкнутость: гражданство постепенно распространяется на провинции и в конце концов даётся всем свободным жителям державы — шаг, невозможный в логике города-государства.'),
  (387, 2, 'c_feudalism', 'Феодализм', 33, 4, 1, NULL, 'Земля за службу: сеть личных обязательств вместо жалованья и налога.', 'Когда денег в обращении мало, а государство не в силах содержать войско, правитель платит единственным, что у него есть, — землёй, отдавая её за конную службу.

Отношения строятся не между государством и подданным, а между двумя людьми: сеньор даёт защиту и держание, вассал — верность и службу. Договор скрепляется обрядом присяги.

Слабость видна сразу: вассал моего вассала мне не вассал. Власть дробится, и король нередко оказывается слабее собственных герцогов — на столетия это станет главной политической задачей Европы.'),
  (388, 2, 'c_chancery', 'Придворная канцелярия', 33, 4, 1, NULL, 'Постоянное письменное делопроизводство: грамота, печать, архив.', 'Управление без письма держится на памяти и присутствии правителя. Канцелярия переводит его в документ: грамота с печатью действует и там, где государя нет, и после его смерти.

Печать решает задачу подлинности, архив — задачу памяти: спор о владении разрешается ссылкой на хранимую копию.

Так появляется чиновник, обязанный должности, а не роду, — фигура, из которой со временем вырастет весь государственный аппарат.'),
  (389, 2, 'c_feudal_custom', 'Феодальное обычное право', 24, 4, 1, NULL, 'Право земли и обычая: суд равных, поединок, свидетельство соседей.', 'Единого закона нет: в каждой местности действует свой обычай, а знание его хранится памятью старожилов. Судят не чиновники, а равные — вассалы одного сеньора.

Доказательства своеобразны: очистительная присяга с поручителями, ордалия, судебный поединок. За ними стоит представление, что исход укажет высшая сила.

Постепенно обычаи начинают записывать, и запись меняет их природу: зафиксированный обычай перестаёт незаметно меняться и превращается в закон, который можно только отменить.'),
  (390, 2, 'c_monotheism', 'Монотеизм', 26, 4, 1, NULL, 'Единый Бог, единая истина и вероучение, общее для многих народов.', 'Монотеистическая религия отличается от античного культа притязанием на исключительность: боги соседей не иные боги, а вовсе не боги.

Отсюда и невиданная прежде способность объединять: вера не привязана к городу, роду или языку и принимает любого, кто примет учение. Она перешагивает границы легче, чем любая держава.

Отсюда же и обратная сторона: там, где культ был делом города, чужой бог не мешал; там, где истина одна, разномыслие становится преступлением.'),
  (391, 2, 'c_theology', 'Богословие', 26, 4, 1, NULL, 'Учение о вере, изложенное строго: догмат, собор, ересь.', 'Богословие возникает из необходимости отвечать на вопросы, которых нет в исходных текстах, и делать это одинаково для всей церкви.

Средством стал собор: спорные положения обсуждаются и утверждаются как обязательные, а несогласие получает имя ереси. Так вера обретает точные границы.

Для этого понадобился аппарат греческой философии — понятия сущности, природы, лица. Богословие оказалось наследником античной мысли и передало её университетам, которые вырастут из церковных школ.'),
  (392, 2, 'c_sacraments', 'Церковные таинства', 27, 4, 1, NULL, 'Обряды, сопровождающие жизнь человека от рождения до смерти.', 'Церковь берёт на себя все узловые моменты жизни: рождение, взросление, брак, болезнь, смерть. Каждый обозначен обрядом, и без него событие как бы не состоялось.

Так церковь становится главным регистратором: записи о крещении, венчании и погребении — единственный учёт населения на много веков, и историки до сих пор работают именно с ними.

Отсюда и власть: отлучение лишает человека не только обрядов, но и брака, наследства и погребения — то есть выводит его из общества целиком.'),
  (393, 2, 'c_patristics', 'Патристика', 28, 4, 1, NULL, 'Труды отцов церкви: соединение веры с античной философией.', 'Отцы церкви решали задачу примирения двух наследий: библейского откровения и греческой философии. Августин соединил их так прочно, что западная мысль тысячу лет шла в его русле.

Оттуда пришли темы, ставшие сквозными для европейской философии: свобода воли, природа времени, отношение земного и небесного государства.

«Исповедь» Августина — первое сочинение с обращённым внутрь взглядом, разбирающее собственные побуждения. Европейская традиция самонаблюдения начинается с этой книги.'),
  (394, 2, 'c_vassal_host', 'Конное вассальное войско', 34, 4, 1, NULL, 'Ополчение держателей земли: служба на своём коне и в своём снаряжении.', 'Войско собирается по обязательству держания: каждый вассал приводит оговорённое число конных и служит установленный срок, обычно около сорока дней в году.

Отсюда особенности такой войны: короткие кампании, невозможность долгой осады и постоянные споры о том, обязан ли вассал идти за пределы своей земли.

Снаряжение стоит как небольшое хозяйство, поэтому воин обязательно землевладелец, а военное дело и владение землёй сливаются в одно сословие.'),
  (395, 2, 'c_castle_guard', 'Замковая стража', 39, 4, 1, NULL, 'Гарнизон замка: дозор, контроль дорог и сбор пошлин.', 'Замок держит округу небольшим гарнизоном: полтора десятка человек контролируют переправу, дорогу и мельницу, и обойти их нельзя.

Отсюда двойственная роль: гарнизон и защищает округу от набега, и сам собирает поборы с проезжающих — грань между охраной и грабежом бывала тонкой.

Право строить замок стало важнейшей привилегией: короли постоянно пытались его ограничить, поскольку каждый новый замок означал ещё одну точку власти, не подчинённую им напрямую.'),
  (396, 2, 'c_fairs', 'Ярмарки', 31, 4, 1, NULL, 'Сезонный торг под охраной с особым правом и расчётным днём.', 'Ярмарка решает задачу торговли в мире, где дороги опасны, а денег мало: купцам гарантируют охрану пути, освобождение от части пошлин и особый быстрый суд.

Шампанские ярмарки соединили фламандское сукно с итальянскими товарами Востока и стали местом, где сходились купцы всей Европы.

Там же сложился расчётный день: взаимные долги гасились зачётом, и переводился лишь остаток. Из этой практики выросло всё позднейшее банковское дело.'),
  (397, 2, 'c_serfdom', 'Крепостной труд', 32, 4, 1, NULL, 'Прикрепление крестьянина к земле с повинностями в пользу сеньора.', 'Крепостной не раб: у него своё хозяйство, семья и имущество, и он не может быть продан отдельно от земли. Но он не волен уйти и обязан барщиной и оброком.

Взамен он получает то, чего в смутное время не купишь, — защиту и право пользоваться общинными угодьями.

Судьба этого порядка разошлась: в Западной Европе он размывался с ростом городов и денежной ренты, тогда как восточнее, наоборот, усиливался вплоть до Нового времени.'),
  (398, 2, 'c_monastic_schools', 'Монастырские школы', 25, 4, 1, NULL, 'Обучение при монастыре и переписка книг в скриптории.', 'После упадка городов монастырь остался почти единственным местом, где учили читать и писать. Программа сводилась к семи свободным искусствам, унаследованным от античности.

Скрипторий сохранил античную литературу: почти всё, что дошло до нас, дошло в копиях, сделанных монахами, нередко без всякого интереса к содержанию.

Каролингское возрождение добавило к этому важную мелочь: новое чёткое письмо со строчными буквами и разделением слов. Именно оно легло в основу нашего шрифта.'),
  (399, 2, 'c_icon_chant', 'Иконопись и хоралы', 29, 4, 1, NULL, 'Искусство как богослужение: канонический образ и одноголосное пение.', 'Икона не портрет: она пишется по канону, где поза, цвет и расположение фигур закреплены и не подлежат вольному изменению. Художник не выражает себя, а передаёт образец.

Спор об иконах — иконоборчество — стоил Византии десятилетий смуты и был спором богословским: можно ли изобразить невидимое.

Хорал строился на тех же основаниях: одноголосное пение без инструментов, подчинённое слову. Ради его записи и была изобретена нотация — предок современных нот.'),
  (400, 2, 'c_chronicles', 'Летописание', 30, 4, 1, NULL, 'Погодная запись событий при монастыре или дворе.', 'Летопись ведётся по годам: под каждым годом записывается то, что сочтено достойным памяти, — княжение, война, мор, знамение, неурожай.

Отбор говорит нам не меньше событий: летописец видит в истории замысел, и бедствия толкуются как вразумление, а победы — как милость.

Тексты правились в интересах заказчика, и историки читают их с поправкой. Но без летописей мы почти ничего не знали бы о нескольких веках европейской истории.'),
  (401, 2, 'c_peace_of_god', 'Божий мир и церковное посредничество', 35, 4, 1, NULL, 'Церковь как посредник: запрет войны в определённые дни и защита безоружных.', 'Движение Божьего мира объявляло неприкосновенными тех, кто не воюет: крестьян, духовенство, купцов, а также мельницы, скот и посевы.

Божье перемирие шло дальше и запрещало воевать в определённые дни недели и в церковные сроки. Соблюдалось это неполно, но само притязание существенно.

Это первая известная попытка ограничить войну правилами, исходящими не от воюющих сторон, а от третьей силы. От неё тянется прямая линия к позднейшему гуманитарному праву.'),
  (402, 2, 'c_estate_hierarchy', 'Сословная иерархия', 23, 4, 1, NULL, 'Общество трёх разрядов: молящиеся, воюющие и работающие.', 'Средневековая мысль описывала общество как тело с тремя частями: одни молятся, другие защищают, третьи кормят. Каждый занят своим, и целое держится их взаимной нуждой.

Схема удобна и обосновывает порядок: неравенство объявляется не несправедливостью, а разделением обязанностей.

Действительность была сложнее схемы, и хуже всего она описывала растущее городское население, не помещавшееся ни в одну из трёх частей. Именно оттуда придёт разрушение всей конструкции.'),
  (403, 2, 'c_burgs', 'Бурги и посады', 36, 4, 1, NULL, 'Поселение ремесла и торга у замка или монастыря.', 'Города возрождаются не сами по себе, а под защитой: у стен замка, монастыря или епископской резиденции, где безопаснее и есть постоянный покупатель.

Жители такого посада — не крестьяне и не вассалы: они живут ремеслом и торгом и не вписываются в феодальные обязательства.

Отсюда неизбежный спор с сеньором о повинностях и суде, который через несколько поколений приведёт к городским вольностям и самоуправлению.'),
  (404, 2, 'c_sermon', 'Проповедь', 38, 4, 1, NULL, 'Регулярное обращение к собравшимся: единственное массовое слово эпохи.', 'Проповедь — единственный канал, достигавший всего населения еженедельно и на понятном языке, тогда как богослужение шло на латыни.

Через неё передавались не только вероучение, но и новости, распоряжения власти, объявления и правила поведения. Кафедра работала как средство оповещения.

Сила её была велика: проповедники поднимали города на крестовый поход и на покаяние, и власть внимательно следила, кому позволено проповедовать.'),
  (405, 2, 'c_two_powers', 'Священство и царство', 40, 4, 1, NULL, 'Учение о двух властях и спор о том, какая из них выше.', 'Раздвоение власти на духовную и светскую — особенность именно западного христианского мира, где церковь не слилась с государством.

Спор об инвеституре — кто назначает епископов — вылился в противостояние папства и империи, длившееся столетия и не выигранное окончательно ни одной стороной.

Историки видят в этой незавершённости источник многого: там, где две власти уравновешивают друг друга, остаётся пространство для третьих сил — городов, университетов, сословных собраний.'),
  (406, 2, 'c_estate_monarchy', 'Сословная монархия', 33, 5, 1, NULL, 'Король, правящий совместно с сословиями и опирающийся на аппарат.', 'Опираясь на города, деньги и правоведов, король постепенно берёт верх над крупными держателями: появляются постоянный суд, казна и должностные лица, назначаемые им самим.

Взамен он вынужден считаться с сословиями: для новых поборов нужно их согласие, а для согласия — собрание.

Так складывается своеобразное равновесие: сильная центральная власть, но ограниченная там, где речь идёт о деньгах. Из этого ограничения вырастет парламентаризм.'),
  (407, 2, 'c_representation', 'Сословное представительство', 33, 5, 1, NULL, 'Собрание представителей сословий, дающее согласие на налоги.', 'Правило «что касается всех, должно быть одобрено всеми» пришло из канонического права и легло в основу сословных собраний.

Английский парламент, французские штаты, испанские кортесы возникли из одной потребности: король не мог собрать новый налог, не заручившись согласием тех, кто будет платить.

Великая хартия вольностей закрепила и другую мысль — что власть связана правом и что нарушившему его можно законно противиться. Практическое значение хартии в её время было невелико, но ссылались на неё потом столетиями.'),
  (408, 2, 'c_town_law', 'Городское право', 24, 5, 1, NULL, 'Особое право города: личная свобода, свой суд и самоуправление.', 'Городское право строится на ином основании, чем феодальное: горожанин лично свободен, судится своим судом и платит установленный сбор вместо повинностей.

Правило «городской воздух делает свободным» означало, что крепостной, проживший в городе год и день без притязаний господина, становился свободным.

Образцы городского права — магдебургское, любекское — принимались десятками городов, распространяясь как готовый устав. Это редкий случай осознанного переноса правового устройства.'),
  (409, 2, 'c_orders_inquisition', 'Духовные ордена и инквизиция', 26, 5, 1, NULL, 'Монашеские ордена нового типа и розыск ереси как постоянное учреждение.', 'Нищенствующие ордена ответили на упрёк в богатстве церкви: их братья жили подаянием, проповедовали в городах и учились в университетах, а не удалялись в обитель.

Те же ордена получили и розыск ереси. Инквизиция была не столько казнью, сколько следственным учреждением с процедурой, допросом и записью — и в этом качестве повлияла на развитие розыскного процесса вообще.

Её ведение дел породило огромные архивы, по которым историки сегодня узнают о верованиях и быте простых людей больше, чем из любого другого источника.'),
  (410, 2, 'c_pilgrimage', 'Паломничество', 27, 5, 1, NULL, 'Дальнее путешествие к святыне ради обета, покаяния или исцеления.', 'Паломничество было единственным законным поводом для простолюдина отправиться за сотни километров от дома, и потому одним из главных способов, которыми люди и новости перемещались по Европе.

Вдоль путей выросло целое хозяйство: приюты, мосты, охрана, торговля значками и реликвиями, — по сути, первая туристическая инфраструктура.

Иногда паломничество назначалось судом как наказание: виновного отправляли в дальний путь вместо казни или штрафа, что было одновременно и карой, и удалением смутьяна.'),
  (411, 2, 'c_scholasticism', 'Схоластика', 28, 5, 1, NULL, 'Строгий разбор вопроса: тезис, возражения, решение — метод университета.', 'Схоластический метод устроен как состязание: ставится вопрос, приводятся доводы против, затем ответ и разбор каждого возражения по отдельности.

Возвращение Аристотеля через арабские переводы поставило задачу согласовать философию с верой, и Фома Аквинский решил её, разделив области разума и откровения.

Схоластику часто высмеивают за отвлечённые споры, но она выработала главное: привычку разбирать возражения противника всерьёз и отвечать на них по существу.'),
  (412, 2, 'c_chivalry', 'Рыцарство', 34, 5, 1, NULL, 'Сословный кодекс конного воина: честь, служение, покровительство слабым.', 'Рыцарский кодекс был попыткой обуздать сословие профессиональных бойцов, разорявших округу в мирное время: церковь и двор предписывали защищать вдов, сирот и безоружных.

Посвящение в рыцари превратилось в обряд с бдением, омовением и клятвой — воинское звание получило религиозное измерение.

Действительность далеко отставала от идеала, что признавали и современники. Но сам идеал оказался живуч: представления о чести и достойном обхождении сохранились надолго после исчезновения рыцарской конницы.'),
  (413, 2, 'c_guilds', 'Гильдии и цеха', 31, 5, 1, NULL, 'Объединения купцов и ремесленников с уставом и монополией на промысел.', 'Гильдия закрепляет за собой право торговать или заниматься ремеслом в городе и устанавливает правила: качество, цену, число работников, часы работы.

Это защищает и покупателя от обмана, и мастера от разорительного соперничества, но закрывает рынок для новых людей и тормозит новшества.

Гильдии были и политической силой: во многих городах именно они добились участия в управлении, потеснив старую патрицианскую верхушку.'),
  (414, 2, 'c_mercenaries', 'Наёмные отряды', 34, 5, 1, NULL, 'Профессиональное войско по договору и за плату.', 'Сорокадневная вассальная служба не годится для долгой войны, и правители переходят к найму: отряд служит по договору, сколько заплачено.

Наёмник дороже, но воюет круглый год, обучен и подчиняется приказу. Итальянские кондотьеры превратили это в предприятие с подрядом, сметой и репутацией.

Опасность известна с античности: неоплаченное войско кормится с земли нанимателя, а иногда и захватывает власть. Макиавелли посвятил этому едва ли не самые резкие страницы своего трактата.'),
  (415, 2, 'c_town_watch', 'Городская стража', 39, 5, 1, NULL, 'Ночной дозор, тушение пожаров и охрана ворот силами горожан.', 'Городская стража набиралась из самих горожан по очереди: обязанность караулить лежала на цехах и кварталах, а уклонение наказывалось штрафом.

Главным врагом был не разбойник, а огонь: в тесной деревянной застройке пожар уничтожал город за часы, и правила о печах, кровлях и хранении соломы были строже уголовных.

Ключи от ворот, запиравшихся на ночь, хранились у выборных лиц: контроль над входом в город был важнейшим признаком того, кому он на деле принадлежит.'),
  (416, 2, 'c_apprentices', 'Подмастерья и мастера', 32, 5, 1, NULL, 'Три ступени ремесла: ученик, подмастерье, мастер со своей мастерской.', 'Путь ремесленника был расписан: несколько лет ученичества без платы, затем годы работы подмастерьем, странствия для перенятия приёмов и, наконец, шедевр — образцовое изделие для приёма в мастера.

Это первая система профессиональной подготовки с признаваемым всеми подтверждением квалификации.

Со временем цеха стали замыкаться: звание мастера всё чаще получали сыновья и зятья мастеров, а подмастерья оставались наёмными работниками пожизненно — и это породило первые объединения работников против хозяев.'),
  (417, 2, 'c_universities', 'Университеты', 25, 5, 1, NULL, 'Самоуправляемая корпорация преподавателей и студентов со степенями.', 'Университет — не школа, а корпорация с правом самоуправления, собственным судом и привилегиями, полученными от папы или государя.

Он выдаёт степень, признаваемую повсюду, и это создаёт единое учёное пространство: магистр Парижа мог преподавать в Болонье, потому что язык обучения и программа были общими.

Учебные предметы делились на факультеты: свободные искусства как основа, затем право, медицина и богословие. Эта схема пережила сам средневековый порядок и дошла до нас.'),
  (418, 2, 'c_gothic_art', 'Готическое искусство', 29, 5, 1, NULL, 'Собор как совокупное произведение: витраж, скульптура, музыка, пространство.', 'Готический собор объединял все искусства сразу и обращался к неграмотному большинству: витражи и скульптура рассказывали священную историю тем, кто не мог её прочесть.

Строительство шло десятилетиями и было делом всего города — предметом гордости и соперничества с соседями, чей собор выше.

Тогда же в музыке появляется многоголосие и совершенствуется нотная запись, без которой сложное созвучие нельзя ни сочинить заранее, ни повторить в другом городе.'),
  (419, 2, 'c_vernacular', 'Народные языки', 30, 5, 1, NULL, 'Литература на живом языке вместо латыни.', 'Латынь оставалась языком церкви и науки, но поэзия, роман и позже деловая запись переходят на живые языки — и вместе с этим меняется круг читателей.

Данте не просто написал поэму по-итальянски, но и отстаивал в отдельном трактате право народного языка на высокую словесность.

Выбор диалекта, на котором создана значительная литература, определял будущий литературный язык страны — а с ним, много позже, и границы национального самосознания.'),
  (420, 2, 'c_papal_diplomacy', 'Папская дипломатия', 35, 5, 1, NULL, 'Папство как посредник и арбитр между государями христианского мира.', 'Папа обладал тем, чего не было ни у одного государя: признанным правом судить споры между христианскими правителями и налагать наказания духовного свойства.

Отлучение и интердикт были действенным средством: они освобождали подданных от присяги и останавливали богослужение в целой стране.

Папская курия выработала и приёмы: постоянные представители, каноническое судопроизводство, посредничество и арбитраж. Всё это перешло затем к светской дипломатии почти без изменений.'),
  (421, 2, 'c_town_liberties', 'Городские вольности', 23, 5, 1, NULL, 'Хартия города: свобода лица, право суда, торга и выбора должностных лиц.', 'Вольности не даровались сами: города их выкупали за деньги, вырывали в союзе с королём против сеньора или добивались восстанием.

Хартия закрепляла достигнутое письменно, и город хранил её как главную ценность, поскольку доказать право можно было только документом.

Так в сословном обществе появляется группа, чьи права основаны не на рождении, а на договоре. Отсюда пойдёт вся позднейшая мысль о правах, вытекающих из соглашения.'),
  (422, 2, 'c_communes', 'Городские коммуны', 36, 5, 1, NULL, 'Городское самоуправление: совет, выборные, казна и ополчение.', 'Коммуна — объединение горожан, скреплённое взаимной клятвой. Именно клятва, а не пожалование сверху, лежит в её основе, и потому власть сеньоров видела в коммунах прямой вызов.

Город получает совет, выборных должностных лиц, казну, печать, ополчение и право вести собственные дела вплоть до войны с соседями.

Итальянские коммуны дошли до полной независимости и превратились в города-государства, чья хозяйственная и художественная жизнь и породила Возрождение.'),
  (423, 2, 'c_heraldry', 'Геральдика и вестники', 38, 5, 1, NULL, 'Герб как опознавательный знак и герольд как оглашающий и удостоверяющий.', 'Закрытый шлем сделал рыцаря неузнаваемым, и опознавательный знак на щите стал необходимостью. Из этой военной надобности выросла целая знаковая система с правилами составления и наследования.

Герольд, обязанный знать гербы, превратился в должностное лицо: он оглашал вызовы, вёл списки участников турнира, опознавал павших и объявлял войну.

Гербом обзавелись не только рыцари, но и города, цехи и университеты: знак принадлежности оказался нужен всякой корпорации.'),
  (424, 2, 'c_tournaments', 'Турниры', 37, 5, 1, NULL, 'Состязание конных бойцов: обучение, зрелище и способ отличиться.', 'Ранний турнир был почти сражением: отряды сходились на большом поле, брали пленных и требовали выкуп. Гибель участников была делом обычным, и церковь неоднократно турниры запрещала.

Со временем он превратился в упорядоченное зрелище с барьером, тупым оружием, судьями и правилами — путь от побоища к спорту виден отчётливо.

Турнир был и общественным событием: местом заключения союзов, сватовства и приобретения известности, без которой воину трудно было получить хорошую службу.'),
  (425, 2, 'c_crusades', 'Крестовые походы', 40, 5, 1, NULL, 'Война, объявленная угодной вере, с обещанием отпущения грехов.', 'Идея священной войны соединила разнородные побуждения: благочестие, поиск земель младшими сыновьями, торговые расчёты итальянских городов и стремление церкви направить воинственность рыцарства вовне.

Обещание отпущения грехов участнику было решающим доводом в обществе, где страх загробного воздаяния был вполне осязаемым.

Последствия оказались далеки от замысла: разгром Константинополя крестоносцами надолго разделил христианский мир, зато встреча с восточной учёностью и торговлей заметно обогатила Европу.'),
  (426, 2, 'c_colonial_admin', 'Колониальная администрация', 33, 6, 1, NULL, 'Управление заморскими владениями через наместников и советы.', 'Заморские владения нельзя было держать прежними способами: расстояние в месяцы плавания делало любое распоряжение запоздалым, а наместника — почти самовластным.

Ответом стали советы по делам колоний в метрополии, подробнейшие инструкции и система донесений, а также разделение полномочий между наместником, судом и казной, чтобы никто не сосредоточил всю власть.

Отсюда знаменитая формула «повинуюсь, но не исполняю»: наместник признавал власть короля, но откладывал исполнение указа, не отвечающего местным условиям.'),
  (427, 2, 'c_maritime_law', 'Морское право', 24, 6, 1, NULL, 'Правила мореплавания, фрахта, аварии и добычи.', 'Морская торговля требует своих правил: кто отвечает за груз при буре, как делить убыток, если часть товара выброшена ради спасения судна, кому принадлежит найденное в море.

Своды вроде родосского и олеронского применялись судами разных стран, и в этом их особенность: право складывалось из обычая купцов, а не из воли государя.

Позднее возник главный спор эпохи: считать ли море общим для всех или его можно присвоить. Победила идея свободы морей, лёгшая в основу международного права.'),
  (428, 2, 'c_missions', 'Миссионерство', 26, 6, 1, NULL, 'Обращение народов заморских земель и споры о их правах.', 'Миссия шла вместе с завоеванием, и это ставило неудобные вопросы: можно ли крестить силой и остаются ли у обращённых права.

Спор в Вальядолиде между Лас Касасом и Сепульведой о том, являются ли жители Америки полноправными людьми, — редкий случай, когда империя всерьёз обсуждала законность собственных действий.

Миссионеры оставили и ценнейшие описания: чтобы проповедовать, надо знать язык и обычаи, и составленные ими словари и грамматики нередко единственный источник о погибших культурах.'),
  (429, 2, 'c_carnival', 'Праздники и карнавалы', 27, 6, 1, NULL, 'Дни перевёрнутого порядка: смех, ряженье и временное равенство.', 'Карнавал переворачивает всё: шут становится королём, слуга — господином, дозволено осмеивать то, что в остальные дни неприкосновенно.

Такое допущение не подрывает порядок, а укрепляет его: накопившееся недовольство выходит в узаконенной и ограниченной по времени форме.

Городской праздник был и делом цехов: каждый выставлял своё шествие и повозку, и участие в общем зрелище закрепляло место ремесла в городской жизни.'),
  (430, 2, 'c_humanism', 'Гуманизм', 28, 6, 1, NULL, 'Обращение к античным образцам и к человеку как мере вещей.', 'Гуманисты вернулись к древним текстам напрямую, минуя средневековые толкования, и выработали приёмы проверки подлинности документа — по сути, филологическую критику.

Разоблачение поддельного Константинова дара показало силу метода: подделку уличили по языку, невозможному в приписываемое время.

Гуманизм сместил и предмет внимания: главным становится земная жизнь человека, его достоинство, образование и способности. Это не отрицание веры, но иное распределение интереса.'),
  (431, 2, 'c_royal_navy', 'Регулярный флот', 34, 6, 1, NULL, 'Постоянный государственный флот с верфями, уставом и офицерами.', 'Прежде флот собирали из нанятых торговых судов на время войны. Постоянный флот — иное дело: корабли строятся специально для боя и содержатся всегда.

Это потребовало верфей, складов, заготовки леса на десятилетия вперёд и, главное, постоянных расходов, ради которых пришлось перестраивать казну.

Появился и морской офицер как профессия со своей выучкой, уставом и чинами — вместе с представлением о том, что командование кораблём есть государственная служба, а не предприятие капитана.'),
  (432, 2, 'c_mercantilism', 'Меркантилизм', 31, 6, 1, NULL, 'Хозяйственная политика ради накопления благородных металлов и вывоза.', 'Меркантилизм исходил из того, что богатство страны измеряется запасом золота и серебра, а значит, вывозить нужно больше, чем ввозить.

Отсюда покровительственные пошлины, поощрение производства, монополии торговых компаний и колонии как источник сырья и закрытый рынок сбыта.

Позднейшая критика указала на главную ошибку: торговля не игра, где выигрыш одного есть проигрыш другого. Но заложенная тогда связь хозяйства с государственной мощью пережила саму теорию.'),
  (433, 2, 'c_plantation_slavery', 'Плантационное рабство', 32, 6, 1, NULL, 'Массовый принудительный труд на заморских плантациях.', 'Плантационное рабство отличалось от прежних форм масштабом и безысходностью: работник был собственностью пожизненно и наследственно, а труд на сахаре и хлопке изнашивал человека за считанные годы.

Трансатлантическая торговля людьми переместила через океан миллионы, и её треугольник — товары в Африку, люди в Америку, сахар и хлопок в Европу — стал основой целых отраслей и состояний.

Для оправдания этого порядка была выстроена расовая доктрина, которой прежде не существовало: обоснование понадобилось именно потому, что практика противоречила уже провозглашённым представлениям о человеке.'),
  (434, 2, 'c_naval_schools', 'Мореходные школы', 25, 6, 1, NULL, 'Обучение навигации, счёту и картографии как государственная задача.', 'Дальние плавания потребовали штурманов, умеющих считать и работать с таблицами. Португальская и испанская короны завели школы и должность главного кормчего, отвечавшего за подготовку и за карты.

Это первый случай, когда государство целенаправленно готовит специалистов ради хозяйственной задачи, а не для двора или церкви.

Обучение опиралось на печатные руководства с таблицами склонения и приёмами счисления — учебник в современном смысле появляется именно здесь.'),
  (435, 2, 'c_court_music', 'Придворная музыка', 29, 6, 1, NULL, 'Капелла, многоголосие и музыка как принадлежность двора.', 'Двор содержит капеллу — постоянный коллектив певчих и музыкантов, — и музыка становится частью придворного обихода наравне с архитектурой и живописью.

Многоголосие достигает необычайной сложности, а нотопечатание позволяет распространять сочинения, и композитор впервые получает известность за пределами места службы.

Соперничество дворов в блеске капелл двигало музыку не хуже любого вдохновения: хороших музыкантов переманивали, как позже переманивали инженеров.'),
  (436, 2, 'c_printed_book', 'Печатная книга', 30, 6, 1, NULL, 'Тираж, титульный лист, нумерация страниц и книжный рынок.', 'Печать создала не только тираж, но и облик книги: титульный лист, оглавление, нумерацию страниц, указатель. Всё это нужно, чтобы в книге можно было искать, а не только читать подряд.

Появился книжный рынок, а с ним издатель, рассчитывающий спрос, и понятие тиража как коммерческого риска.

Власти ответили быстро: возникли цензура, привилегия на издание и списки запрещённых книг. Печать сразу была осознана как сила, требующая надзора.'),
  (437, 2, 'c_treaty_division', 'Раздел мира по договору', 35, 6, 1, NULL, 'Разграничение заморских владений между державами по линии на карте.', 'Тордесильясский договор провёл по океану условную черту, разделив ещё не открытые земли между Португалией и Испанией при посредничестве папы.

Замечательна сама мысль: земли, о которых ничего не известно, распределяются заранее, а мнение их жителей не рассматривается вовсе.

Другие державы договор не признали, и он стал причиной долгих споров. Но образец был задан, и разграничение сфер влияния линией на карте будет повторяться вплоть до раздела Африки четыре столетия спустя.'),
  (438, 2, 'c_colonial_society', 'Колониальное общество', 23, 6, 1, NULL, 'Иерархия по происхождению и месту рождения в заморских владениях.', 'В колониях сложилась иерархия, которой не было в метрополии: положение определялось происхождением и долей крови, расписанной в подробнейших разрядах.

Даже среди европейцев проходила граница: рождённые в колонии уступали в правах приехавшим из метрополии, и эта обида много позже станет одной из движущих сил борьбы за независимость.

Так возникла общественная система, где место человека задано не сословием, как в Европе, а происхождением, — и её последствия переживут сами колониальные империи.'),
  (439, 2, 'c_port_cities', 'Портовые города', 36, 6, 1, NULL, 'Город, живущий морской торговлей: биржа, склады, разноязычное население.', 'Портовый город устроен иначе прежнего: он живёт не своей округой, а обменом с далёкими странами, и его благополучие зависит от событий за океаном.

Здесь появляются биржа, страховщики, маклеры, склады и постоянные общины иноземных купцов со своими молитвенными домами.

Разноязычие и веротерпимость были не идеалом, а необходимостью: города, изгонявшие иноверцев, теряли торговлю в пользу тех, кто их принимал, и это отчётливо видно на судьбе Амстердама.'),
  (440, 2, 'c_pamphlets', 'Летучие листки', 38, 6, 1, NULL, 'Дешёвая печатная новость: известие, памфлет, гравюра на злобу дня.', 'Летучий листок в несколько страниц печатался за день и стоил гроши. Он разносил известия о сражениях, чудесах, казнях и стихийных бедствиях.

Реформация первой воспользовалась этим средством в полную силу: тезисы и памфлеты разошлись по германским землям за недели, чего не бывало ни с одним прежним спором.

Гравюра делала листок понятным и неграмотным, и злободневная карикатура появляется именно тогда — вместе с ней рождается борьба за общественное мнение печатным словом.'),
  (441, 2, 'c_privateering', 'Каперство и пиратство', 39, 6, 1, NULL, 'Узаконенный морской разбой по государственной грамоте.', 'Каперское свидетельство превращало частное судно в законного захватчика неприятельских кораблей: государство получало ущерб противнику без расходов, капитан — долю добычи.

Грань с обычным разбоем была тонкой и зависела от того, признаёт ли грамоту противная сторона, а вчерашний капер после заключения мира легко становился пиратом.

Отменили каперство лишь в середине XIX века, когда государства окончательно закрепили за собой исключительное право на применение силы на море.'),
  (442, 2, 'c_fencing', 'Фехтование', 37, 6, 1, NULL, 'Школа владения шпагой: правила поединка и обучение по трактату.', 'С исчезновением доспеха переменилось и оружие: лёгкая шпага требовала не силы, а точности и работы ног. Появились школы с системой приёмов и печатными руководствами.

Дуэль стала бедствием дворянства: от неё гибло больше людей, чем от иных войн, и власти запрещали её раз за разом без особого успеха.

Постепенно поединок превращался в состязание: защитное снаряжение, затупленный клинок, судья и правила присуждения удара — так из смертельного спора вырос нынешний спорт.'),
  (443, 2, 'c_expansionism', 'Экспансионизм', 40, 6, 1, NULL, 'Расширение владений как естественное право и долг державы.', 'Идея, что сильная держава должна расширяться, получила обоснование сразу с нескольких сторон: обращение язычников, польза торговли и слава государя.

Правовым прикрытием служила доктрина ничейной земли: территории, не принадлежащие признанному христианскому государю, объявлялись открытыми для занятия.

Возражения звучали и тогда: правоведы Саламанкской школы утверждали, что народы заморских земель — законные хозяева своих владений, и одними из первых заговорили о правах, принадлежащих человеку по природе.'),
  (444, 2, 'c_absolutism', 'Абсолютная монархия', 33, 7, 1, NULL, 'Государь, не связанный сословиями: единая казна, армия и чиновничество.', 'Абсолютизм вырос из потребности содержать постоянную армию и артиллерию: расходы требовали налогов, которые собирали, минуя согласие сословий.

Опорой стали чиновники недворянского происхождения, обязанные должностью лично государю, и постоянное войско, подчинённое ему же.

Формула «государство — это я» выражает суть, но не действительность: даже сильнейший монарх был связан обычаем, привилегиями провинций и сопротивлением судов, и власть его никогда не была такой полной, как гласила теория.'),
  (445, 2, 'c_natural_law', 'Естественное право', 24, 7, 1, NULL, 'Права, присущие человеку по природе, а не дарованные властью.', 'Правоведы Саламанки, а затем Гроций утверждали, что существуют правила, обязательные для всех народов и государей и выводимые из самой природы человека.

Гроций пошёл дальше, заявив, что эти правила сохраняли бы силу, даже если предположить — что нечестиво, — что Бога нет. Право получило основание, независимое от вероисповедания, а значит, применимое между враждующими конфессиями.

Отсюда пойдёт и учение о неотчуждаемых правах, и мысль о договоре как основании власти — весь строй политической мысли следующих двух столетий.'),
  (446, 2, 'c_patent', 'Патентная привилегия', 24, 7, 1, NULL, 'Исключительное право изобретателя на срок в обмен на раскрытие способа.', 'Венецианский закон 1474 года первым установил общий порядок: изобретатель заявляет новое устройство и получает защиту на срок, а не выпрашивает милость у государя.

Замысел взаимовыгоден: общество получает описание способа, изобретатель — временную монополию вместо необходимости хранить секрет.

Английский статут о монополиях позже закрепил тот же принцип, отменив прочие королевские монополии и оставив только патент на изобретение. Из этого различия выросло всё патентное право.'),
  (447, 2, 'c_reformation', 'Реформация', 26, 7, 1, NULL, 'Разрыв с папством, Писание на родном языке и спасение верой.', 'Спор начался с частного вопроса об индульгенциях, но затронул основание: чем человек спасается и кто вправе толковать Писание.

Печать сыграла решающую роль: тезисы и памфлеты разошлись по германским землям за недели, а Библия на родном языке сделала толкование делом каждого читателя.

Последствия вышли далеко за веру. Раскол дал государям повод присвоить церковные земли, породил религиозные войны на полтора столетия и в конце концов вынудил Европу искать основания порядка, не зависящие от вероисповедания.'),
  (448, 2, 'c_counter_reformation', 'Контрреформация', 26, 7, 1, NULL, 'Ответ католической церкви: собор, дисциплина, орден, школа.', 'Тридентский собор не пошёл на уступки в вероучении, но взялся за порядок: обязал епископов жить в своих епархиях, завёл семинарии и упорядочил обряд.

Иезуиты сделали ставку на образование и создали сеть коллегий, дававших лучшее в Европе среднее образование, — расчёт был на воспитание, а не на принуждение.

Одновременно усилились цензура и индекс запрещённых книг. Соревнование двух конфессий за души обернулось общим для обеих стороной ростом школ, проповеди и заботы о нравах.'),
  (449, 2, 'c_court_etiquette', 'Придворный этикет', 27, 7, 1, NULL, 'Церемониал двора: место, очерёдность и обхождение как инструмент власти.', 'Этикет — не украшение, а средство управления знатью: подробнейший порядок церемоний определял, кто где стоит, кто первым говорит и кому дозволено подать государю сорочку.

Версаль довёл это до совершенства: удерживая знать при дворе борьбой за мелкие почести, король лишал её и досуга, и повода заниматься делами в своих владениях.

Стоило это дорого, но обходилось дешевле войны с мятежными вельможами — расчёт, который оправдал себя вполне.'),
  (450, 2, 'c_rationalism', 'Рационализм', 28, 7, 1, NULL, 'Разум как источник достоверного знания; сомнение как метод.', 'Декарт начал с полного сомнения: отбросить всё, в чём можно усомниться, и посмотреть, что устоит. Устояло само мышление — отсюда исходное положение его философии.

Метод предполагал разложение сложного на простое, порядок в рассуждении и полноту перечисления, и был сознательно построен по образцу математики.

Эмпиризм возражал, что источник знания — опыт, а не врождённые идеи. Из спора двух направлений вырастет вся европейская философия Нового времени.'),
  (451, 2, 'c_standing_army', 'Постоянные армии', 34, 7, 1, NULL, 'Войско на постоянном содержании: устав, форма, чины, казармы.', 'Постоянная армия решала беду наёмных отрядов, разбегавшихся без платы и грабивших мирное население. Полк становится учреждением с числом, знаменем и историей.

Появились единая форма, уставные приёмы, строевая подготовка, чины и выслуга. Казарма увела солдата из домов горожан, где его прежде размещали на постой.

Содержание такой армии стало главной статьёй расходов и главным двигателем перестройки казны: чтобы платить войску, государству пришлось научиться собирать налоги и брать в долг.'),
  (452, 2, 'c_secret_police', 'Тайная полиция', 39, 7, 1, NULL, 'Политический сыск: осведомители, перлюстрация, дела о государственной измене.', 'Постоянная служба, следящая за настроениями подданных, — новшество Нового времени. До неё сыск был случайным и поручался кому придётся.

Средствами были осведомители в кабаках и салонах, вскрытие писем в так называемых чёрных кабинетах и донесения из провинции.

Сведения шли прямо государю в обход обычных ведомств, и это обеспечивало быстроту, но и отрывало власть от действительности: доносили нередко то, что желали услышать.'),
  (453, 2, 'c_banking_houses', 'Банковские дома', 31, 7, 1, NULL, 'Семейные банки, кредитующие государей и торговлю, и первый государственный долг.', 'Банкирские дома Фуггеров, Медичи и их последователей кредитовали государей под залог доходов, рудников и таможен, а взамен получали монополии и влияние.

Кредит короне был выгоден и опасен: отказ платить разорял кредитора, а привлечь государя к ответу было некому. Испанская корона объявляла себя несостоятельной неоднократно.

Ответом стал государственный долг нового типа: заём не у лица, а у множества держателей бумаг, обеспеченный не обещанием монарха, а установленным налогом.'),
  (454, 2, 'c_artist_workshops', 'Мастерские художников', 32, 7, 1, NULL, 'Боттега с учениками, договор с заказчиком и смета на работу.', 'Художник Возрождения — ремесленник с мастерской: он берёт заказ по договору, где оговорены сроки, размеры, стоимость красок и доля работы, выполняемая лично мастером.

Ученики растирали краски, готовили доски и писали второстепенные части; разделение труда в мастерской было вполне производственным.

Именно в эту эпоху ремесленник начинает превращаться в художника в нынешнем смысле: появляется представление о замысле как о личном достоянии автора, а с ним и слава, переживающая мастера.'),
  (455, 2, 'c_academies', 'Академии', 25, 7, 1, NULL, 'Учёные и художественные общества вне университета.', 'Университет был связан богословской традицией и уставом, поэтому новое знание искало иных мест: академии создавались при дворах и по частной подписке.

Они завели то, чего не знал университет: демонстрацию опыта на заседании, печатный журнал, переписку с иностранными учёными и премию за решение задачи.

Художественные академии сделали то же для искусства: они установили программу обучения, конкурс и выставку, задав образец художественного образования на столетия вперёд.'),
  (456, 2, 'c_renaissance_art', 'Ренессансная живопись', 29, 7, 1, NULL, 'Перспектива, анатомия и авторство: изображение мира таким, каким его видит глаз.', 'Открытие линейной перспективы дало правило построения пространства на плоскости, а изучение анатомии — правдоподобие фигуры. Живопись стала занятием, требующим знания, а не только навыка.

Художник впервые подписывает работы и добивается признания как автор замысла; жизнеописания живописцев Вазари — первая история искусства как истории людей.

Меценатство стало политикой: заказ росписи или собора был способом городов и родов утверждать своё положение не менее действенным, чем война.'),
  (457, 2, 'c_literary_language', 'Литературный язык', 30, 7, 1, NULL, 'Норма, словарь и грамматика: язык, единый для страны.', 'Печать потребовала выбрать написание и грамматику: набор не терпит разнобоя, и издатель невольно становится законодателем нормы.

Перевод Библии Лютером сделал для немецкого языка то же, что печать для прочих: задал общий образец, понятный от Баварии до Саксонии.

Позже за дело взялись академии, издавшие словари и грамматики. Литературный язык оказался и средством единства страны, и средством вытеснения местных наречий.'),
  (458, 2, 'c_resident_embassies', 'Постоянные посольства', 35, 7, 1, NULL, 'Посол, живущий при чужом дворе постоянно, с неприкосновенностью и шифром.', 'Итальянские государства первыми завели постоянных послов: непрерывное наблюдение за соседом оказалось ценнее редких торжественных посольств.

Появились регулярные донесения, шифрованная переписка и, разумеется, разведка — посол собирал сведения не только открыто.

Сложилось и посольское право: неприкосновенность посла и его дома, изъятие из местной юрисдикции. Из этой практики вырастет вся современная дипломатическая служба.'),
  (459, 2, 'c_bourgeoisie', 'Городская буржуазия', 23, 7, 1, NULL, 'Состоятельные горожане: доход от дела, а не от земли и рождения.', 'Буржуазия не помещалась в сословную схему: она богата, но не благородна, свободна, но не привилегированна, и её положение определяется делом, а не происхождением.

Отсюда постоянное стремление купить дворянство или должность, дающую его, — и постоянное раздражение старой знати этим.

Богатство горожан стало опорой государей в борьбе с крупными держателями земли, но оно же со временем породило требование политических прав по имуществу, а не по рождению.'),
  (460, 2, 'c_regular_planning', 'Регулярная планировка', 36, 7, 1, NULL, 'Прямые улицы, площади и парадные перспективы вместо стихийной застройки.', 'Регулярный город строится по замыслу: прямые проспекты, симметричные площади, единая высота застройки и перспектива, замкнутая заметным зданием.

Такая планировка выражала порядок и власть, но имела и прямое назначение: широкая прямая улица удобна для проезда артиллерии и невыгодна для баррикад.

Тогда же появились нумерация домов, названия улиц и первые предписания о ширине проездов и материале кровель — начало городского регулирования застройки.'),
  (461, 2, 'c_newspapers', 'Первые газеты', 38, 7, 1, NULL, 'Периодическое издание с новостями по расписанию.', 'Газета отличается от летучего листка правильностью выхода: читатель знает, что в определённый день получит свежие известия, и приобретает привычку.

Первые газеты выросли из купеческой переписки: сведения о ценах, курсах, приходе судов и войне были нужны торговле в первую очередь.

Регулярность создала новое ощущение времени: события выстроились в поток, за которым можно следить, и общество впервые получило общий календарь новостей.'),
  (462, 2, 'c_utopias', 'Утопии', 40, 7, 1, NULL, 'Описание совершенного устройства общества как способ критики нынешнего.', 'Книга Томаса Мора дала жанру имя и приём: рассказ о далёком острове с иным устройством позволял обсуждать пороки собственной страны, не навлекая обвинения.

Утопии отличаются рационализмом: общество в них устроено по разумному плану, а не выросло из обычая, — и это само по себе новая мысль.

Отсюда двойственное наследие: утопия дала образец продуманного общественного переустройства и вместе с тем соблазн переделать людей по чертежу, что XX век покажет во всей полноте.'),
  (463, 2, 'c_state_apparatus', 'Государственный аппарат', 33, 8, 1, NULL, 'Ведомства, штат, отчётность и разделение дел между службами.', 'Управление перестаёт быть личным поручением и становится ведомством: у него есть название, штат, круг дел, бюджет и порядок отчёта.

Появляются служебная лестница, жалованье вместо кормления, пенсия и экзамен при поступлении. Чиновник становится профессией.

Государство начинает знать о себе: перепись, кадастр, статистика доходов и население по возрастам. Это одновременно и способ лучше собирать налоги, и первый шаг к политике, опирающейся на сведения, а не на предположение.'),
  (464, 2, 'c_popular_sovereignty', 'Народный суверенитет', 33, 8, 1, NULL, 'Власть, происходящая от согласия управляемых, а не от рождения.', 'Учение об общественном договоре переворачивает основание власти: она не дана свыше, а учреждена людьми ради общей пользы и потому подотчётна.

Из этого следует и право сопротивления: правительство, нарушившее условия, теряет законность. Локк сказал это прямо, и американская декларация повторила почти дословно.

Оставался трудный вопрос, кто такой «народ» и как узнать его волю. Ответы на него будут расходиться до противоположности — от парламентского представительства до утверждения, что волю народа выражает вождь.'),
  (465, 2, 'c_constitutional_law', 'Конституционное право', 24, 8, 1, NULL, 'Основной закон, разделение властей и ограничение государства правом.', 'Замысел прост: власть надо разделить так, чтобы одна часть сдерживала другую, — тогда произвол становится затруднительным независимо от нравов правителей.

Писаная конституция закрепляет устройство и права в документе, изменить который труднее, чем обычный закон, а суд получает возможность проверять законы на соответствие ему.

Английский путь пошёл иначе — без единого документа, через обычай, прецедент и отдельные акты, — и это показывает, что дело не в форме, а в действительном признании ограничений.'),
  (466, 2, 'c_deism', 'Деизм и веротерпимость', 26, 8, 1, NULL, 'Разумная вера без откровения и признание права на иное исповедание.', 'После полутора веков религиозных войн стало ясно, что принудить к единоверию не удаётся ни одной стороне, и терпимость приняли сперва по необходимости, а затем как принцип.

Деизм признавал творца, но отвергал чудо и откровение, оставляя религии нравственное содержание. Многие деятели эпохи придерживались именно такого взгляда.

Практическим итогом стало отделение гражданских прав от вероисповедания: постепенно снимались ограничения для иноверцев, и государство переставало быть орудием одной церкви.'),
  (467, 2, 'c_salons', 'Салоны и ложи', 27, 8, 1, NULL, 'Частные собрания для беседы: пространство обсуждения вне двора и церкви.', 'Салон был устроен необычно для сословного общества: за одним столом сходились аристократ, литератор и учёный, и разговор шёл по правилам беседы, а не старшинства.

Хозяйками салонов чаще были женщины, и это дало им влияние на умственную жизнь, которого они были лишены во всех учреждениях эпохи.

Масонские ложи добавили к этому обряд, тайну и сеть, связывавшую города и страны. Историки видят в салонах и ложах зарождение того, что назовут общественным мнением.'),
  (468, 2, 'c_enlightenment_phil', 'Философия Просвещения', 28, 8, 1, NULL, 'Разум против предрассудка: критика власти, церкви и обычая.', 'Просвещение исходило из того, что разум способен разобрать любое установление и спросить, разумно ли оно и кому служит. Ничто не изымалось из проверки.

Отсюда критика пыток и произвольного заключения, требование соразмерности наказания и первое основательное возражение против рабства.

Кант выразил суть короче всех: просвещение есть выход человека из состояния несовершеннолетия, в котором он находится по собственной вине, — то есть решимость пользоваться собственным умом.'),
  (469, 2, 'c_conscription', 'Воинская повинность', 34, 8, 1, NULL, 'Обязанность граждан служить: армия из всего населения.', 'Массовый призыв 1793 года дал революционной Франции армию, какой не имел ни один монарх, и переменил соотношение сил в Европе разом.

Повинность опирается на новое понятие: если государство принадлежит гражданам, то и защищать его — их обязанность, а не наёмное дело.

Последствия оказались долгими: армия стала школой нации, где призывники из разных местностей учились общему языку и привыкали считать себя одним народом.'),
  (470, 2, 'c_police', 'Регулярная полиция', 39, 8, 1, NULL, 'Постоянная служба охраны порядка с уставом, участками и учётом.', 'Полиция Нового времени отличалась от стражи назначением: не только ловить преступника, но и предупреждать беспорядок, надзирая за улицами, рынками, трактирами и приезжими.

Появились участки, дежурства, регистрация происшествий и первые сыскные приёмы — приметы, картотека, опрос свидетелей по правилам.

Возник и спор, не окончившийся до сих пор: где проходит грань между поддержанием порядка и надзором за жизнью подданных, и кто эту грань устанавливает.'),
  (471, 2, 'c_political_economy', 'Политическая экономия', 31, 8, 1, NULL, 'Хозяйство как предмет науки: труд, стоимость, рынок, разделение занятий.', 'Смит объяснил богатство не запасом золота, а трудом и его разделением, и показал, что своекорыстный расчёт участников обмена может вести к общей пользе.

Отсюда возражение меркантилизму: свободная торговля выгодна обеим сторонам, а запреты и монополии обедняют страну, которая их вводит.

Смит вовсе не был проповедником безграничного своекорыстия: он писал о необходимости правосудия, образования и об опасности сговора торговцев против покупателей.'),
  (472, 2, 'c_wage_labor', 'Наёмный труд', 32, 8, 1, NULL, 'Работа по договору за плату: свобода нанимателя и работника расторгнуть связь.', 'Наёмный труд заменяет и крепостную повинность, и цеховую зависимость: стороны свободны и связаны только договором.

Формальное равенство сторон скрывает неравенство положения: работник, у которого нет запаса, вынужден соглашаться на предложенные условия немедленно.

Законы долго были на стороне нанимателя: сговор работников о плате запрещался как заговор, тогда как сговор хозяев преследовался редко. Именно из этого неравенства вырастет рабочее движение.'),
  (473, 2, 'c_secular_school', 'Светская школа', 25, 8, 1, NULL, 'Обучение, не подчинённое церкви: программа, учитель, расписание.', 'Мысль о том, что образование — дело государства, а не церкви, впервые высказывается именно тогда: грамотный подданный полезен казне, армии и хозяйству.

Возникают программа, деление на классы по возрасту, расписание, учебник и подготовка учителей — привычный нам школьный порядок.

Обязательность вводили постепенно и с сопротивлением: крестьянская семья теряла рабочие руки, и школа воспринималась как повинность, а не как благо.'),
  (474, 2, 'c_classicism', 'Классицизм', 29, 8, 1, NULL, 'Строгая форма и античный образец: ясность, соразмерность, правило.', 'Классицизм ставил образец выше вдохновения: правила трёх единств в драме, ордер в архитектуре, иерархия жанров в живописи.

За этим стояло убеждение, что прекрасное подчиняется правилам, которые можно узнать и которым можно научить, — вполне в духе века разума.

Стиль оказался удобен государству: величие, порядок и отсылка к Риму хорошо служили и монархии, и позже республике, что видно по облику правительственных зданий доныне.'),
  (475, 2, 'c_encyclopedias', 'Энциклопедии', 30, 8, 1, NULL, 'Свод знаний по алфавиту: доступ к сведениям без учителя.', '«Энциклопедия» Дидро и Даламбера была не только сводом сведений, но и предприятием с замыслом: подать знание так, чтобы читатель судил сам.

Статьи о ремёслах с подробными гравюрами впервые описали производственные приёмы, которые прежде хранились как цеховая тайна.

Алфавитный порядок и перекрёстные ссылки — техническое решение с последствиями: знание перестаёт быть последовательным изложением и становится сетью, по которой читатель движется своим путём.'),
  (476, 2, 'c_international_law', 'Международное право', 35, 8, 1, NULL, 'Правила между государствами: суверенитет, договор, законы войны.', 'Вестфальский мир закрепил основания порядка: государство суверенно в своих пределах, и вероисповедание в нём — не повод для вмешательства соседей.

Правоведы разработали учение о справедливой войне, о нейтралитете, о правах пленных и о нерушимости договоров.

Слабость очевидна и признавалась сразу: у этого права нет силы принуждения. Оно держится на взаимности и на том, что нарушителю будет труднее договариваться в следующий раз.'),
  (477, 2, 'c_human_rights', 'Права человека', 23, 8, 1, NULL, 'Провозглашение прав, принадлежащих каждому от рождения.', 'Декларации американская и французская объявили права не дарованными, а принадлежащими человеку по природе, и потому не подлежащими отмене.

Провозглашение сразу разошлось с действительностью: рабство сохранялось, женщины прав не получили, имущественный ценз ограничивал участие. Олимпия де Гуж написала декларацию прав женщины и была казнена.

Но сам текст стал орудием: всякий исключённый мог указать на противоречие между провозглашённым и существующим, и вся дальнейшая борьба за расширение прав велась этим доводом.'),
  (478, 2, 'c_city_improvement', 'Городское благоустройство', 36, 8, 1, NULL, 'Мостовая, освещение, вывоз нечистот и надзор за застройкой.', 'Город впервые становится предметом сознательного попечения: власти берутся за мощение, уличные фонари, уборку, водоразбор и правила застройки.

Уличное освещение имело и прямое полицейское назначение: освещённая улица безопаснее, и городские власти прямо ссылались на это, вводя фонарный сбор.

Появились и первые общественные пространства нового типа — бульвары, набережные и публичные сады, открытые для всех сословий, что само по себе было новшеством.'),
  (479, 2, 'c_periodicals', 'Периодическая печать', 38, 8, 1, NULL, 'Журналы, обозрения и рост читающей публики.', 'Помимо газет появляются журналы: нравоучительные, литературные, учёные. Они не столько сообщают новости, сколько обсуждают и оценивают.

Читателей объединяют кофейни и читальни, где издания выписывают вскладчину: печатное слово читают сообща и тут же обсуждают.

Так складывается общественное мнение как самостоятельная сила: правительства начинают с ним считаться, заводить свои издания и оплачивать нужные статьи.'),
  (480, 2, 'c_liberalism', 'Либерализм', 40, 8, 1, NULL, 'Свобода лица, собственность, ограниченная власть и равенство перед законом.', 'Либерализм соединил несколько требований: личная свобода, неприкосновенность собственности, ограничение власти законом и равенство перед судом.

Он был прежде всего учением о пределах: не о том, кто правит, а о том, чего правительство делать не вправе независимо от того, кем оно избрано.

Ранний либерализм не был демократическим и допускал имущественный ценз, полагая собственность условием независимого суждения. Соединение с всеобщим избирательным правом произойдёт лишь столетие спустя.'),
  (481, 2, 'c_clubs', 'Клубы и состязания', 37, 8, 1, NULL, 'Объединения по интересам и первые правила спортивных игр.', 'Клуб — новая форма общения: люди сходятся не по сословию и не по приходу, а по общему занятию, будь то политика, крикет или скачки.

Ради состязаний между клубами понадобились единые правила, и их начинают записывать и печатать — момент рождения спорта в нынешнем смысле.

Скачки и бокс собирали тысячи зрителей и огромные ставки, что сразу поставило вопросы о честности состязания и о надзоре за ним.'),
  (482, 2, 'c_nation_state', 'Национальное государство', 33, 9, 1, NULL, 'Государство, отождествляющее себя с народом: единый язык, школа, армия, символы.', 'Прежде подданство определялось верностью государю, теперь — принадлежностью к нации. Государство берётся эту нацию создавать: единый язык, единая школа, единая воинская повинность, флаг и гимн.

Средства действовали: массовая школа и призывная армия за два-три поколения превращали население, говорившее на десятках наречий, в народ с общим языком и историей.

Обратной стороной стало давление на тех, кто в схему не помещался: местные языки вытеснялись, а меньшинства оказывались подозрительными по самому своему существованию.'),
  (483, 2, 'c_factory_law', 'Фабричное законодательство', 24, 9, 1, NULL, 'Ограничение детского труда, длины рабочего дня и надзор за условиями.', 'Первые фабричные законы касались детей: они ограничивали возраст и часы работы и требовали хоть какого-то обучения.

Решающим оказалось не само правило, а фабричная инспекция: закон без проверяющего оставался словами, и именно введение инспекторов с правом входа на предприятие сдвинуло дело.

Отчёты инспекторов стали первым достоверным описанием положения рабочих и источником, которым пользовались все — от парламентских комиссий до критиков капитализма.'),
  (484, 2, 'c_secularization', 'Секуляризация', 26, 9, 1, NULL, 'Отделение государства от церкви и передача её земель и школ в мирские руки.', 'Секуляризация шла двумя путями: изъятием церковного имущества казной и постепенным переходом записи актов гражданского состояния, брака, школы и кладбищ в ведение государства.

Это лишило церковь не столько веры, сколько повседневных полномочий, которыми она распоряжалась тысячу лет.

Общество не стало от этого неверующим: религия перешла в область личного выбора, а спор о её месте в школе и общественной жизни остаётся открытым по сей день.'),
  (485, 2, 'c_civic_festivals', 'Гражданские праздники', 27, 9, 1, NULL, 'Обряды нации: годовщины, парады, памятники, погребение героев.', 'Революция обнаружила, что общество не может обойтись без обрядов, и стала создавать их сознательно: праздники в честь событий, шествия, гимны и новый календарь.

Государство берёт на себя то, что делала церковь: назначает дни памяти, устраивает погребение великих людей и возводит памятники, объясняющие, кем следует гордиться.

Историки называют это изобретением традиции: обряды, кажущиеся древними, нередко созданы недавно и намеренно — ради того, чтобы нация ощутила себя древней.'),
  (486, 2, 'c_positivism', 'Позитивизм', 28, 9, 1, NULL, 'Достоверно лишь то, что опирается на наблюдение и проверяемо опытом.', 'Позитивизм объявил метафизические вопросы неразрешимыми и предложил заниматься тем, что доступно наблюдению и проверке, — образцом служило естествознание.

Конт распространил это на общество, введя само слово «социология» и намерение изучать общественные явления так же, как природные.

Из этого выросли и статистика общественных явлений, и уверенность эпохи, что наука способна решить и общественные задачи, — уверенность, которую XX век сильно поколеблет.'),
  (487, 2, 'c_mass_army', 'Массовая армия', 34, 9, 1, NULL, 'Армия из призванного населения с запасом обученных и мобилизацией.', 'Массовая армия строится на запасе: отслуживший срок уходит домой, но числится в резерве и может быть призван по расписанию мобилизации.

Это требует учёта населения, складов снаряжения на сотни тысяч человек и железнодорожного расписания перевозок — задача, решаемая только развитым государством.

Генеральный штаб появляется именно как учреждение, разрабатывающее эти планы заранее. Война перестаёт быть искусством полководца и становится делом предварительного расчёта.'),
  (488, 2, 'c_gendarmerie', 'Жандармерия', 39, 9, 1, NULL, 'Военизированная охрана порядка в сельской местности и на путях сообщения.', 'Городская полиция не годилась для деревни и дорог, где расстояния велики, а население разбросано. Жандармерия соединила военную организацию с полицейскими задачами.

Жандармские посты вдоль дорог и в местечках впервые обеспечили присутствие государства там, где прежде оно появлялось лишь при сборе налога.

Она же занималась политическим надзором, и в некоторых странах именно жандармерия стала главным орудием наблюдения за настроениями подданных.'),
  (489, 2, 'c_capitalism', 'Капитализм', 31, 9, 1, NULL, 'Хозяйство на частном капитале, наёмном труде и вложении ради прибыли.', 'Отличительная черта капитализма не торговля и не богатство, известные всем эпохам, а постоянное вложение прибыли обратно в дело ради расширения производства.

Это создало невиданный прежде рост: за столетие выпуск продукции вырос сильнее, чем за всю предшествующую историю.

Вместе с ростом пришли и свойственные только ему беды: кризисы перепроизводства, когда товаров слишком много, а покупателей нет, — явление, немыслимое в хозяйстве прежних эпох, страдавшем от недостатка.'),
  (490, 2, 'c_luddism', 'Луддизм и рабочие волнения', 32, 9, 1, NULL, 'Сопротивление вытеснению труда машиной: разрушение станков и стачки.', 'Луддиты ломали не машины вообще, а те, что позволяли обойтись без квалифицированных работников и сбить плату. Это был не бунт против техники, а спор о её применении.

Ответ был суровым: разрушение станка сделали преступлением, караемым смертью, а против рабочих направляли войска.

Само явление обнаружило вопрос, не решённый и поныне: выигрыш от новой техники достаётся обществу в целом, а издержки ложатся на определённые группы, и распределение того и другого — задача политическая, а не техническая.'),
  (491, 2, 'c_sunday_schools', 'Воскресные и фабричные школы', 25, 9, 1, NULL, 'Начальная грамота для работающих детей и взрослых.', 'Дети работали шесть дней в неделю, и единственным свободным временем оставалось воскресенье. Воскресные школы учили чтению и счёту именно в этот день.

Фабричные законы обязали хозяев отпускать малолетних работников на несколько часов занятий, и обучение впервые стало обязанностью работодателя.

Рабочие и сами создавали институты взаимного обучения и читальни: спрос на грамоту снизу был велик, поскольку она открывала доступ и к лучшей работе, и к печатному слову.'),
  (492, 2, 'c_romanticism', 'Романтизм', 29, 9, 1, NULL, 'Чувство, воображение и народная старина против правил и рассудка.', 'Романтизм возразил классицизму по существу: правила не создают искусства, его создаёт воображение, а мерилом становится подлинность чувства.

Отсюда интерес к средневековью, народной песне и преданию: собирание фольклора было делом одновременно художественным и национальным.

Сложился и образ художника как одинокого гения, живущего вопреки обществу. Этот образ, придуманный романтиками, оказался поразительно живучим и определяет представления об искусстве до сих пор.'),
  (493, 2, 'c_mass_literature', 'Массовая литература', 30, 9, 1, NULL, 'Роман с продолжением, дешёвое издание и чтение как повседневность.', 'Дешёвая бумага, скоропечатная машина и рост грамотности создали массового читателя, а с ним и литературу, рассчитанную на него.

Роман печатался в газете выпусками, и автор подстраивал сюжет под отклик публики — приём, знакомый нам по нынешним сериалам.

Писатель впервые смог жить литературным трудом, не завися от покровителя, но попал в зависимость от вкуса рынка. Спор о том, портит ли это литературу, начался тогда же.'),
  (494, 2, 'c_congresses', 'Конгрессы и союзы', 35, 9, 1, NULL, 'Общеевропейские съезды держав и поддержание равновесия сил.', 'Венский конгресс ввёл новый способ ведения дел: державы собираются вместе и перекраивают карту сообща, а затем регулярно съезжаются для обсуждения возникающих затруднений.

Замыслом было равновесие: ни одна держава не должна усилиться настолько, чтобы угрожать остальным. Система дала Европе почти столетие без общей войны.

Цена была в том, что равновесие поддерживалось и подавлением национальных и конституционных движений: порядок ставился выше народных требований, и это накапливало напряжение.'),
  (495, 2, 'c_working_class', 'Рабочий класс', 23, 9, 1, NULL, 'Формирование фабричного населения как отдельной общности со своим сознанием.', 'Фабрика собрала в одном месте тысячи людей с одинаковым положением: без собственности, живущих платой, зависящих от одного хозяина.

Совместная работа и общее жильё быстро породили и общее самоощущение: сначала общества взаимопомощи и кассы на случай болезни, затем требования, обращённые к хозяину и к государству.

Современники описывали положение рабочих кварталов как бедствие: смертность там была вдвое выше, чем в зажиточных приходах того же города, и это признавали правительственные комиссии.'),
  (496, 2, 'c_industrial_cities', 'Промышленные города', 36, 9, 1, NULL, 'Города, выросшие вокруг фабрик: скученность, копоть и стремительный рост.', 'Промышленный город рос быстрее, чем успевали строить: население удваивалось за десятилетия, а водопровода, канализации и жилья не хватало катастрофически.

Планировки не было вовсе: дома лепились вплотную к фабрике, дворы застраивались спальными бараками, а дым делал воздух видимым.

Именно бедствия таких городов вызвали к жизни и санитарное законодательство, и градостроительное регулирование, и позже — саму мысль о планировании города как государственной задаче.'),
  (497, 2, 'c_mass_press', 'Массовая пресса', 38, 9, 1, NULL, 'Дешёвая газета огромным тиражом, живущая рекламой.', 'Копеечная газета изменила само дело: доход стал приходить не от подписчиков, а от рекламы, а значит, издателю понадобился не состоятельный читатель, а массовый.

Отсюда перемена содержания: происшествия, суды, скандалы, короткие заметки и заголовки, рассчитанные на уличную продажу.

Пресса стала силой, с которой считались правительства: она умела создавать общественное возмущение и раскачивать политику, но так же легко раздувала военный азарт и травлю.'),
  (498, 2, 'c_nationalism', 'Национализм', 40, 9, 1, NULL, 'Нация как высшая общность и требование собственного государства.', 'Национализм утверждал, что границы государства должны совпадать с расселением народа, а народ имеет право на самостоятельность.

В первой половине века он шёл рука об руку с либерализмом и был направлен против империй, подавлявших народы; объединение Италии и Германии выросло отсюда.

Позднее он повернулся другой стороной: обосновывал притязания на чужие земли, превосходство над соседями и подозрение к меньшинствам внутри страны. Двойственность эта останется с ним навсегда.'),
  (499, 2, 'c_socialism', 'Социализм', 40, 9, 1, NULL, 'Общественная собственность и переустройство хозяйства ради равенства.', 'Ранний социализм был проповедью и опытом: устраивали образцовые общины, надеясь убедить остальных примером. Опыты по большей части распались.

Затем пришло иное обоснование, объяснявшее общественное устройство отношениями собственности и видевшее в рабочих ту силу, что изменит порядок.

Направление разошлось на два русла — постепенных преобразований через выборы и профсоюзы и революционного захвата власти, — и спор между ними определил политическую историю следующего столетия.'),
  (500, 2, 'c_parliamentarism', 'Парламентаризм', 33, 10, 1, NULL, 'Правительство, ответственное перед выборным собранием.', 'Ключевой сдвиг незаметен в текстах законов: министры начинают отвечать не перед монархом, а перед парламентом и уходят в отставку, потеряв его доверие.

Вместе с этим складываются устойчивые партии с программами, дисциплиной и местными отделениями — без них большое собрание не способно принимать решения.

Оформляется и роль оппозиции: несогласие перестаёт быть изменой и становится признанной частью устройства, а смена правительства — обычным делом, а не потрясением.'),
  (501, 2, 'c_unions', 'Профсоюзы', 32, 10, 1, NULL, 'Законные объединения работников для переговоров и стачки.', 'Долгое время сговор работников о плате считался преступлением, тогда как сговор хозяев преследовался редко. Признание за профсоюзами права существовать было переломом.

Сила профсоюза в способности остановить работу: стачка — единственное средство, уравнивающее переговорные возможности сторон.

Профсоюзы занимались не только платой: они создавали кассы взаимопомощи, школы и библиотеки и вскоре вышли в политику, породив рабочие партии.'),
  (502, 2, 'c_labor_law', 'Трудовое право', 24, 10, 1, NULL, 'Отдельная отрасль права: договор найма, охрана труда, разрешение споров.', 'Обычный договор предполагает равенство сторон, которого при найме нет. Трудовое право признаёт это неравенство и устанавливает правила, которые нельзя изменить соглашением в худшую сторону.

Появляются минимальные условия, охрана труда, возмещение за увечье и особые суды для трудовых споров.

Страхование от несчастного случая решило и застарелый вопрос вины: пострадавший получал возмещение независимо от того, удавалось ли доказать нерадивость хозяина.'),
  (503, 2, 'c_eight_hours', 'Борьба за восьмичасовой день', 32, 10, 1, NULL, 'Требование разделить сутки: восемь часов работы, отдыха и сна.', 'Формула «восемь часов труда, восемь отдыха, восемь сна» оказалась удачной: она понятна, легко запоминается и не требует объяснений.

Первое мая как день этого требования вошёл в календарь рабочего движения по всему миру и стал главным его символом.

Возражение хозяев было хозяйственным: сокращение часов разорит производство. Опыт показал обратное — выработка за час росла, и потери оказывались меньше ожидаемых.'),
  (504, 2, 'c_social_christianity', 'Социальное христианство', 26, 10, 1, NULL, 'Церковь обращается к рабочему вопросу: справедливая плата и достоинство труда.', 'Столкнувшись с отходом рабочих от церкви, богословы обеих конфессий взялись за общественный вопрос всерьёз.

Папская энциклика 1891 года осудила и безграничную свободу рынка, и социализм, утверждая право на справедливую плату, на объединение и на собственность.

Из этого выросли христианские профсоюзы и партии, надолго ставшие заметной политической силой Европы и предложившие третий путь между либерализмом и социализмом.'),
  (505, 2, 'c_civil_marriage', 'Гражданский брак и светские обряды', 27, 10, 1, NULL, 'Регистрация рождения, брака и смерти государством вместо церкви.', 'Передача записи актов гражданского состояния государству была не мелочью: она означала, что законность семьи устанавливает не приход, а чиновник.

Это разрешило и практическую задачу: браки между людьми разных исповеданий перестали быть невозможными.

Вместе с гражданским браком появились и светские похороны, и обряды имянаречения, а государство получило точную статистику населения, которой прежде не имело.'),
  (506, 2, 'c_marxism', 'Марксизм', 28, 10, 1, NULL, 'Объяснение истории отношениями собственности и борьбой классов.', 'Марксизм предложил объяснять общественное устройство и его перемены не идеями, а способом производства и отношениями между теми, кто владеет средствами труда, и теми, кто трудится.

Экономическая часть учения сегодня оспаривается, но сам приём — искать за политикой и культурой хозяйственные интересы — прочно вошёл в общественные науки.

Влияние оказалось двойственным: одна ветвь вела к парламентской социал-демократии и социальному государству, другая — к революции и однопартийным режимам XX века.'),
  (507, 2, 'c_total_mobilization', 'Всеобщая мобилизация', 34, 10, 1, NULL, 'План развёртывания армии из запасных по железным дорогам в считанные дни.', 'Мобилизация превратилась в расчёт: заранее известно, кто, куда и каким поездом едет, и весь план сведён в расписание, которое нельзя изменить на ходу.

Это дало решающее преимущество тому, кто развернётся быстрее, — и заодно чудовищную жёсткость: остановить запущенную мобилизацию значило разрушить весь план.

Историки указывают на это как на одну из причин, по которым июльский кризис 1914 года стало невозможно остановить: расписания подталкивали правительства объявлять мобилизацию первыми.'),
  (508, 2, 'c_espionage', 'Шпионаж', 39, 10, 1, NULL, 'Постоянные разведывательные службы в мирное время.', 'Раньше разведка была делом военного времени и поручалась офицерам при штабе. Теперь появляются постоянные службы, работающие непрерывно.

Предметом стали не только войска, но и промышленность, транспорт и настроения: война будущего мыслилась как противоборство всего хозяйства.

Одновременно возникла шпиономания: пресса раздувала страх перед тайными агентами, а судебные дела вроде дела Дрейфуса показали, до чего доводит подозрительность, усиленная предрассудком.'),
  (509, 2, 'c_trusts', 'Монополии и тресты', 31, 10, 1, NULL, 'Слияния и соглашения о разделе рынка; антимонопольное законодательство в ответ.', 'Крупное производство требовало таких вложений, что число участников рынка сокращалось само собой, а оставшиеся легко договаривались о ценах.

Тресты и картели поднимали цены и душили новичков, и общественное недовольство вынудило государство вмешаться: появились законы о недопущении сговора и о разделении чрезмерно крупных объединений.

Так родилось противоречие, которое сопровождает хозяйство до сих пор: крупный размер даёт выигрыш в издержках, но лишает рынок соперничества.'),
  (510, 2, 'c_primary_education', 'Всеобщее начальное образование', 25, 10, 1, NULL, 'Обязательная и бесплатная школа для всех детей.', 'Обязательность вводилась постепенно и с сопротивлением: семьи теряли рабочие руки, и школьная повинность казалась им поборами.

Доводы государства были прикладными: грамотный призывник и рабочий полезнее, а единая школа сплачивает нацию и распространяет общий язык.

Итог оказался быстрым: за одно-два поколения грамотность в развитых странах поднялась с половины населения почти до всеобщей, и это изменило всё — от печати до политики.'),
  (511, 2, 'c_technical_education', 'Техническое образование', 25, 10, 1, NULL, 'Реальные училища, политехникумы и инженерная подготовка.', 'Классическое образование с латынью не готовило к промышленности, и рядом с гимназией выросли реальные училища и высшие технические школы.

Германская связка технических вузов с промышленностью и исследовательскими лабораториями оказалась настолько успешной, что её изучали и перенимали остальные страны.

Инженер становится общественной фигурой: человек, соединяющий научное знание с практикой, приобретает вес, сопоставимый с юристом и врачом.'),
  (512, 2, 'c_impressionism', 'Импрессионизм и модерн', 29, 10, 1, NULL, 'Отказ от академической выучки: свет, впечатление, декоративная линия.', 'Фотография отняла у живописи задачу точного изображения, и художники обратились к тому, чего снимок не передаёт: свету, движению, впечатлению мгновения.

Академия и салон отвергали новое, и художники стали устраивать собственные выставки и работать с торговцами картинами — так сложился современный художественный рынок.

Модерн распространил новый подход на предметы быта, шрифт, вывеску и здание, утверждая, что красота должна входить в повседневность, а не жить в музее.'),
  (513, 2, 'c_mass_literacy', 'Массовая грамотность', 30, 10, 1, NULL, 'Читающее большинство: письмо как повседневный навык.', 'Грамотность из признака сословия превратилась в обычное умение, и это изменило устройство общественной жизни целиком.

Читать стали не только книги: расписание, объявление, инструкцию, договор, письмо. Общество, где все читают, управляется иначе, чем общество, где читают немногие.

Открылся и путь наверх: экзамен на должность, конкурс, письменное прошение — всё это требует грамоты, и она стала первым условием подвижности в обществе.'),
  (514, 2, 'c_bloc_politics', 'Блоковая политика', 35, 10, 1, NULL, 'Постоянные военные союзы мирного времени с обязательством вступить в войну.', 'Прежде союзы заключались под определённую войну. Теперь они действуют постоянно и обязывают вступиться за союзника, даже если спор тебя не касается.

Это должно было сдерживать нападение, но дало обратное: местный конфликт автоматически втягивал всех, превращая ссору двух держав в общую войну.

Тайные статьи договоров усугубляли дело: правительства не вполне знали, к чему обязаны их партнёры, и просчитывали чужие действия неверно.'),
  (515, 2, 'c_suffrage', 'Расширение избирательного права', 23, 10, 1, NULL, 'Снятие имущественного ценза и переход к всеобщему голосованию мужчин.', 'Избирательное право расширялось ступенями: сначала снижался имущественный ценз, затем отменялся вовсе. Каждый шаг сопровождался предсказаниями катастрофы, которые не сбывались.

Вместе с расширением пришли тайное голосование, ограждающее избирателя от давления хозяина, и нарезка округов, которая тут же стала предметом злоупотреблений.

Массовый избиратель изменил и политику: понадобились партийная организация, агитация, пресса и умение говорить с толпой, а не только с собранием равных.'),
  (516, 2, 'c_metropolis', 'Метрополии', 36, 10, 1, NULL, 'Города-миллионники: транспорт, пригороды и разделение по достатку.', 'Город перерос пешеходные размеры: конка, а затем трамвай и метро позволили жить далеко от места работы, и город растянулся вдоль линий транспорта.

Следствием стало разделение: центр — деловой и торговый, окраины и пригороды — жилые, причём разные для разного достатка. Прежнее соседство сословий в одном квартале исчезло.

Столица превращается в средоточие всего — власти, печати, денег, науки, — и разрыв между нею и провинцией становится самостоятельным политическим вопросом.'),
  (517, 2, 'c_news_agencies', 'Телеграфные агентства и репортаж', 38, 10, 1, NULL, 'Оперативная новость по телеграфу и корреспондент на месте события.', 'Агентства продавали новости газетам всего мира, и впервые о событии стало возможно узнать в тот же день на другом континенте.

Появился военный корреспондент: сообщения с фронта и фотографии сделали войну видимой для тыла, что немедленно отразилось на общественном мнении и на правительственных решениях.

Скорость породила и новую беду: непроверенное сообщение расходилось по сотням изданий за часы, и опровержение уже никого не догоняло.'),
  (518, 2, 'c_imperialism', 'Империализм', 40, 10, 1, NULL, 'Раздел мира между державами и обоснование господства над колониями.', 'Раздел Африки был проведён почти целиком в кабинетах: границы чертили по картам, не считаясь ни с расселением народов, ни с их согласием.

Обоснование строилось на мнимом долге просвещать и на превратно понятых доводах о естественном отборе между народами.

Проведённые тогда границы пережили колониальные империи и остались источником конфликтов, поскольку рассекли одни общности и соединили в одном государстве другие, враждебные друг другу.'),
  (519, 2, 'c_suffragism', 'Суфражизм и ранний феминизм', 40, 10, 1, NULL, 'Требование избирательных и имущественных прав для женщин.', 'Движение опиралось на простое противоречие: провозглашённое равенство перед законом не распространялось на половину населения.

Начали с прав имущественных и семейных — права замужней женщины владеть своим имуществом, права на детей, доступа к образованию и профессии, — а затем перешли к избирательному праву.

Первыми уступили окраины и молодые государства, где общественный порядок был менее устоявшимся; крупные европейские державы пришли к этому только после мировой войны, когда женский труд в тылу сделал возражения невозможными.'),
  (520, 2, 'c_sport_federations', 'Спортивные федерации', 37, 10, 1, NULL, 'Единые правила, календарь соревнований и разделение любителей и профессионалов.', 'Пока каждый клуб играл по своим правилам, встреча с соседями требовала долгих переговоров. Федерация устраняет это, утверждая единый свод и календарь.

Железная дорога и дешёвая пресса сделали регулярные первенства возможными: команды могли ездить, а публика — следить за таблицей.

Спор о любительстве был социальным: требование выступать бесплатно закрывало спорт для тех, кто не мог позволить себе не работать, и потому долго держал состязания сословно замкнутыми.'),
  (521, 2, 'c_olympics_modern', 'Олимпийское движение', 37, 10, 1, NULL, 'Возрождение всемирных игр как состязания наций.', 'Возрождённые игры соединили античный образец с очень современным содержанием: команды выступают от стран, под флагами и с гимнами.

Провозглашённая цель была миротворческой, но соревнование быстро стало и полем державного соперничества, где число медалей толковалось как показатель превосходства.

Игры дали и редкое общее событие: раз в четыре года мир следит за одним и тем же, и мало какое учреждение способно собрать столь широкое внимание.'),
  (522, 2, 'c_totalitarian', 'Тоталитарное государство', 33, 11, 1, NULL, 'Единственная партия, идеология и подчинение всей жизни общества власти.', 'Тоталитарный режим отличается от прежнего самовластия притязанием: он требует не покорности, а участия и веры, и не оставляет области, до которой ему нет дела.

Средствами стали единственная партия, надзор, массовые организации для всех возрастов, монополия на печать и постоянное указание на врага.

Такое стало возможно только в XX веке: без массовой печати, радио, картотеки и железной дороги охватить подобным образом целую страну технически не удавалось.'),
  (523, 2, 'c_league', 'Лига наций', 35, 11, 1, NULL, 'Первая всемирная организация для предотвращения войн.', 'Замысел был нов: не союз против кого-то, а объединение всех, где нападение на одного считается делом каждого и влечёт общие меры.

На деле механизм не сработал: решения требовали единогласия, собственных сил у Лиги не было, а крупнейшие державы либо не вступили, либо вышли.

Но кое-что удалось: устройство беженцев, борьба с эпидемиями, надзор за трудовыми нормами. Эти направления пережили саму Лигу и перешли к её преемнице.'),
  (524, 2, 'c_tribunals', 'Международные трибуналы', 24, 11, 1, NULL, 'Личная уголовная ответственность за развязывание войны и преступления против человечности.', 'Нюрнбергский процесс установил принцип, прежде отсутствовавший: отвечает не государство, а конкретные люди, и приказ не освобождает исполнителя от ответственности.

Возражения были серьёзными — суд победителей, применение норм, не существовавших в момент деяния, — и их признавали сами участники.

Тем не менее заложенное там понятие преступления против человечности вошло в международное право и легло в основу всех позднейших трибуналов.'),
  (525, 2, 'c_leader_cult', 'Культ вождя и государственная символика', 26, 11, 1, NULL, 'Придание власти священных черт: вождь, символы, ритуальная преданность.', 'Там, где религия отступила, освободившееся место заняли светские культы: изображения вождя, клятвы, знамёна и церемонии, устроенные по образцу церковных.

Исследователи прямо называют это гражданской религией: те же приёмы — священные тексты, мученики, праздники, обряд принятия в общность.

Сила такого культа в том, что он даёт человеку принадлежность и смысл, а требует взамен послушания — обмен, оказавшийся привлекательным для миллионов людей в эпоху потрясений.'),
  (526, 2, 'c_mass_rallies', 'Массовые шествия и съезды', 27, 11, 1, NULL, 'Организованное собрание тысяч людей как обряд единства.', 'Массовое шествие устроено так, чтобы участник ощутил себя частью огромного целого: строй, единая форма, знамёна, музыка, свет и речь с трибуны.

Всё это делалось расчётливо и с привлечением архитекторов, режиссёров и кинематографистов: съезды снимались и монтировались как зрелище для тех, кто на них не был.

Приём переняли не только диктатуры: массовые демонстрации и митинги стали постоянным средством и профсоюзов, и гражданских движений.'),
  (527, 2, 'c_existentialism', 'Экзистенциализм', 28, 11, 1, NULL, 'Существование прежде сущности: свобода, выбор и ответственность без опоры.', 'После двух мировых войн вера в разумный ход истории пошатнулась, и философия обратилась к отдельному человеку, оставшемуся без готовых оснований.

Основное утверждение звучит резко: человек не имеет заранее данной природы, он делается тем, что выбирает, и потому обречён быть свободным и отвечать за выбор.

Философия вышла за пределы кафедры: она говорила языком романа, пьесы и эссе и обсуждалась в кафе и газетах — редкий случай подлинно общественного философского направления.'),
  (528, 2, 'c_combined_arms', 'Общевойсковой бой', 34, 11, 1, NULL, 'Согласованные действия пехоты, танков, артиллерии и авиации.', 'Опыт мировой войны показал, что ни один род войск не решает задачу сам: пехота без поддержки ложится под огнём, танки без пехоты гибнут в застройке, авиация не удерживает местность.

Ответом стало соединение всех родов в одном соединении под единым командованием, а связующим средством — радио, позволившее управлять боем в движении.

Успех зависел не от превосходства техники, а от согласованности: кампании начала второй мировой войны выиграны армией, уступавшей противнику в числе танков, но превосходившей его в организации.'),
  (529, 2, 'c_counterintel', 'Контрразведка', 39, 11, 1, NULL, 'Защита от чужой разведки, дезинформация и радиоперехват.', 'Контрразведка занимается не столько ловлей шпионов, сколько управлением тем, что противник узнаёт: перевербованный агент ценнее арестованного.

Радиосвязь дала перехват, а перехват потребовал шифра; борьба шифровальщиков и дешифровальщиков стала отдельным театром войны, повлиявшим на её ход не меньше иных сражений.

Операции по обману достигли размаха целых кампаний: несуществующие армии с поддельным радиообменом и макетами техники вводили противника в заблуждение относительно места высадки.'),
  (530, 2, 'c_planned_economy', 'Плановая экономика', 31, 11, 1, NULL, 'Централизованное распределение ресурсов по государственному плану.', 'План заменяет рынок как способ решить, что производить: задания спускаются предприятиям, а ресурсы распределяются по фондам.

Такой порядок хорошо справляется с сосредоточением сил на немногих задачах — индустриализации, вооружении, восстановлении — и плохо с разнообразием потребительских нужд.

Экономисты указали и на коренную трудность: без цен, складывающихся в обмене, планирующий орган лишён сведений о том, чего и сколько на деле нужно, и вынужден угадывать.'),
  (531, 2, 'c_social_insurance', 'Социальное страхование', 32, 11, 1, NULL, 'Пенсии, пособия по болезни и безработице за счёт взносов.', 'Первые системы ввёл Бисмарк с прямо названным политическим расчётом: перехватить у социалистов их требования и привязать рабочего к государству.

Устройство оказалось удачным: взносы работника и хозяина образуют фонд, из которого платят при болезни, увечье, старости и потере работы.

Великая депрессия сделала такие системы всеобщими: массовая безработица показала, что без общественной поддержки рынок труда способен обрушить и хозяйство, и политический порядок.'),
  (532, 2, 'c_secondary_education', 'Всеобщее среднее образование', 25, 11, 1, NULL, 'Продление обязательного обучения и массовая средняя школа.', 'Промышленность и управление потребовали работников, умеющих больше, чем читать и считать, и обязательное обучение продлили до подросткового возраста.

Средняя школа перестала быть подготовкой к университету для немногих и стала общей ступенью со своей программой и экзаменом.

Вместе с ней появились и подростковый возраст как отдельная пора жизни, и школьная среда со своими нравами — то, чего не знало общество, где в четырнадцать лет уже работали.'),
  (533, 2, 'c_avant_garde', 'Авангард', 29, 11, 1, NULL, 'Разрыв с изобразительностью: беспредметность, конструкция, манифест.', 'Авангард отказался от изображения видимого и занялся самим языком искусства: цветом, формой, конструкцией, материалом.

Появился и новый жанр — манифест: направление объявляет о себе программой, а не постепенно складывается. Искусство становится делом деклараций и групп.

Многие течения соединяли художественное с общественным, желая переустроить не только картину, но и быт: отсюда дизайн, плакат, оформление жилища и производства как поле работы художника.'),
  (534, 2, 'c_publicism', 'Публицистика', 30, 11, 1, NULL, 'Очерк, репортаж и колонка: слово как непосредственное участие в делах общества.', 'Публицистика заняла место между литературой и газетой: она пишет о действительном, но средствами художественного слова и с открыто заявленной позицией.

Расследовательский очерк показал свою силу: журналистские разоблачения условий труда, качества продуктов и работы монополий приводили к принятию законов.

Она же оказалась удобным средством пропаганды, и различение честного расследования и заказанной кампании стало постоянной заботой самих журналистов.'),
  (535, 2, 'c_universal_suffrage', 'Всеобщее избирательное право', 23, 11, 1, NULL, 'Голос каждого совершеннолетнего гражданина независимо от пола и достатка.', 'Женское избирательное право пробило себе дорогу после мировой войны, когда женский труд в тылу сделал прежние возражения несостоятельными.

Расовые и имущественные ограничения держались дольше и в ряде стран были сняты лишь во второй половине века, порой после долгой борьбы.

Всеобщее голосование окончательно изменило политику: партии стали обращаться ко всему населению, и социальные вопросы вышли на первое место, потеснив прежние споры элит.'),
  (536, 2, 'c_suburbs', 'Пригороды', 36, 11, 1, NULL, 'Малоэтажная застройка вокруг города и жизнь на автомобиле.', 'Автомобиль и дешёвая ипотека сделали возможным то, чего не давал трамвай: собственный дом с участком в получасе езды от работы.

Пригород стал воплощением благополучия среднего класса, но и породил зависимость от машины: без неё оттуда не добраться ни до работы, ни до магазина.

Обратной стороной стало опустение центров и разделение по достатку и происхождению, закреплённое банковской практикой отказа в кредите жителям определённых кварталов.'),
  (537, 2, 'c_cinema', 'Кинематограф', 38, 11, 1, NULL, 'Массовое зрелище и самое действенное средство внушения своего времени.', 'Кино соединило зрелищность театра с охватом печати: один фильм смотрели десятки миллионов, и он говорил с ними на языке, не требующем грамоты.

Монтаж оказался средством не только рассказа, но и убеждения: сопоставление кадров создаёт смысл, которого нет в каждом из них по отдельности.

Все правительства эпохи это оценили, и кинохроника с художественным фильмом стали главными орудиями пропаганды — а вместе с тем и предметом строжайшей цензуры.'),
  (538, 2, 'c_fascism', 'Фашизм', 40, 11, 1, NULL, 'Вождь, нация и государство выше личности; культ силы и врага.', 'Фашизм вырос из послевоенного разочарования: обещанное благополучие не пришло, старые партии выглядели бессильными, а память о войне давала готовый язык товарищества и жертвы.

Он отрицал и либеральное разделение властей, и классовую борьбу, предлагая взамен единство нации под властью вождя и постоянную мобилизацию против врага, внешнего и внутреннего.

К власти он приходил не только силой, но и по формально законным путям, при поддержке части общества, — обстоятельство, из-за которого его изучение остаётся неудобным и необходимым.'),
  (539, 2, 'c_fundamentalism', 'Фундаментализм', 40, 11, 1, NULL, 'Требование вернуться к буквальному основанию веры против современности.', 'Фундаментализм — явление вполне современное: он возникает как ответ на секуляризацию, науку и городскую жизнь и пользуется теми же средствами — печатью, радио, организацией.

Требование буквального прочтения священного текста само по себе новшество: прежние богословские традиции широко пользовались иносказательным толкованием.

Явление это не привязано к одной религии: сходные движения возникли в разных вероисповеданиях примерно в одно время и по сходным причинам.'),
  (540, 2, 'c_pro_sport', 'Профессиональный спорт', 37, 11, 1, NULL, 'Спорт как занятие и зрелище: клубы, контракты, трансляции и болельщики.', 'Признание профессионализма сняло сословный барьер: спортом смогли заниматься те, кто не имел состояния, и уровень результатов немедленно вырос.

Радиорепортаж, а затем кинохроника создали болельщика, следящего за командой, не бывая на стадионе, и сделали спортсмена всенародно известным лицом.

Вместе с деньгами пришли и постоянные спутники: договорные матчи, ставки, торговля игроками и вопрос о том, кому принадлежит клуб — городу или владельцу.'),
  (541, 2, 'c_superpowers', 'Сверхдержавы', 33, 12, 1, NULL, 'Два государства, определяющие мировую политику своим противостоянием.', 'Сверхдержава отличалась от великой державы прошлого возможностью действовать по всему миру и уничтожить противника ядерным оружием.

Мир разделился на два лагеря с собственными союзами, хозяйственными системами и образами будущего, и почти любое местное событие толковалось через это противостояние.

Прямого столкновения не произошло: обе стороны понимали, что война между ними не имеет победителя, и переносили соперничество в третьи страны, в космос, в спорт и в идеологию.'),
  (542, 2, 'c_udhr', 'Всеобщая декларация прав человека', 24, 12, 1, NULL, 'Общий перечень прав, признанный за каждым человеком независимо от государства.', 'Декларация 1948 года была ответом на опыт войны: стало очевидно, что государство способно уничтожать собственных граждан, и что права нуждаются в защите извне.

Юридически обязательной силы документ сначала не имел, но задал общий язык, на котором с тех пор ведётся спор, и лёг в основу последующих договоров и конституций.

Спор о всеобщности прав не окончен: одни считают их универсальными, другие указывают на западное происхождение перечня. Показательно, что даже возражающие спорят внутри той же рамки.'),
  (543, 2, 'c_decolonization', 'Деколонизация', 33, 12, 1, NULL, 'Распад колониальных империй и появление десятков новых государств.', 'Война подорвала и силы метрополий, и их право на господство: державы, воевавшие против расовой доктрины, не могли убедительно её сохранять в колониях.

Освобождение шло по-разному — от мирной передачи власти до многолетних войн, — но почти везде новые государства получали границы, начерченные колонизаторами.

Это и стало главной трудностью: границы рассекали народы и соединяли враждующих, а хозяйство было настроено на вывоз сырья и не приспособлено к самостоятельности.'),
  (544, 2, 'c_ecumenism', 'Экуменизм', 26, 12, 1, NULL, 'Сближение христианских церквей и диалог религий.', 'После веков вражды церкви пошли на сближение: были сняты взаимные отлучения, начались совместные молитвы и богословские собеседования.

Второй Ватиканский собор изменил многое разом: богослужение на родных языках, признание доли истины в других исповеданиях, отказ от обвинения целого народа в гибели Христа.

Побуждением было не только богословие: перед лицом секуляризации и общих нравственных вопросов разделения выглядели менее важными, чем прежде.'),
  (545, 2, 'c_war_memorials', 'Мемориалы и дни памяти', 27, 12, 1, NULL, 'Обряды памяти о погибших: могила неизвестного солдата, минута молчания.', 'Мировые войны потребовали новых обрядов: погибших было слишком много, и многие остались неопознанными. Могила неизвестного солдата решала эту задачу — оплакать всех разом.

Минута молчания, вечный огонь, списки имён на камне стали общим языком памяти, принятым в самых разных странах.

Память оказалась и предметом спора: кого поминать, как называть события и чьи жертвы признавать — вопросы, по которым общества расходятся десятилетиями.'),
  (546, 2, 'c_structuralism', 'Структурализм', 28, 12, 1, NULL, 'Поиск скрытых устойчивых структур за языком, обычаем и повествованием.', 'Структурализм перенёс приёмы языкознания на изучение общества: значение возникает не в отдельном элементе, а в системе различий между ними.

Так были разобраны мифы, системы родства, мода и повествование: за внешним разнообразием обнаруживались повторяющиеся схемы.

Возражение пришло скоро: если всё определяется структурой, то куда девается действующий человек? Из этого спора вырастет то, что назовут постструктурализмом.'),
  (547, 2, 'c_deterrence', 'Ядерное сдерживание', 34, 12, 1, NULL, 'Мир, обеспеченный гарантией взаимного уничтожения.', 'Логика сдерживания парадоксальна: безопасность обеспечивается не защитой, а гарантией того, что нападающий будет уничтожен ответным ударом.

Отсюда странные на первый взгляд следствия: противоракетная оборона считалась дестабилизирующей, поскольку прикрытая сторона могла бы решиться ударить первой.

Устойчивость держалась на неуязвимости ответных сил и на исправности систем предупреждения. Известные случаи ложных тревог показывают, насколько узкой была эта тропа.'),
  (548, 2, 'c_mic', 'Военно-промышленный комплекс', 39, 12, 1, NULL, 'Устойчивая связка армии, промышленности и науки в мирное время.', 'Впервые в истории военная промышленность работала на полную мощность в мирные годы, а исследования велись по государственному заказу непрерывно.

Эйзенхауэр, сам генерал, в прощальной речи предупредил об опасности такого сращивания для свободного общества — предупреждение, ставшее одним из самых цитируемых в XX веке.

Побочные плоды оказались громадными: интернет, спутниковая навигация, вычислительная техника и авиация выросли из военных программ.'),
  (549, 2, 'c_consumer_society', 'Общество потребления', 31, 12, 1, NULL, 'Массовое благосостояние, реклама и обновление вещей как норма жизни.', 'Послевоенные десятилетия дали невиданный рост доходов: автомобиль, холодильник, телевизор и отпуск стали доступны рядовой семье.

Хозяйство перестроилось на постоянное обновление: вещь меняют не когда она сломалась, а когда вышла из моды, и это поддерживает спрос.

Критика появилась немедленно: изобилие не сделало людей счастливее, зато породило расточительность и превратило гражданина в покупателя. Спор этот с тех пор не прекращался.'),
  (550, 2, 'c_collective_bargaining', 'Коллективный договор', 32, 12, 1, NULL, 'Переговоры профсоюзов и работодателей об условиях для целой отрасли.', 'Коллективный договор распространяет достигнутые условия на всех работников отрасли, а не только на членов профсоюза, и потому задаёт общий уровень.

Сложилось трёхстороннее устройство: профсоюзы, объединения работодателей и государство как посредник — порядок, обеспечивший десятилетия сравнительно спокойных отношений.

Обмен был явным: работники получали растущую плату и гарантии, работодатели — предсказуемость и отсутствие стачек. Ослабление этой связки к концу века изменит положение обеих сторон.'),
  (551, 2, 'c_higher_education', 'Массовое высшее образование', 25, 12, 1, NULL, 'Университет для многих: расширение приёма и новые вузы.', 'Число студентов выросло в разы: высшее образование перестало быть принадлежностью узкого слоя и стало обычным этапом жизни.

Государство вкладывалось в это сознательно, видя в подготовке специалистов условие хозяйственного и военного соперничества.

Многочисленное студенчество стало и самостоятельной общественной силой: волнения конца шестидесятых прокатились почти по всем странам сразу и заметно изменили нравы и политику.'),
  (552, 2, 'c_pop_art', 'Поп-арт', 29, 12, 1, NULL, 'Искусство из языка рекламы, комикса и товарной упаковки.', 'Поп-арт взял материал там, где искусство прежде его не искало: в рекламе, упаковке, комиксе и газетном снимке.

Приём тиражирования одного изображения ставил вопрос о подлиннике и копии в обществе, где всё воспроизводится машинным способом.

Спор шёл о том, критика это потребления или его прославление, и художники сознательно оставляли вопрос без ответа — двусмысленность была частью замысла.'),
  (553, 2, 'c_translations', 'Мировая литература в переводах', 30, 12, 1, NULL, 'Массовый перевод и доступ к книгам других культур.', 'Дешёвая книга в мягкой обложке и государственные программы переводов сделали литературу других стран повседневно доступной.

Перевод перестал быть вольным пересказом и стал предметом теории со спорами о верности букве и духу.

Следствие оказалось культурным: читатель получил представление о том, как живут и думают в других частях света, — то, чего прежде не давало ничто, кроме путешествия.'),
  (554, 2, 'c_un_blocs', 'ООН и блоки', 35, 12, 1, NULL, 'Всемирная организация с Советом Безопасности и раздел мира на военные союзы.', 'Учтя неудачу Лиги, устав ООН дал Совету Безопасности право принимать обязательные решения, но закрепил за пятью державами право вето.

Вето сделало ООН бессильной в спорах между сверхдержавами и вместе с тем сохранило её: организация, из которой невыгодно выходить, продолжает существовать.

Реально работали иные её части: миротворческие силы, помощь беженцам, здравоохранение и продовольственные программы, где успехи бесспорны.'),
  (555, 2, 'c_civil_movements', 'Гражданские движения', 23, 12, 1, NULL, 'Ненасильственная борьба за равные права: бойкот, марш, гражданское неповиновение.', 'Движение опиралось на противоречие между провозглашёнными правами и действительным положением, и это делало его доводы неотразимыми.

Приёмы были обдуманными: бойкот, сидячие протесты, марши и намеренное нарушение несправедливого закона с готовностью понести наказание.

Решающую роль сыграло телевидение: страна увидела применение силы против мирных участников, и общественное мнение переменилось быстрее, чем от любых доводов.'),
  (556, 2, 'c_middle_class', 'Средний класс', 23, 12, 1, NULL, 'Широкий слой с устойчивым доходом, жильём и доступом к образованию.', 'Сочетание роста платы, социального страхования, дешёвого кредита и массового образования создало слой, живущий не богатством и не нуждой, а устойчивым достатком.

Именно он стал опорой политической умеренности: люди, имеющие что терять и на что надеяться, редко поддерживают крайности.

Устойчивость эта не была вечной: расхождение доходов и удорожание жилья к концу века вновь поставили под вопрос само существование такого слоя.'),
  (557, 2, 'c_microdistricts', 'Микрорайоны', 36, 12, 1, NULL, 'Жилые массивы с расчётной обеспеченностью школами, садами и магазинами.', 'Микрорайон проектировался как единица с нормативом: столько-то жителей, столько-то мест в школе и детском саду, магазин и поликлиника в пешей доступности.

Это решило острейшую задачу — расселение из бараков и коммунальных квартир — и дало миллионам людей отдельное жильё с удобствами.

Критика указывала на однообразие, отсутствие уличной жизни и разрыв связей старого квартала. Оценки расходятся до сих пор, и во многом они зависят от того, с чем сравнивать.'),
  (558, 2, 'c_tv_broadcast', 'Телевещание', 38, 12, 1, NULL, 'Телевизор в каждом доме: общее зрелище и новая политика.', 'Телевидение соединило охват радио с наглядностью кино и стало главным источником сведений для большинства населения.

Политика перестроилась под него: значение приобрели облик, манера и краткая запоминающаяся фраза, а теледебаты стали решать исход выборов.

Оно же создало общее переживание: миллионы одновременно видят посадку на Луну, убийство президента или чемпионат — единство внимания, которого прежде не бывало.'),
  (559, 2, 'c_cold_war', 'Холодная война', 40, 12, 1, NULL, 'Всемирное противостояние двух образов будущего без прямой войны.', 'Противостояние велось всеми средствами, кроме прямого столкновения: гонкой вооружений, поддержкой союзников, разведкой, пропагандой, помощью развивающимся странам, наукой и спортом.

Идеологическая часть была не украшением, а существом: обе стороны предлагали миру образ будущего и доказывали его превосходство достижениями.

Отсюда и странные плоды: соперничество ускорило космонавтику, вычислительную технику и социальные программы, поскольку каждая сторона должна была показать, что её порядок лучше.'),
  (560, 2, 'c_international_tournaments', 'Международные турниры', 37, 12, 1, NULL, 'Регулярные всемирные первенства и спорт как соперничество держав.', 'Всемирные первенства и Олимпиады превратились в поле державного соперничества: медальный зачёт толковался как доказательство превосходства общественного строя.

Отсюда государственные программы подготовки, спортивные интернаты и, как обратная сторона, систематическое применение допинга.

Спорт стал и средством политики: бойкоты Олимпиад, отстранение стран, а иногда, напротив, спортивная встреча служила первым шагом к восстановлению отношений.'),
  (561, 2, 'c_nuclear_ethics', 'Ядерная этика', 41, 12, 1, NULL, 'Ответственность учёного и допустимость оружия, угрожающего человечеству.', 'Создатели бомбы первыми поставили вопрос об ответственности: многие участники проекта выступили затем за международный контроль над атомной энергией.

Манифест Рассела — Эйнштейна сформулировал задачу предельно просто: перед лицом оружия, способного уничтожить человечество, надо научиться мыслить по-новому и отказаться от войны как средства.

Отсюда выросли и договоры об ограничении испытаний и распространения, и сама мысль о том, что у науки есть последствия, за которые отвечает не только государство, но и учёный.'),
  (562, 2, 'c_technocracy', 'Технократия', 33, 13, 1, NULL, 'Управление через экспертизу: ведомства специалистов и решения по расчёту.', 'Усложнение хозяйства и техники сделало политические решения зависимыми от заключений специалистов: центральный банк, статистическое ведомство, надзор за безопасностью действуют по собственной логике.

Выигрыш в качестве решений очевиден; сложность в подотчётности: избиратель не может оценить довод, который не понимает.

Отсюда постоянное напряжение между сведущим ведомством и выборной властью, особенно заметное там, где решение специалистов болезненно для людей.'),
  (563, 2, 'c_information_law', 'Информационное право', 24, 13, 1, NULL, 'Право на доступ к сведениям, авторское право и защита персональных данных.', 'Информация стала предметом права: кому принадлежат сведения, кто вправе их получить и кто отвечает за их распространение.

Законы о свободе доступа к государственным сведениям исходят из перевёрнутого правила: открыто всё, кроме прямо закрытого, и отказ надо обосновать.

Одновременно появилось понятие персональных данных: сведения о человеке признаны требующими защиты, поскольку их сбор и сопоставление создают власть над ним.'),
  (564, 2, 'c_new_religions', 'Новые религиозные движения', 26, 13, 1, NULL, 'Множество новых учений и переход веры в область личного выбора.', 'Ослабление традиционных церквей не привело к исчезновению религиозности: она рассыпалась на множество течений, часть которых заимствовала восточные учения, часть строилась заново.

Вера всё чаще становится личным выбором и складывается из разнородных источников, а не наследуется вместе с общиной.

Появились и опасные явления: замкнутые группы с полным подчинением участников поставили перед правом трудный вопрос о границе между свободой вероисповедания и защитой человека.'),
  (565, 2, 'c_subcultures', 'Субкультуры', 27, 13, 1, NULL, 'Молодёжные сообщества со своим внешним видом, музыкой и обрядами.', 'Продление обучения и отдельные заработки создали молодёжь как самостоятельную общественную группу с собственным временем, деньгами и вкусами.

Субкультура даёт то же, что прежде давала община: принадлежность, отличие от чужих, обряды принятия и признанных старших.

Отношения с рынком двойственны: почти каждое движение, начинавшееся как отрицание потребления, довольно быстро становилось предметом продажи в виде одежды, пластинок и стиля.'),
  (566, 2, 'c_postmodernism', 'Постмодернизм', 28, 13, 1, NULL, 'Недоверие к всеобъемлющим объяснениям и к единственной истине.', 'Постмодернизм отказался от больших повествований — о прогрессе, разуме, неизбежном освобождении, — указав, что каждое из них служило чьей-то власти.

Отсюда внимание к языку и к тому, как описание создаёт предмет, а также интерес к тому, кто и в чьих интересах говорит.

Критика была не менее резкой: если всякое утверждение лишь точка зрения, то как отличить знание от вымысла и на что опереться в споре? Вопрос остаётся открытым.'),
  (567, 2, 'c_asymmetric_war', 'Партизанская и асимметричная война', 34, 13, 1, NULL, 'Слабая сторона избегает сражения и изматывает сильную.', 'Асимметричная война меняет цель: не разбить войска, а сделать пребывание противника невыносимо дорогим и долгим, опираясь на местное население.

Техническое превосходство при этом обесценивается: против рассеянного противника, неотличимого от жителей, тяжёлое вооружение малополезно.

Решающим полем становится общественное мнение в стране, ведущей войну вдали: затяжной конфликт без видимой цели теряет поддержку раньше, чем истощаются силы.'),
  (568, 2, 'c_terrorism', 'Международный терроризм', 39, 13, 1, NULL, 'Насилие против мирных людей ради воздействия на политику через страх.', 'Терроризм рассчитан не на военный результат, а на отклик: нападение совершается ради того, чтобы о нём сообщили, и потому неразрывно связано с массовой печатью и телевидением.

Ответом стали международное сотрудничество служб, досмотр в аэропортах и законодательство, расширяющее полномочия власти.

Здесь и коренится главная трудность: чрезмерный ответ достигает той самой цели нападавших — изменения общества в сторону страха и ограничений.'),
  (569, 2, 'c_globalization', 'Глобализация', 31, 13, 1, NULL, 'Единый мировой рынок товаров, денег и производственных цепочек.', 'Дешёвая перевозка, связь и снятие торговых барьеров позволили разнести производство одного изделия по десяткам стран, выбирая для каждой операции самое выгодное место.

Результат двойствен: сотни миллионов людей вышли из крайней бедности, а расхождение доходов внутри богатых стран выросло.

Уязвимость длинных цепочек обнаружилась позже: сбой в одном звене останавливает производство на другом конце света, и это заставило заново задуматься о запасах и надёжности.'),
  (570, 2, 'c_service_economy', 'Постиндустриальная занятость', 32, 13, 1, NULL, 'Большинство работает в услугах, а не в промышленности и на земле.', 'Промышленность продолжала расти, но занятых в ней становилось меньше: производительность росла быстрее выпуска, а часть производств переносилась в другие страны.

Занятость перешла в услуги — торговлю, здравоохранение, образование, финансы, — где труд иначе устроен и хуже поддаётся измерению.

Для промышленных областей это обернулось бедствием: закрытие завода лишало города не только работы, но и смысла существования, и последствия этого сказываются в политике десятилетиями.'),
  (571, 2, 'c_lifelong_learning', 'Непрерывное образование', 25, 13, 1, NULL, 'Переобучение в течение жизни вместо одной профессии навсегда.', 'Быстрая смена техники сделала полученное однажды образование недостаточным: профессии исчезают и появляются быстрее, чем сменяются поколения.

Возникли курсы переподготовки, вечернее и заочное обучение, корпоративные программы и признание квалификации, полученной вне вуза.

Ответственность при этом переложилась на самого работника: поддержание своей пригодности к работе стало его личной задачей, что для многих обернулось постоянным напряжением.'),
  (572, 2, 'c_mass_culture', 'Массовая культура', 29, 13, 1, NULL, 'Индустрия развлечений: тираж, формат, звезда и всемирный прокат.', 'Массовая культура работает как производство: есть формат, расчёт аудитории, бюджет продвижения и оценка успеха по сборам.

Она перестала быть местной: фильм, песня и сериал расходятся по всему миру одновременно, создавая общий круг узнаваемых образов.

Спор о ней ведётся с самого начала: одни видят упрощение и вытеснение своего чужим, другие — единственную культуру, действительно доступную большинству и вовсе не лишённую качества.'),
  (573, 2, 'c_global_english', 'Мировой английский', 30, 13, 1, NULL, 'Общий язык науки, торговли и сети.', 'Английский стал вспомогательным языком мирового общения не по указу, а по стечению обстоятельств: положение США, наука, авиация, вычислительная техника и развлечения.

Большинство разговоров на нём ведут те, для кого он неродной, и складывается упрощённый международный вариант со своими нормами.

Выигрыш очевиден — общий язык удешевляет всякое взаимодействие; цена тоже: преимущество носителям, вытеснение других языков из науки и утрата малых языков.'),
  (574, 2, 'c_ngos', 'Неправительственные организации', 35, 13, 1, NULL, 'Международные объединения граждан, влияющие на политику государств.', 'Правозащитные, экологические и гуманитарные организации стали самостоятельными участниками международных дел, не будучи ни государствами, ни предприятиями.

Их главное средство — огласка: сбор проверенных сведений и придание их широкой известности оказались действеннее многих дипломатических нот.

Успехи заметны: договоры о запрете противопехотных мин и о защите озонового слоя во многом обязаны их давлению. Вопрос об их собственной подотчётности при этом остаётся.'),
  (575, 2, 'c_multiculturalism', 'Мультикультурализм', 23, 13, 1, NULL, 'Признание за меньшинствами права сохранять язык, обычай и веру.', 'Массовые переселения сделали общества разнородными, и прежняя установка на полное растворение приезжих в принимающей культуре перестала работать.

Мультикультурализм предложил иное: гражданское равенство при сохранении культурного своеобразия, поддержка языков и общин.

Критика шла с двух сторон: одни видели угрозу единству общества, другие — закрепление обособленности и невнимание к правам людей внутри самих общин, прежде всего женщин.'),
  (576, 2, 'c_agglomerations', 'Агломерации', 36, 13, 1, NULL, 'Срастание городов в единые системы расселения на десятки миллионов человек.', 'Агломерация — не большой город, а сросшаяся система городов и пригородов с общими рынком труда, транспортом и хозяйством.

Управлять ею трудно: административные границы не совпадают с действительными связями, и решения о транспорте или жилье приходится согласовывать десяткам муниципалитетов.

В развивающихся странах рост шёл быстрее, чем строилась инфраструктура, и породил огромные самостроенные районы, где живёт значительная часть городского населения мира.'),
  (577, 2, 'c_info_networks', 'Информационные сети', 38, 13, 1, NULL, 'Спутниковое вещание, кабельные каналы и первые сети передачи данных.', 'Спутник сделал вещание всемирным: событие видно одновременно на всех континентах, и государственная монополия на сведения дала первую трещину.

Кабельные каналы раздробили аудиторию: вместо трёх программ для всех появились десятки для разных интересов, и общее поле начало распадаться.

Круглосуточные новостные каналы ввели непрерывное освещение событий, изменив и политику: реагировать приходится немедленно, до того как обстоятельства выяснены.'),
  (578, 2, 'c_ecology_movement', 'Экологическое движение', 40, 13, 1, NULL, 'Природа как ценность и предмет политики.', 'Толчком послужили книги и катастрофы, показавшие, что хозяйственная деятельность способна разрушить среду обитания необратимо.

Движение быстро вышло за пределы протеста: появились партии зелёных, участие в правительствах и понятие устойчивого развития, соединяющее хозяйственные и природоохранные соображения.

Оно же породило постоянный спор о цене: природоохранные меры требуют затрат сегодня ради выигрыша, который получат следующие поколения, а они не участвуют в нынешних решениях.'),
  (579, 2, 'c_sport_industry', 'Спортивная индустрия', 37, 13, 1, NULL, 'Права на трансляцию, спонсоры и спорт как крупное предприятие.', 'Доходы сместились со стадиона на телевидение: продажа прав на показ стала главным источником средств, и это переменило устройство всего спорта.

Под телевидение подстроили расписание, правила и даже длительность перерывов, а спонсорство сделало соревнование ещё и рекламной площадкой.

Деньги обострили старые вопросы: допинг, подкуп судей, торговля игроками и получение права на проведение крупных турниров, вокруг которого сложилась собственная теневая политика.'),
  (580, 2, 'c_info_ethics', 'Информационная этика', 41, 13, 1, NULL, 'Ответственность за достоверность сведений и за их сбор о людях.', 'Способность собирать и сопоставлять сведения о человеке росла быстрее, чем представления о допустимом, и правила приходилось вырабатывать вдогонку.

Сложились основания, ставшие затем законом: сведения собираются для заявленной цели, хранятся не дольше нужного, человек вправе знать, что о нём известно, и требовать исправления.

Одновременно встал вопрос достоверности: у распространителя сведений появляется ответственность, соразмерная охвату, — довод, который станет главным в спорах следующей эпохи.'),
  (581, 2, 'c_e_government', 'Электронное правительство', 33, 14, 1, NULL, 'Государственные услуги и учёт в сети: заявление без очереди и без бумаги.', 'Перевод услуг в сеть изменил отношения человека с ведомством: справка выдаётся мгновенно, а сведения запрашиваются учреждениями друг у друга, а не у гражданина.

Наиболее последовательные примеры дали небольшие страны, построившие цифровую личность, электронную подпись и единый доступ ко всем услугам.

Возникают и новые опасности: сбой или взлом парализует государство целиком, а полный учёт даёт власти возможности наблюдения, которых у неё прежде не было.'),
  (582, 2, 'c_digital_law', 'Цифровое право', 24, 14, 1, NULL, 'Правила сети: ответственность площадок, персональные данные, электронная сделка.', 'Сеть долго считали пространством вне права, но выяснилось, что за каждым действием стоят вполне обычные отношения — договор, вред, собственность.

Ключевым стал вопрос об ответственности площадки за размещённое пользователями: от полного её отсутствия постепенно перешли к обязанности удалять противоправное.

Регулирование персональных данных дало человеку права на согласие, доступ, исправление и удаление сведений о себе, а нарушителям — штрафы, соразмерные обороту.'),
  (583, 2, 'c_online_religion', 'Религиозные сообщества в сети', 26, 14, 1, NULL, 'Богослужение, проповедь и община, существующие в интернете.', 'Сеть изменила религиозную жизнь: проповедь стала доступна всемирно, общины складываются вне прихода, а обряды передаются и совершаются удалённо.

Пандемия ускорила это резко: службы транслировались, и многие впервые задумались, что в обряде требует телесного присутствия, а что нет.

Богословы спорят о существенном: возможна ли община без совместного присутствия и не подменяет ли удобство удалённого участия саму суть религиозной жизни.'),
  (584, 2, 'c_online_rites', 'Онлайн-обряды и цифровая память', 27, 14, 1, NULL, 'Свадьбы, поминовение и памятные страницы в сети.', 'Обряды перешли в сеть вслед за жизнью: страницы памяти умерших, трансляции торжеств, поздравления и соболезнования в общедоступных лентах.

Появилось цифровое наследие: учётные записи, переписка и снимки, которые надо кому-то передать или закрыть, и право лишь начинает это регулировать.

Страница умершего, которую продолжают посещать и на которой оставляют записи, стала новой формой поминовения — не задуманной никем, а сложившейся сама собой.'),
  (585, 2, 'c_transhumanism', 'Трансгуманизм', 28, 14, 1, NULL, 'Улучшение человека техникой как осознанная цель.', 'Трансгуманизм предлагает не лечить человека, а совершенствовать: продлевать жизнь, усиливать способности, преодолевать телесные пределы техникой.

Довод простой: очки, прививки и протезы уже изменяют природное состояние, и принципиальной границы между лечением и улучшением провести не удаётся.

Возражения весомы: улучшения будут доступны состоятельным и закрепят неравенство в самой телесности, а согласия у будущих поколений на такие изменения никто не спрашивает.'),
  (586, 2, 'c_cyberwar', 'Кибервойна', 34, 14, 1, NULL, 'Нападение на сети и управление противника без применения оружия.', 'Атака на сеть способна остановить электростанцию, банк или больницу, не пересекая границы и не убивая напрямую, — и потому плохо укладывается в существующее понятие войны.

Трудность в установлении нападавшего: след легко подделать, и уверенно назвать виновного бывает невозможно, что подрывает всю логику ответного удара.

Отсюда открытый вопрос: считать ли такое нападение вооружённым и допустим ли ответ обычными средствами. Согласия между государствами по этому поводу нет.'),
  (587, 2, 'c_cybersecurity', 'Кибербезопасность', 39, 14, 1, NULL, 'Защита сетей, данных и критической инфраструктуры.', 'Оборона в этой области устроена невыгодно: защищающемуся надо закрыть все уязвимости, нападающему достаточно найти одну.

Самым слабым звеном остаётся человек: обманное письмо и подобранный пароль открывают доступ вернее любой изощрённой уязвимости.

Особую тревогу вызывает промышленное оборудование и городское хозяйство: многие системы проектировались, когда о подключении к сети никто не думал, и защиты в них не предусмотрено вовсе.'),
  (588, 2, 'c_platform_economy', 'Платформенная экономика', 31, 14, 1, NULL, 'Посредник-платформа между исполнителем и заказчиком; работа по заказам.', 'Платформа не производит и не нанимает: она сводит стороны, берёт долю и устанавливает правила, обладая при этом сведениями об обеих.

Для работника это гибкость без гарантий: формально независимый исполнитель на деле подчинён алгоритму, распределяющему заказы и оценивающему его работу.

Суды и законодатели в разных странах приходят к разным ответам на вопрос, считать ли такого исполнителя работником, и от этого зависит судьба целых отраслей.'),
  (589, 2, 'c_remote_work', 'Удалённая работа', 32, 14, 1, NULL, 'Работа вне конторы: связь вместо присутствия.', 'Техническая возможность существовала задолго до массового перехода: препятствием была не связь, а привычка руководителей измерять труд присутствием.

Пандемия сняла это препятствие принудительно, и выяснилось, что значительная часть работы прекрасно выполняется вне конторы.

Последствия оказались широкими: изменился рынок жилья и деловой недвижимости, открылся наём в других странах, но размылась и граница между работой и домом, а новичкам стало труднее входить в дело.'),
  (590, 2, 'c_online_education', 'Онлайн-образование', 25, 14, 1, NULL, 'Курсы, доступные всем: лекция, задание и проверка через сеть.', 'Открытые курсы обещали переворот: лучшие лекции мира становятся доступны любому имеющему связь.

Переворота не вышло: до конца доходили единицы процентов записавшихся, поскольку обучение держится не на доступе к сведениям, а на распорядке, обратной связи и среде.

Устоялось сочетание: сеть берёт на себя изложение и проверку, а живое общение остаётся для разбора, обсуждения и практики — и такая смешанная форма оказалась действительно устойчивой.'),
  (591, 2, 'c_digital_art', 'Цифровое искусство', 29, 14, 1, NULL, 'Произведения, созданные и существующие в цифровой среде.', 'Цифровая среда дала искусству то, чего не было: изменяемость, взаимодействие со зрителем, генеративность и неограниченное тиражирование без потери качества.

Последнее подорвало саму основу художественного рынка, построенного на единственности вещи, и породило попытки искусственно вернуть редкость.

Появление генеративных моделей поставило вопрос ребром: кому принадлежит произведение, созданное по описанию, и на чьих работах обучена сама модель.'),
  (592, 2, 'c_net_language', 'Сетевой язык', 30, 14, 1, NULL, 'Письменная речь как разговор: сокращения, значки, мемы.', 'Переписка в сети породила необычное явление: письмо, ведущее себя как устная речь — быстрое, неформальное, с обозначением интонации.

Значки-эмодзи возместили недостающее в письме: тон, мимику, отношение — то, что в разговоре передаётся голосом и лицом.

Мем стал самостоятельной единицей: образ с изменяемой подписью, понятный только внутри своего круга, работает как пароль принадлежности не хуже прежнего субкультурного знака.'),
  (593, 2, 'c_digital_diplomacy', 'Цифровая дипломатия', 35, 14, 1, NULL, 'Официальные заявления в сетях и борьба за общественное мнение других стран.', 'Дипломатия вышла из кабинетов: заявления делаются публично и мгновенно, минуя посольские каналы, и обращены не столько к правительству, сколько к населению другой страны.

Это ускорило обмен, но снизило возможность отступить: сказанное публично трудно взять назад, а переговоры требуют пространства для уступок.

Тогда же вмешательство в чужие выборы через сети стало признанной угрозой, а разграничение убеждения и вмешательства — предметом трудных международных споров.'),
  (594, 2, 'c_net_communities', 'Сетевые сообщества', 23, 14, 1, NULL, 'Объединения по интересу, не привязанные к месту.', 'Сеть позволила собраться людям, которых на месте единицы: редкая болезнь, узкое занятие, необычные взгляды. Для многих это оказалось спасением от одиночества.

Тот же механизм собирает и тех, чьи взгляды опасны, и придаёт им ощущение нормальности и численности, которого в жизни у них не было.

Устройство лент, подбирающих привычное, усиливает разделение: люди со временем перестают встречать возражения и начинают считать своё мнение общепринятым.'),
  (595, 2, 'c_mobile_society', 'Общество постоянной связи', 23, 14, 1, NULL, 'Непрерывная доступность каждого и переустройство повседневности.', 'Постоянная связь отменила прежние способы координации: договариваться заранее и точно стало не нужно, поскольку всё уточняется по дороге.

Граница между работой и личным временем размылась: доступность по умолчанию означает, что рабочий вопрос настигает где угодно и когда угодно.

Появились и обратные явления: право на отключение, закреплённое в трудовом законодательстве некоторых стран, и сознательные ограничения на пользование устройствами.'),
  (596, 2, 'c_smart_city', 'Умный город', 36, 14, 1, NULL, 'Управление городом по данным: транспорт, энергия, услуги, наблюдение.', 'Датчики и данные позволяют управлять городом точнее: регулировать светофоры по потоку, планировать маршруты по действительным передвижениям, находить утечки в сетях.

Наибольший выигрыш дают неброские вещи — расписание транспорта, вывоз мусора, обслуживание сетей, — а не показные новшества.

Оборотная сторона в том, что тот же набор датчиков и камер образует систему наблюдения, и вопрос о том, кто владеет городскими данными и на что вправе их употребить, стал предметом настоящей политической борьбы.'),
  (597, 2, 'c_social_networks', 'Социальные сети', 38, 14, 1, NULL, 'Каждый — издатель: лента, алгоритм и распространение без редакции.', 'Сети сняли посредника: любой может обратиться к любому числу людей без редакции, типографии и лицензии.

Отбор перешёл к алгоритму, настроенному на удержание внимания, а удерживает внимание лучше всего то, что вызывает сильные чувства, — и это перекосило общественный разговор в сторону возмущения.

Последствия оказались политическими: скорость распространения непроверенных сообщений превысила скорость их опровержения, и общества столкнулись с расхождением представлений о самих фактах.'),
  (598, 2, 'c_techno_optimism', 'Технооптимизм', 40, 14, 1, NULL, 'Вера в то, что техника решит основные затруднения человечества.', 'Технооптимизм исходит из того, что затруднения — от нехватки решений, а не от устройства общества, и потому решаются изобретением.

Доводы за него весомы: продолжительность жизни, бедность, детская смертность и грамотность изменились за столетие к лучшему разительно, и во многом благодаря технике.

Возражение столь же весомо: та же техника создала оружие, способное уничтожить человечество, и изменение климата, а распределение выигрыша от неё определяется не техникой, а политикой.'),
  (599, 2, 'c_digital_populism', 'Цифровой популизм', 40, 14, 1, NULL, 'Обращение к народу через сети в обход печати и партий.', 'Сети позволили политику говорить с избирателем напрямую, минуя газеты и телевидение, а значит, и минуя проверку сказанного редакцией.

Приёмы сложились быстро: короткое яркое высказывание, противопоставление народа и элиты, точное нацеливание сообщений на узкие группы избирателей по их данным.

Действенность оказалась высокой, а последствия для общественного разговора тяжёлыми: спор о том, как соединить свободу слова с достоверностью, остаётся нерешённым.'),
  (600, 2, 'c_esports', 'Киберспорт', 37, 14, 1, NULL, 'Состязания в компьютерных играх с командами, лигами и зрителями.', 'Киберспорт повторил путь обычного спорта за десятилетие: любительские турниры, затем профессиональные команды, лиги, тренеры, контракты и многомиллионная аудитория.

Отличие в том, что площадка принадлежит частной компании: издатель игры может изменить правила состязания обновлением, чего не бывает ни в одном другом виде спорта.

Признание неоднозначно: споры о том, спорт ли это, идут наравне со спорами о здоровье участников и о возрасте зрителей.'),
  (601, 2, 'c_data_privacy', 'Приватность и данные', 41, 14, 1, NULL, 'Право распоряжаться сведениями о себе в мире тотального сбора.', 'Сведения о человеке собираются постоянно и незаметно: перемещения, покупки, запросы, круг общения. По отдельности они безобидны, в совокупности дают исчерпывающий портрет.

Согласие как основание защиты работает плохо: никто не читает соглашений, а отказаться от услуги на деле невозможно.

Поэтому обсуждение сместилось к иным подходам: ограничению самого сбора, запрету определённых способов употребления данных и ответственности собирающего независимо от полученного согласия.'),
  (602, 2, 'c_planetary_governance', 'Планетарное управление', 33, 15, 1, NULL, 'Общие решения по задачам, которые не решаются в границах одной страны.', 'Климат, океан, космос, эпидемии и искусственный интеллект не признают границ: выигрыш от воздержания достаётся всем, а издержки несёт тот, кто воздержался.

Существующие соглашения строятся на добровольности, и потому слабы там, где выгоднее всего нарушить.

Предлагаемые решения расходятся: одни видят выход в усилении всемирных учреждений, другие — в союзах желающих, третьи в том, чтобы делать соблюдение выгодным, а не обязательным.'),
  (603, 2, 'c_ai_rights', 'Права искусственного разума', 24, 15, 1, NULL, 'Вопрос о правовом положении систем, способных действовать самостоятельно.', 'Ближайшая задача не о правах машины, а об ответственности: кто отвечает за вред, причинённый системой, — изготовитель, владелец или тот, кто её обучал.

Предлагаются разные решения: строгая ответственность владельца, обязательное страхование, особый правовой статус наподобие юридического лица.

Вопрос о собственных правах системы возникнет лишь при появлении признаков внутреннего опыта, а надёжного способа их установить у нас нет — и это само по себе тяжёлая философская трудность.'),
  (604, 2, 'c_posthuman_belief', 'Постчеловеческие верования', 26, 15, 1, NULL, 'Религиозные и квазирелигиозные учения вокруг техники и бессмертия.', 'Обещания продления жизни, сохранения сознания и всеведущего разума занимают то же место, что прежде занимали религиозные ожидания, и говорят похожим языком.

Появились и вполне оформленные учения, ожидающие спасения от техники, и противоположные им течения, видящие в ней посягательство на человеческую природу.

Традиционные религии вырабатывают свою позицию: большинство признаёт лечение, но настороженно относится к изменению самой природы человека и к отождествлению личности с записью.'),
  (605, 2, 'c_digital_rites', 'Обряды цифрового бытия', 27, 15, 1, NULL, 'Обряды вокруг перехода, памяти и присутствия в виртуальной среде.', 'Если значительная часть жизни проходит в среде, созданной техникой, обряды перемещаются туда же: принятие в сообщество, признание достижения, прощание.

Появляются устойчивые формы сохранения присутствия умерших: голосовые и текстовые модели, обученные на их переписке и записях.

Психологи и богословы расходятся в оценке: одни видят помощь в переживании утраты, другие — препятствие ему, поскольку прощание оказывается бесконечно отложенным.'),
  (606, 2, 'c_posthumanism', 'Постгуманизм', 28, 15, 1, NULL, 'Пересмотр исключительности человека среди других разумных и живых существ.', 'Постгуманизм ставит под сомнение положение, на котором стояла вся европейская мысль: что человек занимает особое место и является мерой всего.

Поводов достаточно: исследования разума животных, экологический кризис и появление систем, справляющихся с задачами, которые считали исключительно человеческими.

Практические следствия велики: они затрагивают отношение к животным, к природе как к обладателю прав и к искусственным системам — то есть заново ставят вопрос о том, кого мы принимаем в круг тех, с кем считаемся.'),
  (607, 2, 'c_autonomous_armies', 'Автономные армии', 34, 15, 1, NULL, 'Войска из машин, действующих без непосредственного участия человека.', 'Замена людей машинами обещает избавить свою сторону от потерь, и уже это меняет расчёт: война, не стоящая жизней избирателей, встречает меньше внутреннего сопротивления.

Следствие тревожное: снижается порог применения силы, и вооружённое вмешательство становится политически более лёгким решением.

Спор о допустимости упирается в требование сохранить значимый человеческий контроль над решением о применении оружия — понятие, которое все признают и никто не может точно определить.'),
  (608, 2, 'c_total_monitoring', 'Тотальный мониторинг', 39, 15, 1, NULL, 'Сплошное наблюдение и предсказание поведения по данным.', 'Соединение камер, распознавания, данных о перемещениях и покупках даёт возможность наблюдения, невозможного ни для одного государства прошлого, — и притом дешёвого.

Предсказательный подход добавляет к этому неприятную особенность: меры принимаются на основании вероятности, а не совершённого действия, что подрывает презумпцию невиновности.

Тревожит и другое: система обучается на прошлых решениях и потому воспроизводит прежние предубеждения, придавая им вид беспристрастного расчёта.'),
  (609, 2, 'c_abundance_economy', 'Экономика изобилия', 31, 15, 1, NULL, 'Хозяйство, где производство почти не ограничено трудом и сырьём.', 'Если производство обеспечивается автоматикой и дешёвой энергией, привычная хозяйственная задача — распределение недостающего — теряет прежний смысл.

Дефицит при этом не исчезает: остаются земля, редкие материалы, внимание, подлинность и время других людей — то, чего нельзя размножить.

Главный вопрос становится политическим: кому достаётся выигрыш от машин. От ответа зависит, окажется ли изобилие всеобщим или обернётся невиданным неравенством.'),
  (610, 2, 'c_abundance_labor', 'Освобождение от труда', 32, 15, 1, NULL, 'Сокращение необходимого труда и поиск нового источника смысла и дохода.', 'Кейнс предсказывал, что к нашему времени рабочая неделя сократится до пятнадцати часов. Производительность выросла как он предполагал, а часы — нет: выигрыш ушёл в потребление, а не в досуг.

Обсуждаемые ответы — безусловный доход, сокращение недели, общественная собственность на средства автоматизации — расходятся не в оценке техники, а в представлениях о справедливости.

Отдельная трудность нехозяйственная: работа даёт человеку не только доход, но и распорядок, круг общения и признание, и чем их заменить — вопрос открытый.'),
  (611, 2, 'c_knowledge_upload', 'Прямая передача знаний', 25, 15, 1, NULL, 'Обучение через интерфейс: навык без длительного упражнения.', 'Замысел предполагает передачу навыка напрямую в мозг, минуя упражнение. Нынешнее знание о памяти показывает, что это несравнимо труднее, чем кажется: навык распределён по сетям нейронов и неотделим от опыта его приобретения.

Более достижимым выглядит ускорение обучения: обратная связь по состоянию внимания, стимуляция в нужные моменты, подстройка нагрузки под учащегося.

Если же передача окажется возможной, встанет вопрос о ценности пути: многое в образовании даёт не результат, а само усилие его достижения.'),
  (612, 2, 'c_neuro_society', 'Общество нейроинтерфейсов', 23, 15, 1, NULL, 'Последствия прямой связи мозга с машиной для общения и права.', 'Прямое считывание мозговой активности ставит вопрос, которого раньше не было: неприкосновенность мысли. Прежде она обеспечивалась природой, теперь требует защиты.

Уже предлагаются нейроправа: на умственную неприкосновенность, на тождественность личности, на свободу от вмешательства в психику, и отдельные страны вносят их в конституции.

Отдельная забота — неравенство: если усиление способностей окажется доступно не всем, различия между людьми перестанут быть только имущественными.'),
  (613, 2, 'c_synthetic_art', 'Синтетическое искусство', 29, 15, 1, NULL, 'Произведения, создаваемые совместно с генеративными системами.', 'Генеративные системы сместили роль автора: он задаёт направление, отбирает и правит, но не выполняет работу целиком сам.

Спор об авторстве идёт всерьёз: правовые системы разных стран расходятся в том, охраняется ли созданное машиной и кому оно принадлежит.

Более глубокий вопрос — о ценности: если произведение ценно связью с человеческим опытом, то что остаётся от неё, когда работу выполняет система, никакого опыта не имеющая.'),
  (614, 2, 'c_universal_translation', 'Универсальный перевод', 30, 15, 1, NULL, 'Мгновенный перевод речи, снимающий языковой барьер.', 'Качество машинного перевода выросло настолько, что бытовое и деловое общение через него стало обыденностью, а устный синхронный перевод перестал быть редкостью.

Трудности остались там, где язык неотделим от культуры: вежливость, юмор, недосказанность и всё, что понимается из общего опыта, а не из слов.

Последствия двойственны: снятие барьера облегчает общение, но снижает побуждение учить языки, а вместе с этим теряется и способность мыслить в чужой картине мира.'),
  (615, 2, 'c_interplanetary_treaties', 'Межпланетные соглашения', 35, 15, 1, NULL, 'Право и договоры для деятельности за пределами Земли.', 'Договор о космосе объявил небесные тела не подлежащими присвоению и обязал государства отвечать за действия своих граждан в космосе.

Он писался, когда космос был делом двух держав; теперь там действуют десятки стран и частные компании, а вопрос о собственности на добытое остаётся неурегулированным.

Насущны и приземлённые задачи: орбитальный мусор, распределение частот и орбитальных позиций, предотвращение заражения других тел земными организмами.'),
  (616, 2, 'c_extended_identity', 'Расширенная идентичность', 23, 15, 1, NULL, 'Личность, распределённая между телом, сетью и представительствами в средах.', 'Человек всё чаще существует одновременно в нескольких средах, и его облик, имя и круг общения в них могут различаться.

Право пока исходит из единственности личности, тогда как действительность становится сложнее: возникают вопросы о признании цифровых представительств и об ответственности за их действия.

Психологи расходятся: одни видят в множественности угрозу целостности личности, другие — расширение возможностей быть собой там, где среда позволяет.'),
  (617, 2, 'c_orbital_settlements', 'Орбитальные поселения', 36, 15, 1, NULL, 'Постоянные поселения вне Земли и их общественное устройство.', 'Поселение в замкнутой среде ставит вопросы, острые именно из-за малого размера: как принимаются решения, кто распоряжается воздухом и водой, что делать с тем, кто нарушает правила.

Опыт полярных станций и подводных лодок показывает, насколько важны отбор участников, распорядок и разрешение споров в замкнутом коллективе.

Юридическая сторона не проще: чьё право действует в поселении, кому принадлежит произведённое и может ли оно со временем объявить себя самостоятельным.'),
  (618, 2, 'c_immersive_media', 'Иммерсивные среды', 38, 15, 1, NULL, 'Виртуальная и дополненная реальность как повседневная среда.', 'Иммерсивная среда отличается от экрана присутствием: человек не смотрит на изображение, а находится внутри него, и переживание оказывается несравнимо сильнее.

Это ценно для обучения и лечения — тренировка навыков, работа со страхами, реабилитация — и столь же действенно для воздействия на человека.

Отсюда и опасения: если убедительность среды сравняется с действительностью, то различение подлинного и внушённого станет задачей, к которой общество не подготовлено.'),
  (619, 2, 'c_cosmism', 'Космизм', 40, 15, 1, NULL, 'Расселение человечества за пределы Земли как общее дело.', 'Космизм видит смысл в выходе за пределы планеты: и ради сохранения человечества при возможной катастрофе, и ради самого движения вперёд.

Довод о запасной планете оспаривается: сделать Землю пригодной для жизни после любой мыслимой катастрофы всё равно проще, чем обжить Марс.

Возражение звучит и иначе: расходы на космос уместнее направить на насущные земные нужды. Сторонники отвечают, что великие общие задачи двигают науку и объединяют людей сильнее, чем распределение средств.'),
  (620, 2, 'c_augmented_sport', 'Дополненные состязания', 37, 15, 1, NULL, 'Спорт с усилением возможностей: протезы, стимуляция, смешанные виды.', 'Граница между лечением и усилением в спорте стала неопределённой: протез уже позволяет выступать наравне со здоровыми, а в отдельных отношениях и превосходить их.

Обсуждается и обратный ход — состязания без ограничений, где усиление разрешено открыто, что уже осуществляется в отдельных турнирах.

Спор идёт о существе спорта: если он о пределах человеческих возможностей, то усиление его разрушает; если о зрелище и совершенстве, то нет.'),
  (621, 2, 'c_ai_ethics', 'Этика искусственного разума', 41, 15, 1, NULL, 'Согласование целей систем с человеческими и ответственность за их решения.', 'Основная опасность видится не в злом умысле машины, а в буквальном исполнении неточно поставленной цели: система достигает заданного, разрушая то, что мы забыли оговорить.

Отсюда работа над согласованием целей, объяснимостью решений и возможностью остановить систему — задачи технические лишь отчасти.

Ближайшие вопросы приземлённее: воспроизведение предубеждений при обучении на прошлых данных, ответственность за врачебное или судебное решение и допустимость передачи машине решений о жизни человека.'),
  (622, 2, 'c_planetary_ethics', 'Планетарная ответственность', 41, 15, 1, NULL, 'Обязательства перед будущими поколениями и перед планетой как целым.', 'Действия нынешних поколений определяют условия жизни тех, кто ещё не родился и потому не участвует в решениях. Обычные политические механизмы этого не учитывают: избиратель и предприятие считают на годы, а последствия измеряются веками.

Предлагаются учреждения, представляющие интересы будущих поколений: уполномоченные, обязательная оценка долгосрочных последствий, закрепление обязанностей в конституциях.

Сюда же относится и вопрос об обязанностях перед природой как таковой: ряд стран уже признал права рек и экосистем в качестве самостоятельных субъектов.'),
  (623, 2, 'c_algorithmic_governance', 'Управление алгоритмами', 33, 15, 1, NULL, 'Надзор за системами, принимающими решения о людях.', 'Всё больше решений — о кредите, найме, лечении, надзоре — принимается или подготавливается системами, и человек оказывается перед ответом, который никто не может объяснить.

Отсюда требования: право на объяснение решения, право на пересмотр человеком, проверка систем на предвзятость и запрет отдельных применений вовсе.

Складывается и порядок надзора по степени риска: чем тяжелее последствия для человека, тем строже требования к системе и к тому, кто её применяет.');

